                    boxShadow: activeAgent === i ? `0 0 0 3px ${agent.glowColor}, 0 8px 25px ${agent.glowColor}` : 'none',
                    transform: activeAgent === i ? 'scale(1.04)' : 'scale(1)'
                  }}
                  onMouseEnter={(e) => {
                    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
                    e.currentTarget.style.boxShadow = `0 0 0 3px ${agent.glowColor}, 0 8px 25px ${agent.glowColor}`;
                    e.currentTarget.style.transform = 'scale(1.04)';
                  }}
                  onMouseLeave={(e) => {
                    if (activeAgent !== i) {
                      e.currentTarget.style.boxShadow = 'none';
                      e.currentTarget.style.transform = 'scale(1)';
                    }
                  }}
                >
                  <span className={cn("text-[10px] font-bold leading-none mb-1 opacity-80", agent.textColor)}>0{i+1}</span>
                  <agent.icon className={cn("w-[18px] h-[18px] transition-transform duration-250 motion-safe:group-hover:-translate-y-0.5", agent.textColor)} />
                </div>

                {/* Connector Line (Desktop) */}
                {i < pipelineAgents.length - 1 && (
                  <div className="hidden md:block absolute top-[29px] left-[55%] w-[90%] h-[1px] bg-muted z-0 overflow-hidden pointer-events-none">
                    <motion.div 
                      className={cn("h-full w-1/3 bg-gradient-to-r from-transparent to-current opacity-60 motion-reduce:hidden", agent.textColor)}
                      animate={{ x: ["-100%", "300%"] }}
                      transition={{ repeat: Infinity, duration: 3, delay: i * 0.4, ease: "linear" }}
                      style={{ filter: "blur(2px)" }}
                    />
                  </div>
                )}
                {/* Vertical Connector (Mobile) */}
                {i < pipelineAgents.length - 1 && (
                  <div className="md:hidden w-[1px] h-4 bg-muted my-2" />
                )}

                {/* Info */}
                <div className="text-center mt-3 flex flex-col items-center flex-1">
                  <span className="text-[12px] font-bold tracking-[0.04em] text-foreground uppercase transition-colors group-hover:text-foreground">{agent.name}</span>
                  <span className="text-[11px] leading-[1.4] text-muted-foreground mt-1 max-w-[100px] transition-colors group-hover:text-foreground">{agent.shortDesc}</span>
                </div>
              </motion.div>
            ))}
          </motion.div>

          {/* Active Detail Panel */}
          <AnimatePresence>
            {activeAgent !== null && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: "auto", opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.3 }}
                className="overflow-hidden mt-8 md:mt-10"
              >
                <div className={cn(
                  "p-5 md:p-6 rounded-xl border bg-card flex flex-col md:flex-row gap-6 md:gap-10",
                  pipelineAgents[activeAgent].borderColor,
                  pipelineAgents[activeAgent].bgColor
                )}>
                  <div className="flex-1">
                    <h4 className={cn("font-bold text-[14px] md:text-[15px] mb-2 uppercase tracking-wide flex items-center gap-2", pipelineAgents[activeAgent].textColor)}>
                      {React.createElement(pipelineAgents[activeAgent].icon, { className: "w-4 h-4" })}
                      {pipelineAgents[activeAgent].name} Agent
                    </h4>
                    <p className="text-[13px] md:text-sm text-muted-foreground leading-relaxed">
                      {pipelineAgents[activeAgent].purpose}
                    </p>
                  </div>
                  <div className="flex-1 grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <span className="block text-[11px] font-bold text-muted-foreground uppercase tracking-wider mb-1">Input</span>
                      <span className="text-foreground font-medium text-[13px]">{pipelineAgents[activeAgent].input}</span>
                    </div>
                    <div>
                      <span className="block text-[11px] font-bold text-muted-foreground uppercase tracking-wider mb-1">Output</span>
                      <span className="text-foreground font-medium text-[13px]">{pipelineAgents[activeAgent].output}</span>
                    </div>
                    <div className="col-span-2 pt-2 border-t border-border-subtle">
                      <span className="block text-[11px] font-bold text-muted-foreground uppercase tracking-wider mb-1">Next Stage</span>
                      <span className="text-foreground font-medium text-[13px]">{pipelineAgents[activeAgent].next}</span>
                    </div>
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">

          {/* ΓöÇΓöÇ LEFT COL: FAQ & Troubleshooting ΓöÇΓöÇ */}
          <div className="lg:col-span-2 space-y-10">

            <section id="faq" className="space-y-6">
              <h3 className="text-xl font-bold tracking-tight border-b pb-2 border-border">Frequently Asked Questions</h3>
              <div className="space-y-3">
                {faqs.map((faq, i) => (
                  <div key={i} className="bg-card border border-border rounded-xl overflow-hidden transition-all hover:border-border">
                    <button 
                      onClick={() => setOpenFaq(openFaq === i ? null : i)}
                      className="w-full flex items-center justify-between p-4 text-left focus:outline-none focus-visible:bg-surface"
                      aria-expanded={openFaq === i}
                    >
                      <span className="font-semibold text-sm text-foreground">{faq.q}</span>
                      <ChevronDown className={cn("w-4 h-4 text-muted-foreground transition-transform duration-200 shrink-0", openFaq === i ? "rotate-180" : "")} />
                    </button>
                    <AnimatePresence initial={false}>
                      {openFaq === i && (
                        <motion.div
                          initial={{ height: 0, opacity: 0 }}
                          animate={{ height: "auto", opacity: 1 }}
                          exit={{ height: 0, opacity: 0 }}
                          transition={{ duration: 0.2 }}
                          className="overflow-hidden bg-surface/50"
                        >
                          <div className="p-4 pt-1 text-[13px] text-muted-foreground leading-relaxed border-t border-border-subtle">
                            {faq.a}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </section>

            <section id="troubleshooting" className="space-y-6">
              <h3 className="text-xl font-bold tracking-tight border-b pb-2 border-border flex items-center gap-2">
                <Wrench className="w-5 h-5 text-muted-foreground" /> Troubleshooting
              </h3>
              <div className="space-y-3">
                {troubleshooting.map((t, i) => (
                  <div key={i} className="bg-card border border-border rounded-xl overflow-hidden transition-all hover:border-amber-200 focus-within:border-amber-300 shadow-sm">
                    <button 
                      onClick={() => setOpenTrouble(openTrouble === i ? null : i)}
                      className="w-full flex items-center justify-between p-4 text-left focus:outline-none"
                    >
                      <div className="flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full bg-amber-500" />
                        <span className="font-semibold text-sm text-foreground">{t.title}</span>
                      </div>
                      <ChevronDown className={cn("w-4 h-4 text-muted-foreground transition-transform duration-200", openTrouble === i ? "rotate-180" : "")} />
                    </button>
                    <AnimatePresence initial={false}>
                      {openTrouble === i && (
                        <motion.div
                          initial={{ height: 0, opacity: 0 }}
                          animate={{ height: "auto", opacity: 1 }}
                          exit={{ height: 0, opacity: 0 }}
                          transition={{ duration: 0.2 }}
                          className="overflow-hidden bg-amber-50/30"
                        >
                          <div className="p-4 pt-0 text-[13px] border-t border-amber-100/50 mt-2 space-y-3">
                            <div>
                              <span className="font-semibold text-foreground block mb-1">Possible Causes:</span>
                              <span className="text-muted-foreground">{t.causes}</span>
                            </div>
                            <div>
                              <span className="font-semibold text-foreground block mb-1">Steps to resolve:</span>
                              <span className="text-muted-foreground">{t.steps}</span>
                            </div>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </section>

          </div>

          {/* ΓöÇΓöÇ RIGHT COL: Support, Status, Shortcuts ΓöÇΓöÇ */}
          <div className="space-y-6">

            {/* Contact Support */}
            <section id="support" className="bg-card border border-border rounded-2xl p-6 shadow-sm relative overflow-hidden">
              <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-indigo-500" />
              <h3 className="text-lg font-bold text-foreground flex items-center gap-2">
                <MessageCircle className="w-5 h-5 text-primary" /> Still need help?
              </h3>
              <p className="text-[13px] text-muted-foreground mt-2 mb-5">
                Can't find what you're looking for? Send us a message and we'll help you troubleshoot the issue.
              </p>

              <form onSubmit={handleSupportSubmit} className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-foreground">Category</label>
                  <select 
                    value={supportForm.category}
                    onChange={e => setSupportForm({...supportForm, category: e.target.value})}
                    className="w-full bg-surface border border-border rounded-lg text-sm px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-primary transition-all"
                  >
                    <option value="general">General Support</option>
                    <option value="bug">Report a Bug</option>
                    <option value="feedback">Send Feedback</option>
                    <option value="billing">Account & Billing</option>
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-foreground">Subject</label>
                  <input 
                    required
                    value={supportForm.subject}
                    onChange={e => setSupportForm({...supportForm, subject: e.target.value})}
                    placeholder="Brief description"
                    className="w-full bg-surface border border-border rounded-lg text-sm px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-primary transition-all"
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-foreground">Description</label>
                  <textarea 
                    required
                    value={supportForm.description}
                    onChange={e => setSupportForm({...supportForm, description: e.target.value})}
                    placeholder="How can we help?"
                    rows={3}
                    className="w-full bg-surface border border-border rounded-lg text-sm px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-primary transition-all resize-none"
                  />
                </div>
                <button 
                  disabled={supportStatus === "loading" || supportStatus === "success"}
                  type="submit" 
                  className={cn(
                    "w-full flex items-center justify-center gap-2 py-2 rounded-lg text-sm font-semibold text-white transition-all",
                    supportStatus === "idle" || supportStatus === "error" ? "bg-primary hover:bg-primary/90 shadow-sm" : 
                    supportStatus === "loading" ? "bg-primary/70 cursor-wait" : "bg-success"
                  )}
                >
                  {supportStatus === "idle" && <><Send className="w-4 h-4" /> Send Message</>}
                  {supportStatus === "loading" && <span className="flex items-center gap-2"><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> Sending...</span>}
                  {supportStatus === "success" && <><CheckCircle2 className="w-4 h-4" /> Submitted Γ£ô</>}
                  {supportStatus === "error" && <><XCircle className="w-4 h-4" /> Failed ΓÇö Try Again</>}
                </button>
              </form>
            </section>

            {/* System Status */}
            <section id="status" className="bg-card border border-border rounded-2xl p-5 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-[15px] font-bold text-foreground">AstraFinance Systems</h3>
                <div className="flex items-center gap-1.5 px-2 py-1 bg-success/10 text-success border border-emerald-100 rounded-md text-[10px] font-bold uppercase tracking-wider">
                  <span className="w-1.5 h-1.5 rounded-full bg-success animate-pulse" /> Operational
                </div>
              </div>
              <div className="space-y-3">
                {[
                  "Frontend Application", 
                  "Backend API", 
                  "AI Orchestration", 
                  "Document Processing", 
                  "Report Generation"
                ].map(service => (
                  <div key={service} className="flex items-center justify-between text-sm border-b border-slate-50 last:border-0 pb-2 last:pb-0">
                    <span className="text-muted-foreground font-medium text-[13px]">{service}</span>
                    <span className="text-success"><CheckCircle2 className="w-4 h-4" /></span>
                  </div>
                ))}
              </div>
            </section>


          </div>
        </div>
      </div>

      {/* ΓöÇΓöÇ COMMAND PALETTE OVERLAY ΓöÇΓöÇ */}
      <AnimatePresence>
        {showCommandPalette && (
          <>
            <motion.div 
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              className="fixed inset-0 bg-background/80 backdrop-blur-sm z-50"
              onClick={() => setShowCommandPalette(false)}
            />
            <motion.div 
              initial={{ opacity: 0, scale: 0.95, y: -20, x: "-50%" }} 
              animate={{ opacity: 1, scale: 1, y: 0, x: "-50%" }} 
              exit={{ opacity: 0, scale: 0.95, y: -20, x: "-50%" }}
              transition={{ duration: 0.15, ease: "easeOut" }}
              className="fixed top-[15%] left-1/2 w-full max-w-2xl bg-card rounded-xl shadow-2xl border border-border z-50 overflow-hidden flex flex-col max-h-[70vh]"
            >
              <div className="flex items-center px-4 py-3 border-b border-border-subtle">
                <Search className="w-5 h-5 text-primary shrink-0" />
                <input 
                  autoFocus
                  type="text" 
                  value={searchQuery}
                  onChange={e => setSearchQuery(e.target.value)}
                  placeholder="Search help topics, FAQs..."
                  className="flex-1 bg-transparent border-none outline-none px-3 text-[15px] font-medium text-foreground placeholder:text-muted-foreground"
                />
                <button 
                  onClick={() => setShowCommandPalette(false)}
                  className="p-1 hover:bg-surface rounded-md text-muted-foreground hover:text-foreground transition-colors"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="overflow-y-auto p-2 flex-1 custom-scrollbar">
                {searchQuery.trim() === "" ? (
                  <div className="py-12 text-center">
                    <Command className="w-10 h-10 text-slate-200 mx-auto mb-3" />
                    <p className="text-sm font-semibold text-muted-foreground">Start typing to search</p>
                    <p className="text-xs text-muted-foreground mt-1">Search for reports, agents, workspaces, or settings.</p>
                  </div>
                ) : filteredResults.length > 0 ? (
                  <div className="space-y-1">
                    <div className="px-3 py-1.5 text-xs font-semibold text-muted-foreground uppercase tracking-wider">Results</div>
                    {filteredResults.map((res, i) => (
                      <button 
                        key={i}
                        className="w-full text-left flex flex-col gap-1 px-3 py-2.5 rounded-lg hover:bg-primary/10 focus:bg-primary/10 focus:outline-none transition-colors group"
                        onClick={() => setShowCommandPalette(false)}
                      >
                        <div className="flex items-center justify-between">
                          <span className="text-sm font-semibold text-foreground group-hover:text-primary">{res.title}</span>
                          <span className="text-[10px] font-bold bg-surface text-muted-foreground px-1.5 py-0.5 rounded">{res.type}</span>
                        </div>
                        <span className="text-[12px] text-muted-foreground truncate">{res.text}</span>
                      </button>
                    ))}
                  </div>
                ) : (
                  <div className="py-12 text-center">
                    <p className="text-sm font-semibold text-foreground">No results found</p>
                    <p className="text-xs text-muted-foreground mt-1">We couldn't find anything matching "{searchQuery}"</p>
                  </div>
                )}
              </div>
              <div className="bg-surface px-4 py-2 border-t border-border-subtle text-[11px] text-muted-foreground font-medium flex items-center gap-3">
                <span className="flex items-center gap-1"><kbd className="bg-card border rounded px-1 shadow-sm">Γåæ</kbd><kbd className="bg-card border rounded px-1 shadow-sm">Γåô</kbd> to navigate</span>
                <span className="flex items-center gap-1"><kbd className="bg-card border rounded px-1 shadow-sm">Enter</kbd> to select</span>
                <span className="flex items-center gap-1"><kbd className="bg-card border rounded px-1 shadow-sm">Esc</kbd> to close</span>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useAuth } from "@/components/providers/AuthProvider";
import { signOut } from "firebase/auth";
import { auth } from "@/lib/firebase";
import { cn } from "@/lib/utils";
import { 
  DashboardIcon, 
  FolderSharedIcon, 
  DescriptionIcon, 
  SettingsIcon, 
  HelpOutlineIcon, 
  SecurityIcon,
  MenuIcon,
  NotificationsIcon,
  AddIcon
} from "@/components/dashboard/icons";

import { UserProfilePanel } from "@/components/dashboard/UserProfilePanel";
import { NotificationsPanel } from "@/components/layout/NotificationsPanel";
import { ChevronDown, Loader2 } from "lucide-react";
import { fetcher } from "@/lib/api";
import { ThemeToggle } from "@/components/ui/theme-toggle";
import { useNotificationStore } from "@/hooks/useNotificationStore";
import { NotificationProvider } from "@/components/providers/NotificationProvider";
export default function AppLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const { user, dbUser, loading } = useAuth();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  
  const unreadCount = useNotificationStore(state => state.unreadCount);
  
  useEffect(() => {
    if (!loading && !user) {
      window.location.href = "/login";
    }
  }, [user, loading, router]);

  if (loading || !user) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-surface">
        <Loader2 className="w-8 h-8 text-primary animate-spin mb-4" />
        <p className="text-muted-foreground font-medium">Authenticating...</p>
      </div>
    );
  }

  const userName = dbUser?.name || user?.displayName || "Vivek Chaurasiya";

  const navItems = [
    { name: "Dashboard", href: "/dashboard", icon: DashboardIcon },
    { name: "Workspaces", href: "/workspace", icon: FolderSharedIcon },
    { name: "Reports", href: "/reports", icon: DescriptionIcon },
    { name: "Settings", href: "/settings", icon: SettingsIcon },
  ];

  return (
    <NotificationProvider>
    <div className="bg-background text-foreground font-sans min-h-screen flex">
      {/* Mobile Sidebar Overlay */}
      {mobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 md:hidden transition-opacity" 
          onClick={() => setMobileMenuOpen(false)}
        />
      )}

      {/* SideNavBar */}
      <nav className={cn(
        "bg-background h-screen fixed left-0 top-0 shadow-sm flex flex-col p-4 gap-2 z-50 border-r border-border transition-all duration-300",
        mobileMenuOpen ? "flex translate-x-0 w-64" : "hidden md:flex md:translate-x-0",
        !mobileMenuOpen && isSidebarCollapsed ? "md:w-[72px]" : "md:w-64"
      )}>
        <div className="flex flex-col gap-2 mb-8 px-1">
          <div className="flex items-center gap-3 py-2">
            <div className="w-8 h-8 rounded-xl bg-primary shadow-[0_4px_14px_0_rgb(37,99,235,0.39)] flex items-center justify-center overflow-hidden shrink-0">
              <span className="text-white font-bold text-sm tracking-tighter">AF</span>
            </div>
            {(!isSidebarCollapsed || mobileMenuOpen) && (
              <div className="transition-opacity duration-300 whitespace-nowrap overflow-hidden">
                <div className="text-[15px] font-bold text-foreground tracking-tight leading-none mb-1">AstraFinance AI</div>
                <div className="text-[10px] font-semibold tracking-widest text-muted-foreground uppercase leading-none">Intelligence</div>
              </div>
            )}
          </div>
          <Link 
            href="/workspace/create" 
            suppressHydrationWarning 
            className="bg-primary/10 border border-primary/30 text-primary w-full h-9 rounded-lg mt-4 hover:bg-primary/20 hover:border-primary/50 transition-all shadow-sm flex items-center justify-center gap-2 overflow-hidden hover:-translate-y-0.5 backdrop-blur-sm"
          >
            <AddIcon className="w-4 h-4 shrink-0" />
            {(!isSidebarCollapsed || mobileMenuOpen) && <span className="text-sm font-semibold whitespace-nowrap">New Analysis</span>}
          </Link>
        </div>

        <div className="flex flex-col gap-1.5 flex-1 mt-2">
          {navItems.map((item) => {
            const isActive = pathname === item.href || pathname.startsWith(`${item.href}/`);
            return (
              <Link
                key={item.name}
                href={item.href}
                onClick={() => setMobileMenuOpen(false)}
                className={cn(
                  "rounded-xl flex items-center gap-3 px-3 py-2.5 transition-all duration-200 group relative",
                  isActive
                    ? "bg-primary/10 text-primary font-semibold transition-theme"
                    : "text-muted-foreground hover:bg-surface hover:text-foreground transition-theme"
                )}
              >
                {isActive && (
                  <div className="absolute left-0 w-1 h-5 bg-primary rounded-r-full transition-theme" />
                )}
                <item.icon className={cn("w-5 h-5 shrink-0 transition-all", isActive ? "text-primary" : "text-muted-foreground group-hover:text-foreground")} />
                {(!isSidebarCollapsed || mobileMenuOpen) && <span className="truncate whitespace-nowrap text-[13px] tracking-wide transition-theme">{item.name}</span>}
              </Link>
            );
          })}
        </div>

        <div className="flex flex-col gap-1 mt-auto pt-4 border-t border-border-subtle">
          <Link
            href="/help"
            className="text-muted-foreground hover:bg-surface hover:text-foreground transition-all duration-200 rounded-xl flex items-center gap-3 px-3 py-2.5 overflow-hidden group"
          >
            <HelpOutlineIcon className="w-5 h-5 shrink-0 text-muted-foreground group-hover:text-foreground transition-theme" />
            {(!isSidebarCollapsed || mobileMenuOpen) && <span className="text-[13px] font-medium whitespace-nowrap tracking-wide transition-theme">Help & Support</span>}
          </Link>
          <button suppressHydrationWarning
            onClick={() => signOut(auth).then(() => window.location.href = "/login")}
            className="text-muted-foreground hover:bg-destructive/10 hover:text-destructive transition-all duration-200 rounded-xl flex items-center gap-3 px-3 py-2.5 w-full text-left overflow-hidden group"
          >
            <SecurityIcon className="w-5 h-5 shrink-0 text-muted-foreground group-hover:text-destructive transition-theme" />
            {(!isSidebarCollapsed || mobileMenuOpen) && <span className="text-[13px] font-medium whitespace-nowrap tracking-wide transition-theme">Sign Out</span>}
          </button>
        </div>
      </nav>

      {/* Main Content Area */}
      <main className={cn(
        "flex-1 flex flex-col min-h-screen pb-16 md:pb-0 relative transition-all duration-300 min-w-0 w-full",
        isSidebarCollapsed ? "md:ml-[72px] md:w-[calc(100%-72px)]" : "md:ml-64 md:w-[calc(100%-256px)]"
      )}>
        
        {/* Global Desktop Header */}
        <header className="hidden md:flex justify-between items-center px-8 py-4 z-30 sticky top-0 bg-background/80 backdrop-blur-sm">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
              className="p-2 -ml-2 rounded-lg text-muted-foreground hover:bg-surface hover:text-foreground transition-colors"
            >
              <MenuIcon className="w-5 h-5" />
            </button>
          </div>
          <div className="flex items-center gap-6 relative">
            <ThemeToggle />
            <button 
              suppressHydrationWarning 
              onClick={() => { setNotificationsOpen(!notificationsOpen); setProfileOpen(false); }}
              className="text-muted-foreground hover:text-blue-900 transition-colors relative">
              <NotificationsIcon className="w-6 h-6" />
              {unreadCount > 0 && (
                <span className="absolute -top-1 -right-1 w-4 h-4 bg-destructive text-white text-[9px] font-bold flex items-center justify-center rounded-full border-2 border-white shadow-sm">
                  {unreadCount > 9 ? "9+" : unreadCount}
                </span>
              )}
            </button>
            <button suppressHydrationWarning 
              onClick={() => setProfileOpen(!profileOpen)}
              className="flex items-center gap-3 hover:bg-primary/10 px-2 py-1.5 rounded-lg transition-colors border border-transparent hover:border-border"
            >
              {dbUser?.profile_picture ? (
                <img src={dbUser.profile_picture} alt="Profile" className="w-8 h-8 rounded-full object-cover" />
              ) : (
                <div className="w-8 h-8 rounded-full bg-primary/20 text-primary flex items-center justify-center font-semibold text-sm transition-theme">
                  {userName.charAt(0)}
                </div>
              )}
              <span className="text-sm font-medium text-foreground transition-theme">{userName}</span>
              <ChevronDown className="w-4 h-4 text-muted-foreground transition-theme" />
            </button>
          </div>
          {profileOpen && (
            <UserProfilePanel 
              onClose={() => setProfileOpen(false)} 
              onSignOut={() => signOut(auth).then(() => window.location.href = "/login")} 
            />
          )}
          {notificationsOpen && (
            <NotificationsPanel 
              onClose={() => setNotificationsOpen(false)}
            />
          )}
        </header>

        {/* TopAppBar Mobile */}
        <header className="w-full top-0 sticky bg-card border-b border-border shadow-sm z-30 md:hidden flex justify-between items-center px-6 h-16">
          <div className="flex items-center gap-2">
            <img
              alt="Company Logo"
              className="w-10 h-10 object-contain transition-theme"
              src="/logo.svg"
            />
            <span className="text-lg font-bold text-foreground transition-theme">AstraFinance AI</span>
          </div>
          <div className="flex gap-4 items-center relative">
            <ThemeToggle />
            <button 
              suppressHydrationWarning 
              className="relative" 
              onClick={() => { setNotificationsOpen(!notificationsOpen); setProfileOpen(false); }}>
              <NotificationsIcon className="w-6 h-6 text-muted-foreground" />
              {unreadCount > 0 && (
                <span className="absolute -top-1 -right-1 w-4 h-4 bg-destructive text-white text-[9px] font-bold flex items-center justify-center rounded-full border-2 border-white shadow-sm">
                  {unreadCount > 9 ? "9+" : unreadCount}
                </span>
              )}
            </button>
            <button suppressHydrationWarning onClick={() => setMobileMenuOpen(!mobileMenuOpen)}>
              <MenuIcon className="w-6 h-6 text-muted-foreground" />
            </button>
          </div>
        </header>
        {profileOpen && (
           <div className="md:hidden">
             <UserProfilePanel 
               onClose={() => setProfileOpen(false)} 
               onSignOut={() => signOut(auth).then(() => window.location.href = "/login")} 
             />
           </div>
        )}

        {/* Content */}
        {children}

      </main>

      {/* BottomNavBar Mobile */}
      <nav className="md:hidden fixed bottom-0 w-full bg-card border-t border-border flex justify-around items-center h-16 z-40 pb-safe shadow-[0_-2px_10px_rgba(0,0,0,0.05)]">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.name}
              href={item.href}
              className={cn(
                "flex flex-col items-center justify-center w-full h-full",
                isActive ? "text-primary" : "text-muted-foreground"
              )}
            >
              <item.icon className={cn("w-6 h-6", isActive && "fill-current")} />
              <span className="text-[10px] font-bold uppercase tracking-wider mt-1">{item.name}</span>
            </Link>
          );
        })}
      </nav>
    </div>
    </NotificationProvider>
  );
}

"use client";

import { useState, useEffect, useCallback, useMemo } from "react";
import { useRouter } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import {
  FileBarChart2,
  Search,
  ChevronDown,
  Calendar,
  Filter,
  List,
  LayoutGrid,
  Plus,
  BookOpen,
  FileText,
  Layers
} from "lucide-react";
import { cn } from "@/lib/utils";
import { fetcher } from "@/lib/api";
import GenerateReportModal from "@/components/reports/GenerateReportModal";
import ReportCard, { Report } from "@/components/reports/ReportCard";
import EmptyState from "@/components/reports/EmptyState";
import DeleteDialog from "@/components/reports/DeleteDialog";
import RenameDialog from "@/components/reports/RenameDialog";
import debounce from "lodash/debounce";
import toast from "react-hot-toast";

export default function GlobalReportsLibraryPage() {
  const router = useRouter();

  const [reports, setReports] = useState<Report[]>([]);
  const [metrics, setMetrics] = useState({
    total_reports: 0,
    total_versions: 0,
    total_workspaces: 0,
    storage_used: "0 MB"
  });
  const [loading, setLoading] = useState(true);
  const [showGenerateModal, setShowGenerateModal] = useState(false);
  const [view, setView] = useState<"table" | "grid">("grid");

  // Filter States
  const [searchQuery, setSearchQuery] = useState("");
  const [activeWorkspace, setActiveWorkspace] = useState("all");
  const [activeSort, setActiveSort] = useState("latest");
  const [workspaces, setWorkspaces] = useState<{id: string, name: string}[]>([]);

  // Action Modals State
  const [deleteDialog, setDeleteDialog] = useState<{isOpen: boolean, id: string, name: string}>({ isOpen: false, id: "", name: "" });
  const [renameDialog, setRenameDialog] = useState<{isOpen: boolean, id: string, name: string}>({ isOpen: false, id: "", name: "" });

  const load = useCallback(async (search: string, workspace: string, sort: string) => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (search) params.append("search", search);
      if (workspace && workspace !== "all") params.append("workspace", workspace);
      if (sort) params.append("sort", sort);

      const res = await fetcher<{ reports: Report[], metrics: any }>(`/reports?${params.toString()}`);
      setReports(res.reports || []);

      if (res.metrics) {
        setMetrics(res.metrics);
      }

      // Extract unique workspaces for filter dropdown
      const uniqueWs = new Map();
      res.reports?.forEach(r => uniqueWs.set(r.workspace_id, r.workspace_name));
      setWorkspaces(Array.from(uniqueWs.entries()).map(([id, name]) => ({ id, name })));

    } catch (e) {
      console.error(e);
      toast.error("Failed to load reports");
    } finally {
      setLoading(false);
    }
  }, []);

  // Debounced search
  const debouncedSearch = useMemo(
    () => debounce((q, w, s) => load(q, w, s), 300),
    [load]
  );

  useEffect(() => {
    debouncedSearch(searchQuery, activeWorkspace, activeSort);
    return () => debouncedSearch.cancel();
  }, [searchQuery, activeWorkspace, activeSort, debouncedSearch]);

  const handlePreview = (workspaceId: string, reportId: string) => {
    router.push(`/workspace/${workspaceId}/reports/${reportId}`);
  };

  const handleDownload = async (reportId: string, versionId: string) => {
    try {
      toast.loading("Downloading report...", { id: "download" });
      const token = localStorage.getItem("astra_token");
      const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000/api/v1'}/reports/${reportId}/download?version_id=${versionId}`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });

      if (!res.ok) throw new Error("Download failed");

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `Report_${reportId}.pdf`; // The server sets the filename in Content-Disposition as well
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
      toast.success("Download complete", { id: "download" });
    } catch (e) {
      toast.error("Failed to download report", { id: "download" });
    }
  };

  const handleRenameConfirm = async (newName: string) => {
    try {
      await fetcher(`/reports/${renameDialog.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ title: newName })
      });
      toast.success("Report renamed successfully");
      load(searchQuery, activeWorkspace, activeSort);
    } catch (e) {
      toast.error("Failed to rename report");
      throw e; // Let the dialog handle loading state
    }
  };

  const handleDeleteConfirm = async () => {
    try {
      await fetcher(`/reports/${deleteDialog.id}`, {
        method: 'DELETE'
      });
      toast.success("Report deleted successfully");
      load(searchQuery, activeWorkspace, activeSort);
    } catch (e) {
      toast.error("Failed to delete report");
      throw e;
    }
  };

  const handleRegenerate = async (reportId: string) => {
    try {
      toast.loading("Regenerating report...", { id: "regen" });
      await fetcher(`/reports/${reportId}/regenerate`, {
        method: 'POST'
      });
      toast.success("Report regenerated successfully", { id: "regen" });
      load(searchQuery, activeWorkspace, activeSort);
    } catch (e) {
      toast.error("Failed to regenerate report", { id: "regen" });
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-background/50 min-h-full overflow-hidden font-sans">
      <div className="flex-1 max-w-[1400px] w-full mx-auto px-6 py-6 md:px-8 md:py-8 overflow-y-auto">

        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
          <div>
            <h1 className="text-3xl font-bold text-foreground tracking-tight">Reports</h1>
            <p className="text-sm text-muted-foreground mt-1.5">Manage, preview, and download your AI-generated financial reports.</p>
          </div>
          <div className="flex items-center gap-3">
            <div className="flex items-center bg-card border border-border rounded-lg p-1 shadow-sm shrink-0">
              <button 
                onClick={() => setView("grid")}
                className={cn("flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-colors", view === "grid" ? "bg-surface text-foreground" : "text-muted-foreground hover:text-foreground")}
              >
                <LayoutGrid className="w-4 h-4" /> Grid
              </button>
              <button 
                onClick={() => setView("table")}
                className={cn("flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-colors", view === "table" ? "bg-surface text-foreground" : "text-muted-foreground hover:text-foreground")}
              >
                <List className="w-4 h-4" /> List
              </button>
            </div>
            <button 
              onClick={() => setShowGenerateModal(true)}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white hover:bg-blue-700 text-sm font-medium rounded-lg shadow-sm transition-colors shrink-0"
            >
              <Plus className="w-4 h-4" /> New Report
            </button>
          </div>
        </div>

        {/* Library Stats */}
        <div className="mb-8">
          <h2 className="text-[20px] font-bold text-foreground mb-6">Library Overview</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

            {/* Stat 1: Total Reports */}
            <div className="bg-blue-500/5 border border-blue-500/20 rounded-[16px] p-6 flex justify-between items-center shadow-sm hover:shadow-md transition-shadow group cursor-pointer">
              <div className="flex flex-col gap-1.5">
                <h3 className="text-[12px] font-bold text-blue-500 uppercase tracking-widest">Total Reports</h3>
                <div className="text-[24px] font-black text-foreground leading-none">{metrics.total_reports}</div>
              </div>
              <div className="w-[46px] h-[46px] rounded-[14px] bg-card border border-blue-500/20 flex items-center justify-center shrink-0 shadow-sm transition-transform group-hover:scale-105">
                <FileBarChart2 className="w-5 h-5 text-blue-500" />
              </div>
            </div>

            {/* Stat 2: Total Versions */}
            <div className="bg-fuchsia-500/5 border border-fuchsia-500/20 rounded-[16px] p-6 flex justify-between items-center shadow-sm hover:shadow-md transition-shadow group cursor-pointer">
              <div className="flex flex-col gap-1.5">
                <h3 className="text-[12px] font-bold text-fuchsia-500 uppercase tracking-widest">Total Versions</h3>
                <div className="text-[24px] font-black text-foreground leading-none">{metrics.total_versions}</div>
              </div>
              <div className="w-[46px] h-[46px] rounded-[14px] bg-card border border-fuchsia-500/20 flex items-center justify-center shrink-0 shadow-sm transition-transform group-hover:scale-105">
                <Layers className="w-5 h-5 text-fuchsia-500" />
              </div>
            </div>

            {/* Stat 3: Workspaces */}
            <div className="bg-emerald-500/5 border border-emerald-500/20 rounded-[16px] p-6 flex justify-between items-center shadow-sm hover:shadow-md transition-shadow group cursor-pointer">
              <div className="flex flex-col gap-1.5">
                <h3 className="text-[12px] font-bold text-emerald-500 uppercase tracking-widest">Workspaces</h3>
                <div className="text-[24px] font-black text-foreground leading-none">{metrics.total_workspaces}</div>
              </div>
              <div className="w-[46px] h-[46px] rounded-[14px] bg-card border border-emerald-500/20 flex items-center justify-center shrink-0 shadow-sm transition-transform group-hover:scale-105">
                <LayoutGrid className="w-5 h-5 text-emerald-500" />
              </div>
            </div>

          </div>
        </div>

        {/* Main Content (Reports) */}
        <div className="flex flex-col gap-8 w-full">

          {/* Left Column: Reports Grid */}
          <div className="flex flex-col min-w-0">
            {/* Filters Bar */}
            <div className="flex flex-wrap items-center gap-3 mb-6 bg-card p-2 rounded-xl border border-border shadow-sm">
              <div className="relative flex-1 min-w-[200px]">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <input 
                  type="text" 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search reports by name..." 
                  className="w-full pl-9 pr-4 h-10 bg-transparent border-none rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 transition-colors"
                />
              </div>

              <div className="h-6 w-px bg-border mx-1 hidden md:block" />

              <select 
                value={activeWorkspace}
                onChange={(e) => setActiveWorkspace(e.target.value)}
                className="h-10 px-3 pr-8 bg-surface border border-border rounded-lg text-sm font-medium text-foreground cursor-pointer focus:outline-none focus:ring-2 focus:ring-primary/20 appearance-none bg-[url('data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2216%22%20height%3D%2216%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%2364748b%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpolyline%20points%3D%226%209%2012%2015%2018%209%22%3E%3C%2Fpolyline%3E%3C%2Fsvg%3E')] bg-no-repeat bg-[position:right_10px_center] hover:bg-card shadow-sm transition-colors"
              >
                <option value="all" className="bg-card text-foreground">All Workspaces</option>
                {workspaces.map(w => (
                  <option key={w.id} value={w.id} className="bg-card text-foreground">{w.name}</option>
                ))}
              </select>

              <select 
                value={activeSort}
                onChange={(e) => setActiveSort(e.target.value)}
                className="h-10 px-3 pr-8 bg-surface border border-border rounded-lg text-sm font-medium text-foreground cursor-pointer focus:outline-none focus:ring-2 focus:ring-primary/20 appearance-none bg-[url('data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2216%22%20height%3D%2216%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%2364748b%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpolyline%20points%3D%226%209%2012%2015%2018%209%22%3E%3C%2Fpolyline%3E%3C%2Fsvg%3E')] bg-no-repeat bg-[position:right_10px_center] hover:bg-card shadow-sm transition-colors"
              >
                <option value="latest" className="bg-card text-foreground">Sort by Latest</option>
                <option value="oldest" className="bg-card text-foreground">Sort by Oldest</option>
                <option value="a-z" className="bg-card text-foreground">Sort A-Z</option>
              </select>
            </div>

            {/* Reports Area */}
            <div className="flex-1 flex flex-col min-h-[400px]">
              {loading ? (
                <div className="flex-1 flex items-center justify-center">
                  <span className="w-8 h-8 border-4 border-blue-500/30 border-t-blue-600 rounded-full animate-spin" />
                </div>
              ) : reports.length === 0 ? (
                <EmptyState 
                  onGenerate={() => setShowGenerateModal(true)} 
                  isSearch={searchQuery.length > 0 || activeWorkspace !== "all"} 
                />
              ) : view === "grid" ? (
                <motion.div 
                  layout
                  className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-3 gap-4 pb-12"
                >
                  <AnimatePresence>
                    {reports.map((report) => (
                      <ReportCard 
                        key={report.id} 
                        report={report} 
                        viewMode="grid"
                        onPreview={handlePreview}
                        onDownload={handleDownload}
                        onRename={(id, name) => setRenameDialog({ isOpen: true, id, name })}
                        onRegenerate={handleRegenerate}
                        onDelete={(id) => setDeleteDialog({ isOpen: true, id, name: report.title })}
                      />
                    ))}
                  </AnimatePresence>
                </motion.div>
              ) : (
                <motion.div 
                  layout
                  className="bg-card border border-border rounded-[16px] shadow-sm overflow-hidden flex flex-col mb-12"
                >
                  <div 
                    className="grid gap-4 px-6 py-4 border-b border-border bg-surface/30 text-[12px] font-semibold text-muted-foreground uppercase tracking-[0.04em]"
                    style={{ gridTemplateColumns: 'minmax(280px, 1fr) 90px 150px 170px 180px' }}
                  >
                    <div>Report Details</div>
                    <div>Version</div>
                    <div>Workspace</div>
                    <div>Date</div>
                    <div className="text-right pr-2">Actions</div>
                  </div>
                  <div className="flex-1 overflow-y-auto">
                    <AnimatePresence>
                      {reports.map((report) => (
                        <ReportCard 
                          key={report.id} 
                          report={report} 
                          viewMode="table"
                          onPreview={handlePreview}
                          onDownload={handleDownload}
                          onRename={(id, name) => setRenameDialog({ isOpen: true, id, name })}
                          onRegenerate={handleRegenerate}
                          onDelete={(id) => setDeleteDialog({ isOpen: true, id, name: report.title })}
                        />
                      ))}
                    </AnimatePresence>
                  </div>
                </motion.div>
              )}
            </div>
          </div>

        </div>
      </div>

      {showGenerateModal && <GenerateReportModal onClose={() => setShowGenerateModal(false)} onComplete={() => load(searchQuery, activeWorkspace, activeSort)} />}

      <RenameDialog 
        isOpen={renameDialog.isOpen} 
        currentName={renameDialog.name}
        onClose={() => setRenameDialog({ isOpen: false, id: "", name: "" })}
        onConfirm={handleRenameConfirm}
      />

      <DeleteDialog 
        isOpen={deleteDialog.isOpen}
        reportName={deleteDialog.name}
        onClose={() => setDeleteDialog({ isOpen: false, id: "", name: "" })}
        onConfirm={handleDeleteConfirm}
      />
    </div>
  );
}

