// ΓöÇΓöÇ Animated Score Ring ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function SecurityScoreRing({ score }: { score: number }) {
  const [animatedScore, setAnimatedScore] = useState(0);
  const safeScore = Number.isFinite(score) ? Math.max(0, Math.min(100, score)) : 0;
  const radius = 34;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (animatedScore / 100) * circumference;
  const safeOffset = Number.isFinite(offset) ? offset : circumference;

  useEffect(() => {
    const timer = setTimeout(() => setAnimatedScore(safeScore), 100);
    return () => clearTimeout(timer);
  }, [safeScore]);

  const ringColor =
    safeScore >= 90
      ? "#10b981"
      : safeScore >= 70
      ? "#3b82f6"
      : safeScore >= 50
      ? "#f59e0b"
      : "#ef4444";

  return (
    <div className="relative shrink-0" style={{ width: 80, height: 80 }}>
      <svg width="80" height="80" viewBox="0 0 80 80" style={{ transform: "rotate(-90deg)" }}>
        <circle
          cx="40"
          cy="40"
          r={radius}
          stroke="#f1f5f9"
          strokeWidth="7"
          fill="transparent"
        />
        <circle
          cx="40"
          cy="40"
          r={radius}
          stroke={ringColor}
          strokeWidth="7"
          fill="transparent"
          strokeDasharray={circumference}
          strokeDashoffset={safeOffset}
          strokeLinecap="round"
          style={{ transition: "stroke-dashoffset 1.2s ease-out, stroke 0.5s ease" }}
        />
      </svg>
      <div
        className="absolute inset-0 flex items-center justify-center"
        style={{ transform: "rotate(0deg)" }}
      >
        <span style={{ fontSize: 18, fontWeight: 800, color: "#0f172a" }}>
          {animatedScore}
          <span style={{ fontSize: 11 }}>%</span>
        </span>
      </div>
    </div>
  );
}

// ΓöÇΓöÇ Device icon helper ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function DeviceIcon({ device }: { device: string }) {
  if (device === "Mobile") return <Smartphone className="w-4 h-4" />;
  if (device === "Tablet") return <Tablet className="w-4 h-4" />;
  return <Monitor className="w-4 h-4" />;
}

// ΓöÇΓöÇ Time-ago helper ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function timeAgo(iso: string): string {
  if (!iso) return "";
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "Just now";
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  return `${days}d ago`;
}

// ΓöÇΓöÇ Main Page ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export default function SecurityPage() {
  const { user } = useAuth();
  const [data, setData] = useState<SecurityData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [revokingId, setRevokingId] = useState<string | null>(null);
  const [revokingAll, setRevokingAll] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const fetchedRef = useRef(false);

  const fetchSecurity = useCallback(async (showRefresh = false) => {
    try {
      if (showRefresh) setRefreshing(true);
      else setLoading(true);
      setError(null);
      const res = await fetcher<SecurityData>("/settings/security");
      setData(res);
    } catch (e: any) {
      setError(e.message || "Failed to load security information.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    if (user && !fetchedRef.current) {
      fetchedRef.current = true;
      fetchSecurity();
    }
  }, [user, fetchSecurity]);

  const handleRevoke = useCallback(
    async (sessionId: string) => {
      setRevokingId(sessionId);
      try {
        await fetcher(`/settings/security/sessions/${sessionId}`, { method: "DELETE" });
        setData((prev) =>
          prev
            ? { ...prev, sessions: prev.sessions.filter((s) => s.id !== sessionId) }
            : prev
        );
      } catch (e: any) {
        setError(e.message || "Failed to revoke session.");
      } finally {
        setRevokingId(null);
      }
    },
    []
  );

  const handleRevokeAll = useCallback(async () => {
    setRevokingAll(true);
    try {
      await fetcher("/settings/security/sessions/revoke-others", { method: "POST" });
      setData((prev) =>
        prev
          ? { ...prev, sessions: prev.sessions.filter((s) => s.is_current) }
          : prev
      );
    } catch (e: any) {
      setError(e.message || "Failed to revoke other sessions.");
    } finally {
      setRevokingAll(false);
    }
  }, []);

  // ΓöÇΓöÇ Skeleton ΓöÇΓöÇ
  if (loading) {
    return (
      <div className="space-y-5 pb-8">
        <div className="border-b border-border pb-3">
          <div className="h-5 w-24 bg-muted rounded animate-pulse" />
          <div className="h-3 w-64 bg-surface rounded animate-pulse mt-2" />
        </div>
        {[1, 2, 3].map((i) => (
          <div key={i} className="bg-card border border-border rounded-xl p-5">
            <div className="h-4 w-32 bg-muted rounded animate-pulse mb-3" />
            <div className="h-16 bg-surface rounded animate-pulse" />
          </div>
        ))}
      </div>
    );
  }

  // ΓöÇΓöÇ Error ΓöÇΓöÇ
  if (error && !data) {
    return (
      <div className="space-y-5 pb-8">
        <div className="border-b border-border pb-3">
          <h2 className="text-xl font-extrabold text-foreground">Security</h2>
        </div>
        <div className="bg-destructive/10 border border-destructive/50 rounded-xl p-5 flex items-start gap-3">
          <AlertCircle className="w-5 h-5 text-destructive shrink-0 mt-0.5" />
          <div>
            <h4 className="text-sm font-bold text-destructive">Security information unavailable</h4>
            <p className="text-xs text-destructive mt-1">{error}</p>
            <button
              onClick={() => { fetchedRef.current = false; fetchSecurity(); }}
              className="mt-3 text-xs font-bold text-destructive border border-destructive/50 px-3 py-1.5 rounded-lg hover:bg-destructive/20 transition-colors"
            >
              Retry
            </button>
          </div>
        </div>
      </div>
    );
  }

  const sessions = data?.sessions || [];
  const currentSession = sessions.find((s) => s.is_current);
  const otherSessions = sessions.filter((s) => !s.is_current);

  return (
    <div className="space-y-5 pb-8 relative">
      {/* Page header */}
      <motion.div
        initial={{ opacity: 0, y: 6 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
        className="flex items-center justify-between border-b border-border pb-3"
      >
        <div>
          <h2 className="text-xl font-extrabold text-foreground">Security</h2>
          <p className="text-muted-foreground text-xs font-medium mt-0.5">
            Manage your active sessions and connected accounts.
          </p>
        </div>
        <button
          onClick={() => fetchSecurity(true)}
          disabled={refreshing}
          className="flex items-center gap-1.5 text-xs font-bold text-muted-foreground hover:text-primary px-2.5 py-1.5 rounded-lg border border-border hover:border-primary/50 transition-colors disabled:opacity-50"
        >
          <RefreshCw className={`w-3 h-3 ${refreshing ? "animate-spin" : ""}`} />
          Refresh
        </button>
      </motion.div>

      {/* Error banner (non-fatal) */}
      <AnimatePresence>
        {error && data && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="bg-destructive/10 border border-destructive/50 rounded-xl px-4 py-3 flex items-center gap-2 text-xs text-destructive"
          >
            <AlertCircle className="w-3.5 h-3.5 shrink-0" />
            {error}
          </motion.div>
        )}
      </AnimatePresence>

      {/* ΓöÇΓöÇΓöÇ Security Status Card ΓöÇΓöÇΓöÇ */}
      <SettingsSection
        title="Security Status"
        description="Your account's overall security health."
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "100px 1fr",
            gap: "20px",
            alignItems: "start",
          }}
        >
          {/* Left: Ring */}
          <div style={{ display: "flex", justifyContent: "center", paddingTop: 4 }}>
            <SecurityScoreRing score={data?.score || 0} />
          </div>

          {/* Right: Content */}
          <div style={{ minWidth: 0 }}>
            <h4
              style={{
                fontSize: 15,
                fontWeight: 800,
