              {data?.label === "Excellent"
                ? "Looking Good!"
                : data?.label === "Good"
                ? "Doing Well"
                : data?.label === "Needs Attention"
                ? "Needs Attention"
                : "Action Required"}
            </h4>
            <p
              style={{
                fontSize: 13,
                color: "#64748b",
                lineHeight: 1.5,
                marginBottom: 12,
                maxWidth: 500,
