"use client";
import { uploadMultipart } from "@/lib/api";

import { useState, useEffect, useRef, useCallback } from "react";
import { useParams, useRouter, usePathname } from "next/navigation";
import Link from "next/link";
import { motion } from "framer-motion";
import {
  ChevronRight,
  Upload,
  FileBarChart2,
  MessageSquare,
  BarChart2,
  GitCompareArrows,
  ShieldAlert,
  Bot,
  FileText,
  ChevronLeft,
  MoreVertical,
  Activity,
  RotateCcw,
  Loader2,
  Check,
  X,
  FileStack,
  TrendingUp,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { timeAgo } from "@/lib/utils";
import { fetcher, API_BASE_URL } from "@/lib/api";
import { useAuth } from "@/components/providers/AuthProvider";


interface Workspace {
  id: string;
  name: string;
  description: string;
  docs: number;
  chats: number;
  reports: number;
  owner_name: string;
  updatedAt: string;
}


// ΓöÇΓöÇ Agent Sidebar Components ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const AGENT_ICONS: Record<string, any> = {
  "Document Agent": FileStack,
  "Extraction Agent": TrendingUp,
  "Red Flag Agent": ShieldAlert,
  "Comparison Agent": GitCompareArrows,
  "Research Agent": MessageSquare,
  "Report Agent": FileBarChart2,
};

const AGENT_COLORS: Record<string, string> = {
  "Document Agent": "bg-primary/20 text-primary",
  "Extraction Agent": "bg-teal-100 text-success",
  "Red Flag Agent": "bg-orange-100 text-orange-600",
  "Comparison Agent": "bg-violet-100 text-violet-600",
  "Research Agent": "bg-sky-100 text-sky-600",
  "Report Agent": "bg-destructive/20 text-destructive",
};

function StatusBadge({ status }: { status: string }) {
  if (status === "Complete")
    return (
      <span className="inline-flex items-center gap-1 text-xs font-semibold text-success bg-success/10 px-2 py-0.5 rounded-full">
        <Check className="w-3 h-3" /> Complete
      </span>
    );
  if (status === "Running")
    return (
      <span className="inline-flex items-center gap-1 text-xs font-semibold text-primary bg-primary/10 px-2 py-0.5 rounded-full">
        <Loader2 className="w-3 h-3 animate-spin" /> Running
      </span>
    );
  if (status === "Failed")
    return (
      <span className="inline-flex items-center gap-1 text-xs font-semibold text-destructive bg-destructive/10 px-2 py-0.5 rounded-full">
        <X className="w-3 h-3" /> Failed
      </span>
    );
  if (status === "Blocked")
    return (
      <span className="inline-flex items-center gap-1 text-xs font-semibold text-amber-700 bg-amber-50 px-2 py-0.5 rounded-full">
        <ShieldAlert className="w-3 h-3" /> Blocked
      </span>
    );
  return (
    <span className="inline-flex items-center gap-1 text-xs font-semibold text-muted-foreground bg-surface px-2 py-0.5 rounded-full">
      Idle
    </span>
  );
}

import { useAgentOrchestration } from "@/hooks/useAgentOrchestration";

function AgentSidebar({
  workspaceId,
  collapsed,
  onToggle,
}: {
  workspaceId: string;
  collapsed: boolean;
  onToggle: () => void;
}) {
  const { agents, loading, retryAgent } = useAgentOrchestration(workspaceId);

  const handleRetry = async (agentId: number) => {
    try {
      await retryAgent(agentId);
    } catch (e: any) {
      console.error("Retry failed:", e);
    }
  };

  if (collapsed) {
    return (
      <div className="w-10 border-l border-border bg-background flex flex-col items-center pt-4 gap-4 shrink-0">
        <button
          onClick={onToggle}
          className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-surface transition-colors"
          title="Expand Agent Status"
        >
          <ChevronLeft className="w-4 h-4" />
        </button>
        {agents.slice(0, 6).map((agent) => {
          const Icon = AGENT_ICONS[agent.name] || Bot;
          const colorClass = AGENT_COLORS[agent.name] || "bg-surface text-muted-foreground";
          return (
            <div key={agent.id} className={cn("w-8 h-8 rounded-lg flex items-center justify-center shrink-0 relative", colorClass)}>
              <Icon className="w-4 h-4" />
              {agent.status === "Running" && (
                <span className="absolute -top-0.5 -right-0.5 w-2 h-2 bg-primary rounded-full animate-pulse" />
              )}
              {agent.status === "Failed" && (
                <span className="absolute -top-0.5 -right-0.5 w-2 h-2 bg-destructive rounded-full" />
              )}
            </div>
          );
        })}
      </div>
    );
  }

  return (
    <div className="w-72 border-l border-border bg-background flex flex-col shrink-0 overflow-hidden">
      <div className="flex items-center justify-between px-4 py-3 border-b border-border-subtle">
        <span className="text-sm font-bold text-foreground">Agent Status</span>
        <button
          onClick={onToggle}
          className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-surface transition-colors"
          title="Collapse"
        >
          <ChevronRight className="w-4 h-4" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto divide-y divide-border">
        {loading
          ? Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className="px-4 py-3 flex items-center gap-3 animate-pulse">
                <div className="w-9 h-9 rounded-xl bg-surface shrink-0" />
                <div className="flex-1 space-y-2">
                  <div className="h-3 bg-surface rounded w-3/4" />
                  <div className="h-2 bg-surface rounded w-1/2" />
                </div>
              </div>
            ))
          : agents.map((agent) => {
              const Icon = AGENT_ICONS[agent.name] || Bot;
              const isRunning = agent.status === "Running";
              const isComplete = agent.status === "Complete";
              const isFailed = agent.status === "Failed";
              const isBlocked = agent.status === "Blocked";
              const colorClass = AGENT_COLORS[agent.name] || "bg-surface text-muted-foreground";
              const detailLines = agent.details.split("\n");
              return (
                <div 
                  key={agent.id} 
                  className={cn(
                    "px-4 py-3 flex items-start gap-3 transition-colors relative border-l-2",
                    isRunning ? "bg-primary/10/30 border-primary" :
                    isComplete ? "hover:bg-surface border-transparent" :
                    isFailed ? "bg-destructive/10/30 border-destructive/50" :
                    isBlocked ? "bg-amber-50/30 border-amber-500" :
                    "hover:bg-surface border-transparent"
                  )}
                >
                  <div className={cn("w-9 h-9 rounded-xl flex items-center justify-center shrink-0 mt-0.5 relative", colorClass)}>
                    <Icon className="w-4 h-4" />
                    {isComplete && <span className="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-success border-2 border-white rounded-full" />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-2 mb-1">
                      <span className="text-xs font-semibold text-foreground truncate">
                        {agent.id} {agent.name}
                      </span>
                      <button className="p-0.5 text-muted-foreground hover:text-muted-foreground transition-colors shrink-0">
                        <MoreVertical className="w-3.5 h-3.5" />
                      </button>
                    </div>
                    <StatusBadge status={agent.status} />
                    <p className="text-[11px] text-muted-foreground mt-1.5 leading-relaxed whitespace-pre-line">
                      {detailLines[0]}
                    </p>
                    {detailLines[1] && (
                      <p className="text-[11px] text-muted-foreground">{detailLines[1]}</p>
                    )}
                    {isFailed && (
                      <button
                        onClick={() => handleRetry(agent.id)}
                        className="mt-1.5 flex items-center gap-1 text-[11px] font-medium text-destructive hover:text-destructive transition-colors"
                      >
                        <RotateCcw className="w-3 h-3" /> Retry
                      </button>
                    )}
                  </div>
                  {isRunning && (
                    <div className="absolute bottom-0 left-0 right-0 h-[2px] bg-primary/20 overflow-hidden">
                      <div className="h-full bg-primary rounded-r-full w-full origin-left animate-pulse" />
                    </div>
                  )}
                </div>
              );
            })}
      </div>

      <div className="border-t border-border-subtle px-4 py-2">
        <Link href={`/workspace/${workspaceId}/agents`} className="w-full flex items-center justify-center gap-2 text-xs font-medium text-primary hover:text-primary-hover py-1.5 transition-colors">
          <Activity className="w-3.5 h-3.5" />
          View all activity
        </Link>
      </div>
    </div>
  );
}

// ΓöÇΓöÇ Layout ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

type Tab = "Chat" | "Documents" | "Metrics" | "Comparison" | "Red Flags" | "Agent Activity" | "Reports";

const TABS: { id: Tab, label: string, path: string, icon: any }[] = [
  { id: "Chat", label: "Chat", path: "", icon: MessageSquare },
  { id: "Documents", label: "Documents", path: "/documents", icon: FileText },
  { id: "Metrics", label: "Metrics", path: "/metrics", icon: BarChart2 },
  { id: "Comparison", label: "Comparison", path: "/compare", icon: GitCompareArrows },
  { id: "Red Flags", label: "Red Flags", path: "/red-flags", icon: ShieldAlert },
  { id: "Agent Activity", label: "Agent Activity", path: "/agents", icon: Activity },
  { id: "Reports", label: "Reports", path: "/reports", icon: FileBarChart2 },
];

export default function WorkspaceLayout({ children }: { children: React.ReactNode }) {
  const params = useParams();
  const router = useRouter();
  const pathname = usePathname();
  const workspaceId = params.id as string;

  const { user, loading: authLoading } = useAuth();
  const [ws, setWs] = useState<Workspace | null>(null);
  const [firstDocName, setFirstDocName] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [uploading, setUploading] = useState(false);

  const uploadRef = useRef<HTMLInputElement>(null);

  const loadWorkspace = useCallback(async () => {
    if (authLoading || !user) return;
    try {
      const data = await fetcher<Workspace>(`/workspaces/${workspaceId}`);
      setWs(data);
      
      try {
        const docsData = await fetcher<{documents: any[]}>(`/workspaces/${workspaceId}/documents`);
        if (docsData && docsData.documents && docsData.documents.length > 0) {
          setFirstDocName(docsData.documents[0].name);
        }
      } catch (e) {
        console.error("Failed to fetch documents for breadcrumb", e);
      }
    } catch {
      router.push("/workspace");
    } finally {
      setLoading(false);
    }
  }, [workspaceId, router, authLoading, user]);

  useEffect(() => {
    if (!authLoading && user) {
      loadWorkspace();
    } else if (!authLoading && !user) {
      router.push("/login");
    }
  }, [loadWorkspace, authLoading, user, router]);

  const handleHeaderUpload = async (files: File[]) => {
    const pdfs = files.filter((f) => f.type === "application/pdf");
    if (!pdfs.length) return;
    setUploading(true);
    const formData = new FormData();
    pdfs.forEach((f) => formData.append("files", f));
    try {
      await uploadMultipart(`/workspaces/${workspaceId}/documents`, formData);
      await loadWorkspace();
      router.push(`/workspace/${workspaceId}/documents`);
    } catch (e) {
      console.error("Upload failed", e);
    } finally {
      setUploading(false);
    }
  };

  const handleGenerateReport = () => {
    router.push(`/workspace/${workspaceId}/reports/generate`);
  };

  // Determine current active tab based on pathname
  let activeTabId: Tab = "Chat";
  for (const tab of TABS) {
    if (tab.path && (pathname.endsWith(tab.path) || pathname.includes(`${tab.path}/`))) {
      activeTabId = tab.id;
    }
  }

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center py-32">
        <Loader2 className="w-8 h-8 text-primary animate-spin" />
      </div>
    );
  }

  if (!ws) return null;

  return (
    <div className="flex flex-col flex-1 min-w-0 min-h-0 h-[calc(100vh-56px)] overflow-hidden bg-background">
      {/* ΓöÇΓöÇ Header ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="bg-card border-b border-border px-6 py-4 shrink-0">
        {/* Breadcrumb */}
        <div className="flex items-center gap-1.5 text-xs text-muted-foreground mb-2 w-full">
          <Link href="/workspace" className="hover:text-primary transition-colors flex items-center gap-1 shrink-0">
            <ChevronLeft className="w-3.5 h-3.5" /> Workspaces
          </Link>
          <ChevronRight className="w-3 h-3 shrink-0" />
          <Link href={`/workspace/${workspaceId}`} className="hover:text-primary transition-colors min-w-0 shrink-0">
            <span className="truncate block max-w-sm" title={firstDocName || ws.name}>{firstDocName || ws.name}</span>
          </Link>
          <ChevronRight className="w-3 h-3 shrink-0" />
          <span className="text-muted-foreground font-medium shrink-0">{activeTabId}</span>
        </div>

        {/* Title row */}
        <div className="flex items-start justify-between gap-4">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-3 flex-wrap">
              <h1 className="text-xl font-bold text-foreground truncate">{ws.name}</h1>
              <span className="inline-flex items-center gap-1 text-xs font-semibold text-success bg-success/10 border border-success/50 px-2.5 py-0.5 rounded-full">
                <span className="w-1.5 h-1.5 bg-success rounded-full animate-pulse" />
                Active
              </span>
            </div>
            <p className="text-xs text-muted-foreground mt-1">
              {timeAgo(ws.updatedAt)} &bull; {ws.docs} Document{ws.docs !== 1 ? "s" : ""} &bull; {ws.chats} Chat{ws.chats !== 1 ? "s" : ""} &bull; {ws.reports} Report{ws.reports !== 1 ? "s" : ""}
            </p>
          </div>

          <div className="flex items-center gap-3 shrink-0">
            <button
              onClick={() => uploadRef.current?.click()}
              disabled={uploading}
              className="flex items-center gap-2 px-4 py-2 rounded-lg border border-border bg-card text-sm font-medium text-foreground hover:bg-surface disabled:opacity-50 transition-colors shadow-sm"
            >
              {uploading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
              Upload
            </button>
            <input
              ref={uploadRef}
              type="file"
              accept=".pdf"
              multiple
              className="hidden"
              onChange={(e) => {
                handleHeaderUpload(Array.from(e.target.files || []));
                e.target.value = "";
              }}
            />
            <button
              suppressHydrationWarning
              onClick={handleGenerateReport}
              className="hidden md:flex items-center gap-2 h-9 px-4 rounded-lg bg-primary/10 border border-primary/30 text-primary hover:bg-primary/20 hover:border-primary/50 transition-colors shadow-sm text-sm font-medium backdrop-blur-sm"
            >
              <FileBarChart2 className="w-4 h-4" />
              Generate Report
            </button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex items-center gap-1 mt-5 -mb-4 overflow-x-auto scrollbar-none relative px-2">
          {TABS.map((tab) => {
            const Icon = tab.icon;
            const active = activeTabId === tab.id;
            return (
              <Link
                key={tab.id}
                href={`/workspace/${workspaceId}${tab.path}`}
                className={cn(
                  "relative flex items-center gap-2 px-4 py-2.5 text-[13px] font-semibold whitespace-nowrap transition-colors z-10",
                  active
                    ? "text-primary"
                    : "text-muted-foreground hover:text-foreground"
                )}
              >
                {active && (
                  <motion.div
                    layoutId="workspaceActiveTab"
                    className="absolute inset-0 bg-primary/10/80 border-b-2 border-primary rounded-t-lg -z-10"
                    transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
                  />
                )}
                {!active && (
                  <div className="absolute inset-0 bg-surface/50 opacity-0 hover:opacity-100 rounded-t-lg -z-10 transition-opacity" />
                )}
                <Icon className={cn("w-[15px] h-[15px] shrink-0 transition-colors", active ? "text-primary" : "text-muted-foreground")} />
                {tab.label}
              </Link>
            );
          })}
        </div>
      </div>

      {/* ΓöÇΓöÇ Body ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="flex flex-1 min-w-0 min-h-0 overflow-hidden">
        {/* Main panel */}
        <div className="flex-1 flex flex-col min-w-0 min-h-0 overflow-hidden">
          {children}
        </div>

        {/* Agent Sidebar */}
        <AgentSidebar
          workspaceId={workspaceId}
          collapsed={sidebarCollapsed}
          onToggle={() => setSidebarCollapsed((v) => !v)}
        />
      </div>


    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useParams, useRouter, useSearchParams } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import {
  ArrowUpRight,
  ArrowDownRight,
  Globe,
  Loader2,
  BadgeCheck,
  TrendingUp,
  IndianRupee,
  Percent,
  Wallet,
  HandCoins,
  Handshake,
  Info,
  BarChart3,
  ChevronDown,
  Check,
  FileText,
  Building2,
  Calendar,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { fetcher } from "@/lib/api";
import { AnimatedNumber } from "@/components/ui/AnimatedNumber";
import { FinancialHeroParticles } from "@/components/ui/FinancialHeroParticles";
import {
  DonutChart,
  QuarterlyTrendChart,
  GeographySplitChart,
  KeyMetricsBarChart,
  CircularGauge,
  KeyMetricsRadarChart
} from "@/components/ui/PremiumCharts";

/* ΓöÇΓöÇ types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
interface Metric {
  label: string;
  value: string;
  change: string;
  trend: "up" | "down";
  period: string;
}
interface Segment {
  segment: string;
  value: number | string;
  revenue: string;
}
interface Quarter {
  quarter: string;
  revenue: number | string;
  profit: number | string;
  margin: number | string;
}
interface Geo {
  region: string;
  percentage: number | string;
}
interface MetricsData {
  status?: string;
  period?: string;
  company?: string;
  key_metrics?: Metric[];
  revenue_breakdown?: Segment[];
  quarterly_trend?: Quarter[];
  geography_split?: Geo[];
}

/* ΓöÇΓöÇ colour palette for segments ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
const SEG_COLORS = [
  "#3B82F6",
  "#8B5CF6",
  "#10B981",
  "#F59E0B",
  "#EF4444",
  "#06B6D4",
  "#EC4899",
];

const GEO_COLORS = ["#3B82F6", "#8B5CF6", "#10B981", "#F59E0B"];

/* small icon map matching the screenshot cards */
const METRIC_ICONS: Record<string, any> = {
  Revenue: IndianRupee,
  "Net Profit": Wallet,
  "EBIT Margin": Percent,
  EPS: TrendingUp,
  "Free Cash Flow": HandCoins,
  "Deal Wins": Handshake,
};

const parseNumber = (val: string | number | undefined | null): number => {
  if (val === undefined || val === null) return NaN;
  if (typeof val === 'number') return val;
  const match = val.replace(/,/g, '').match(/-?\d+(\.\d+)?/);
  return match ? parseFloat(match[0]) : NaN;
};



/* ΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
interface Document {
  id: string;
  name: string;
  status: "pending" | "processing" | "ready" | "failed";
  uploaded_at: string;
}

export default function MetricsPage() {
  const params = useParams();
  const workspaceId = params.id as string;
  const router = useRouter();
  const searchParams = useSearchParams();
  
  const selectedDocumentId = searchParams.get("documentId");

  const [data, setData] = useState<MetricsData & { filename?: string } | null>(null);
  const [loading, setLoading] = useState(true);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [docsLoading, setDocsLoading] = useState(true);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Close dropdown on outside click
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setDropdownOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Fetch available documents
  useEffect(() => {
    fetcher<{ documents: Document[] }>(`/workspaces/${workspaceId}/documents`)
      .then((res) => setDocuments(res.documents || []))
      .catch(console.error)
      .finally(() => setDocsLoading(false));
  }, [workspaceId]);

  // Fetch metrics when selectedDocumentId changes
  useEffect(() => {
    setLoading(true);
    const url = selectedDocumentId 
      ? `/workspaces/${workspaceId}/metrics?document_id=${selectedDocumentId}`
      : `/workspaces/${workspaceId}/metrics`;
      
    fetcher<MetricsData & { filename?: string }>(url)
      .then(setData)
      .catch(console.error)
      .finally(() => setLoading(false));
  }, [workspaceId, selectedDocumentId]);

  const handleSelectDocument = (docId: string) => {
    setDropdownOpen(false);
    const params = new URLSearchParams(searchParams.toString());
    params.set("documentId", docId);
    router.push(`?${params.toString()}`);
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "ready":
        return <span className="bg-emerald-100 text-success px-2 py-0.5 rounded text-[10px] font-bold uppercase">Ready</span>;
      case "processing":
        return <span className="bg-primary/20 text-primary px-2 py-0.5 rounded text-[10px] font-bold uppercase flex items-center gap-1"><Loader2 className="w-3 h-3 animate-spin"/> Processing</span>;
      case "failed":
        return <span className="bg-destructive/20 text-destructive px-2 py-0.5 rounded text-[10px] font-bold uppercase">Failed</span>;
      default:
        return <span className="bg-surface text-foreground px-2 py-0.5 rounded text-[10px] font-bold uppercase">{status}</span>;
    }
  };

  if (loading || docsLoading)
    return (
      <div className="flex-1 flex items-center justify-center py-24 text-muted-foreground">
        <Loader2 className="w-6 h-6 animate-spin mr-2" />
        Loading metricsΓÇª
      </div>
    );

  // Identify currently displayed document name
  // Either from selected document in list, or from backend's 'filename', or fallback to 'Company'
  const selectedDoc = (documents || []).find(d => d.id === selectedDocumentId);
  const displayTitle = selectedDoc?.name || data?.filename || data?.company || "Financial Document";
  const displayCompany = data?.company || "Company";

  // Check if we should render empty states
  let emptyState = null;
  if (data?.status === "running") {
    emptyState = (
      <div className="flex-1 flex flex-col items-center justify-center py-24 text-center px-6">
        <Loader2 className="w-10 h-10 animate-spin text-primary mb-6" />
        <h2 className="text-xl font-bold text-foreground mb-2">Metrics extraction is in progress</h2>
        <p className="text-sm text-muted-foreground max-w-md">
          The Extraction Agent is currently analyzing your document. This may take a moment.
        </p>
      </div>
    );
  } else if (data?.status === "failed") {
    emptyState = (
      <div className="flex-1 flex flex-col items-center justify-center py-24 text-center px-6">
        <div className="w-20 h-20 rounded-2xl bg-destructive/10 flex items-center justify-center mb-6">
          <Info className="w-10 h-10 text-destructive" />
        </div>
        <h2 className="text-xl font-bold text-foreground mb-2">Extraction Failed</h2>
        <p className="text-sm text-muted-foreground max-w-md">
          Metrics could not be extracted because the Extraction Agent failed. You can retry it from the Agent Status sidebar.
        </p>
      </div>
    );
  } else if (!data || data.status !== "complete" || !data.key_metrics || data.key_metrics.length === 0 || data.key_metrics[0].label === "Data") {
    emptyState = (
      <div className="flex-1 flex flex-col items-center justify-center py-24 text-center px-6">
        <div className="w-20 h-20 rounded-2xl bg-primary/10 flex items-center justify-center mb-6">
          <TrendingUp className="w-10 h-10 text-primary" />
        </div>
        <h2 className="text-xl font-bold text-foreground mb-2">No supported financial metrics were found</h2>
        <p className="text-sm text-muted-foreground max-w-md">
          {selectedDocumentId 
            ? "This document does not contain supported metrics, or extraction has not been completed."
            : "Upload supported financial documents (such as 10-K, 10-Q, or Earnings Reports) for our AI agents to automatically extract key metrics."}
        </p>
      </div>
    );
  }

