}

"use client";

import { useState, useEffect, useRef } from "react";
import { useParams } from "next/navigation";
import { 
  Bot, MessageSquare, Paperclip, Send, Layers, ShieldAlert, Loader2, FileText, 
  TrendingUp, GitCompareArrows, FileBarChart2, X, Search, Plus, Pencil, Trash2, 
  Check, Edit, PanelLeftClose, PanelLeftOpen, Book, Folder, Clock, Blocks, Code, MoreHorizontal, 
  Pin, Store, ChevronDown, Mic, ArrowUp, Copy, RotateCcw, CheckCheck
} from "lucide-react";
import { cn } from "@/lib/utils";
import { fetcher, API_BASE_URL, uploadMultipart } from "@/lib/api";
import { useAuth } from "@/components/providers/AuthProvider";

interface ChatMsg {
  role: "user" | "assistant" | "model";
  content: string;
  citations?: { doc: string; page: number; field?: string }[];
  attachments?: { name: string; type: string }[];
}

interface ChatSession {
  _id: string;
  title: string;
  message_count: number;
  updated_at: string;
  is_pinned?: boolean;
}

export default function ChatPage() {
  const params = useParams();
  const workspaceId = params.id as string;
  const { user: firebaseUser, dbUser } = useAuth();
  const userName = dbUser?.name || firebaseUser?.displayName || "Vivek Chaurasiya";
  const firstName = userName.split(" ")[0] || "there";

  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [isHistoryOpen, setIsHistoryOpen] = useState(true);

  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState("");

  const [messages, setMessages] = useState<ChatMsg[]>([]);
  const [input, setInput] = useState("");
  const [attachedFiles, setAttachedFiles] = useState<File[]>([]);
  const [sending, setSending] = useState(false);
  const [loadingMessages, setLoadingMessages] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  const [editingMessageIndex, setEditingMessageIndex] = useState<number | null>(null);
  const [editMessageText, setEditMessageText] = useState("");

  const bottomRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        searchInputRef.current?.focus();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const handleCopy = (text: string, index: number) => {
    navigator.clipboard.writeText(text);
    setCopiedIndex(index);
    setTimeout(() => setCopiedIndex(null), 2000);
  };

  const handleRetry = (index: number) => {
    let lastUserMsg = "";
    for (let i = index; i >= 0; i--) {
      if (messages[i].role === "user") {
        lastUserMsg = messages[i].content;
        break;
      }
    }
    if (lastUserMsg && !sending) {
      sendMessage(lastUserMsg);
    }
  };

  const handleEditMessage = (index: number) => {
    setEditingMessageIndex(index);
    setEditMessageText(messages[index].content);
  };

  const submitEditMessage = (index: number) => {
    if (!editMessageText.trim() || sending) return;

    // To cleanly retry from this point, we truncate the history at this message
    const newMessages = messages.slice(0, index);
    setMessages(newMessages);
    setEditingMessageIndex(null);
    sendMessage(editMessageText.trim());
  };

  const cancelEditMessage = () => {
    setEditingMessageIndex(null);
  };

  const loadSessions = () => {
    fetcher<{ sessions: ChatSession[] }>(`/workspaces/${workspaceId}/chat_sessions`)
      .then((data) => setSessions(data.sessions))
      .catch(console.error);
  };

  const handleVoiceInput = () => {
    // @ts-ignore
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice input is not supported in this browser. Please use Chrome or Edge.");
      return;
    }

    if (isRecording) {
      return; // It handles its own stop
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = true;

    recognition.onstart = () => setIsRecording(true);
    recognition.onresult = (event: any) => {
      const transcript = Array.from(event.results)
        .map((result: any) => result[0])
        .map(result => result.transcript)
        .join("");

      setInput(transcript);
      if (textareaRef.current) {
        textareaRef.current.style.height = "auto";
        textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 200) + "px";
      }
    };
    recognition.onerror = (e: any) => {
      console.error(e);
      setIsRecording(false);
    };
    recognition.onend = () => setIsRecording(false);

    recognition.start();
  };

  const handleDeleteSession = async (sessionId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm("Are you sure you want to delete this conversation?")) return;

    try {
      await fetcher(`/workspaces/${workspaceId}/chat_sessions/${sessionId}`, { method: "DELETE" });
      setSessions(prev => prev.filter(s => s._id !== sessionId));
      if (activeSessionId === sessionId) setActiveSessionId(null);
    } catch (error) {
      console.error("Failed to delete session", error);
    }
  };

  const handleTogglePin = async (sessionId: string, currentPinned: boolean, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      await fetcher(`/workspaces/${workspaceId}/chat_sessions/${sessionId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ is_pinned: !currentPinned })
      });
      setSessions(prev => prev.map(s => s._id === sessionId ? { ...s, is_pinned: !currentPinned } : s));
    } catch (error) {
      console.error("Failed to toggle pin", error);
    }
  };

  const handleRenameSession = async (sessionId: string) => {
    if (!editTitle.trim()) {
      setEditingSessionId(null);
      return;
    }

    try {
      await fetcher(`/workspaces/${workspaceId}/chat_sessions/${sessionId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title: editTitle.trim() })
      });
      setSessions(prev => prev.map(s => s._id === sessionId ? { ...s, title: editTitle.trim() } : s));
      setEditingSessionId(null);
    } catch (error) {
      console.error("Failed to rename session", error);
    }
  };

  useEffect(() => {
    loadSessions();
  }, [workspaceId]);

  useEffect(() => {
    if (activeSessionId) {
      setLoadingMessages(true);
      fetcher<{ messages: ChatMsg[] }>(`/workspaces/${workspaceId}/chat_sessions/${activeSessionId}`)
        .then((data) => setMessages(data.messages))
        .catch(console.error)
        .finally(() => setLoadingMessages(false));
    } else {
      setMessages([]);
    }
  }, [activeSessionId, workspaceId]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, sending]);

  const sendMessage = async (text: string) => {
    if ((!text.trim() && attachedFiles.length === 0) || sending) return;

    const attachments = attachedFiles.map(f => ({ name: f.name, type: f.type }));
    const userMsg: ChatMsg = { role: "user", content: text.trim(), attachments: attachments.length > 0 ? attachments : undefined };

    setMessages((prev) => [...prev, userMsg]);
    setInput("");
    const filesToSend = [...attachedFiles];
    setAttachedFiles([]);
    setSending(true);

    try {
      if (filesToSend.length > 0) {
        // Only upload PDFs to the document library
        const pdfFiles = filesToSend.filter(f => f.type === "application/pdf" || f.name.toLowerCase().endsWith(".pdf"));
        if (pdfFiles.length > 0) {
          const docFormData = new FormData();
          pdfFiles.forEach(file => {
            docFormData.append("files", file);
          });
          try {
            await uploadMultipart(`/workspaces/${workspaceId}/documents`, docFormData);
          } catch (e) {
            console.error("Failed to upload PDFs to document library", e);
          }
        }
      }

      const finalMessage = text.trim() || (filesToSend.length > 0 ? "I have just uploaded new files. Please acknowledge them." : "");

      const formData = new FormData();
      formData.append("message", finalMessage);
      if (activeSessionId) {
        formData.append("session_id", activeSessionId);
      }

      // Append all files to the chat endpoint (for image processing and acknowledgment)
      filesToSend.forEach(file => {
        formData.append("files", file);
      });

      const data = await uploadMultipart<{ reply: string; citations: { doc: string; page: number; field?: string }[]; session_id?: string }>(`/workspaces/${workspaceId}/chat`, formData);

      setMessages((prev) => [
        ...prev,
        { role: "assistant", content: data.reply, citations: data.citations },
      ]);

      if (data.session_id && !activeSessionId) {
        setActiveSessionId(data.session_id);
      }
      loadSessions();
    } catch (error) {
      console.error(error);
      setMessages((prev) => [
        ...prev,
        { role: "assistant", content: "Sorry, there was an error communicating with the Research Agent. Please try again." },
      ]);
    } finally {
      setSending(false);
      textareaRef.current?.focus();
    }
  };

  const filteredSessions = sessions.filter(s => s.title.toLowerCase().includes(searchQuery.toLowerCase()));
  const pinnedSessions = filteredSessions.filter(s => s.is_pinned);
  const recentSessions = filteredSessions.filter(s => !s.is_pinned);

  // Render a chat session item (used in Recents)
  const renderSessionItem = (s: ChatSession) => {
    return (
      <div
        key={s._id}
        onClick={() => {
          setActiveSessionId(s._id);
          if(window.innerWidth < 1024) setIsHistoryOpen(false);
        }}
        className={cn(
          "w-full flex items-center justify-between gap-2 px-2.5 py-2 rounded-lg text-left transition-colors group cursor-pointer text-sm",
          activeSessionId === s._id
            ? "bg-muted text-foreground"
            : "hover:bg-muted/50 text-foreground"
        )}
      >
        <div className="flex-1 min-w-0 flex items-center gap-2">
          {editingSessionId === s._id ? (
            <div className="flex items-center gap-1 w-full" onClick={e => e.stopPropagation()}>
              <input
                type="text"
                autoFocus
                value={editTitle}
                onChange={e => setEditTitle(e.target.value)}
                onKeyDown={e => {
                  if (e.key === "Enter") handleRenameSession(s._id);
                  if (e.key === "Escape") setEditingSessionId(null);
                }}
                className="flex-1 bg-card border border-border rounded px-1.5 py-0.5 text-xs text-foreground outline-none focus:ring-1 focus:ring-blue-500 w-full"
              />
              <button onClick={() => handleRenameSession(s._id)} className="p-1 text-green-600 hover:bg-green-50 rounded shrink-0">
                <Check className="w-3 h-3" />
              </button>
              <button onClick={() => setEditingSessionId(null)} className="p-1 text-muted-foreground hover:bg-surface rounded shrink-0">
                <X className="w-3 h-3" />
              </button>
            </div>
          ) : (
            <p className="font-medium truncate">{s.title || "New Conversation"}</p>
          )}
        </div>

        {/* Action icons shown on hover */}
        {editingSessionId !== s._id && (
          <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
            <button 
              onClick={(e) => {
                e.stopPropagation();
                setEditingSessionId(s._id);
                setEditTitle(s.title || "New Conversation");
              }}
              className="p-1 text-muted-foreground hover:text-foreground rounded"
              title="Rename"
            >
              <Pencil className="w-3.5 h-3.5" />
            </button>
            <button 
              onClick={(e) => handleTogglePin(s._id, !!s.is_pinned, e)}
              className={cn("p-1 rounded", s.is_pinned ? "text-primary hover:text-primary hover:bg-primary/10" : "text-muted-foreground hover:text-foreground hover:bg-surface")}
              title={s.is_pinned ? "Unpin" : "Pin"}
            >
              <Pin className="w-3.5 h-3.5" />
            </button>
            <button 
              onClick={(e) => handleDeleteSession(s._id, e)}
              className="p-1 text-muted-foreground hover:text-destructive rounded"
              title="Delete"
            >
              <Trash2 className="w-3.5 h-3.5" />
            </button>
          </div>
        )}
      </div>
    );
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      setAttachedFiles(prev => [...prev, ...Array.from(e.dataTransfer.files)]);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    if (e.clipboardData.files && e.clipboardData.files.length > 0) {
      e.preventDefault();
      setAttachedFiles(prev => [...prev, ...Array.from(e.clipboardData.files)]);
    }
  };

  return (
    <div 
      className="flex h-screen bg-background"
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >

      {/* Drag Overlay */}
      {isDragging && (
        <div className="fixed inset-0 z-50 bg-black/40 backdrop-blur-sm flex items-center justify-center transition-all">
          <div className="bg-card rounded-3xl p-10 flex flex-col items-center shadow-2xl transform scale-105 transition-transform">
            <div className="w-20 h-20 bg-surface rounded-full flex items-center justify-center mb-6 text-muted-foreground">
              <Plus className="w-10 h-10" />
            </div>
            <h3 className="text-2xl font-bold text-foreground">Drop files here</h3>
            <p className="text-muted-foreground mt-2 text-center max-w-sm">
              Your files will be uploaded and attached to the current chat session.
            </p>
          </div>
        </div>
      )}

      {/* Sidebar (Chat History) */}
      {isHistoryOpen && (
        <div className="w-[260px] shrink-0 bg-background border-r border-border flex flex-col h-full transition-all">

          {/* Top Sidebar Header */}
          <div className="p-3 flex items-center justify-between">
            <button
              onClick={() => {
                setActiveSessionId(null);
                if(window.innerWidth < 1024) setIsHistoryOpen(false);
              }}
              className="flex items-center gap-2 px-3 py-2 text-foreground hover:bg-muted/50 rounded-lg transition-colors font-medium text-sm flex-1"
            >
              <div className="bg-muted rounded-full p-1"><Edit className="w-3.5 h-3.5" /></div>
              New chat
            </button>
            <button
              onClick={() => setIsHistoryOpen(false)}
              className="p-2 text-muted-foreground hover:bg-muted/50 rounded-lg transition-colors ml-1"
              title="Close sidebar"
            >
              <PanelLeftClose className="w-5 h-5" />
            </button>
          </div>



          {/* History Sections */}
          <div className="flex-1 overflow-y-auto px-3 space-y-6 pb-4">

            {/* Pinned Section */}
            {pinnedSessions.length > 0 && (
              <div>
                <h4 className="text-xs font-semibold text-muted-foreground px-3 mb-2">Pinned</h4>
                <div className="space-y-0.5">
                  {pinnedSessions.map(renderSessionItem)}
                </div>
              </div>
            )}

            {/* Recents Section */}
            <div>
              <h4 className="text-xs font-semibold text-muted-foreground px-3 mb-2">Recents</h4>
              <div className="space-y-0.5">
                {recentSessions.length > 0 ? (
                  recentSessions.map(renderSessionItem)
                ) : (
                  <div className="px-3 py-2 text-xs text-muted-foreground">No recent chats</div>
                )}
              </div>
            </div>

          </div>

          {/* User Profile Footer */}
          <div className="p-3 border-t border-border flex items-center justify-between">
            <button className="flex items-center gap-2 hover:bg-muted/50 px-2 py-1.5 rounded-lg transition-colors min-w-0">
              <div className="w-7 h-7 rounded-full bg-orange-200 text-orange-800 flex items-center justify-center text-xs font-bold shrink-0">
                {firstName.charAt(0).toUpperCase()}
              </div>
              <div className="flex flex-col items-start min-w-0">
                <span className="text-sm font-semibold text-foreground truncate">{userName}</span>
                <span className="text-[10px] text-muted-foreground truncate">Go</span>
              </div>
            </button>
            <button className="p-1.5 text-muted-foreground hover:bg-muted/50 rounded-lg">
              <Store className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}

      {/* Main Chat Area */}
      <div className="flex flex-col h-full flex-1 relative min-w-0 bg-card">

        {/* Top Header */}
        <div className="h-14 flex items-center justify-between px-4">
          <div className="flex items-center gap-2">
            {!isHistoryOpen && (
              <button onClick={() => setIsHistoryOpen(true)} className="p-2 text-muted-foreground hover:bg-surface rounded-lg transition-colors">
                <PanelLeftOpen className="w-5 h-5" />
              </button>
            )}
            <div className="flex items-center px-3 py-1.5">
              <span className="font-semibold text-foreground text-lg">FinanceGPT</span>
            </div>
          </div>
        </div>

        {loadingMessages ? (
          <div className="flex-1 flex items-center justify-center">
            <Loader2 className="w-8 h-8 text-muted-foreground animate-spin" />
          </div>
        ) : messages.length === 0 ? (
          <div className="flex-1 flex flex-col items-center justify-center px-6 overflow-y-auto">
            <h2 className="text-3xl font-semibold text-foreground mb-12">
              What's on your mind today?
            </h2>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto px-6 py-4 space-y-6">
            {messages.map((msg, i) => (
              <div
                key={i}
                className={cn(
                  "flex gap-4 max-w-3xl mx-auto w-full group",
                  msg.role === "user" ? "flex-row-reverse" : ""
                )}
              >
                {/* Avatar */}
                <div
                  className={cn(
                    "w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold shrink-0 mt-1",
                    msg.role === "user" ? "hidden" : "bg-card border border-border text-muted-foreground"
                  )}
                >
                  {msg.role !== "user" && <Bot className="w-5 h-5" />}
                </div>

                {/* Bubble */}
                <div
                  className={cn(
                    "px-4 py-2.5 text-[15px] leading-relaxed max-w-[85%]",
                    msg.role === "user"
                      ? "bg-surface text-foreground rounded-3xl"
                      : "bg-transparent text-foreground"
                  )}
                >
                  {msg.attachments && msg.attachments.length > 0 && (
                    <div className="flex flex-wrap gap-2 mb-2">
                      {msg.attachments.map((file, idx) => (
                        <div key={idx} className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs bg-muted text-foreground">
                          <Paperclip className="w-3 h-3" />
                          <span className="truncate max-w-[120px]">{file.name}</span>
                        </div>
                      ))}
                    </div>
                  )}
                  {/* Bubble Content */}
                  {editingMessageIndex === i ? (
                    <div className="flex flex-col gap-2 w-full min-w-[300px]">
                      <textarea
                        value={editMessageText}
                        onChange={(e) => setEditMessageText(e.target.value)}
                        className="w-full bg-card border border-border rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none min-h-[100px]"
                        autoFocus
                      />
                      <div className="flex items-center justify-end gap-2">
                        <button onClick={cancelEditMessage} className="px-4 py-1.5 text-sm font-medium text-muted-foreground bg-surface hover:bg-surface rounded-full transition-colors">Cancel</button>
                        <button onClick={() => submitEditMessage(i)} className="px-4 py-1.5 text-sm font-medium text-white bg-primary hover:bg-primary/90 rounded-full transition-colors">Send</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      {msg.content && <div className="whitespace-pre-wrap">{msg.content}</div>}
                      {msg.citations && msg.citations.length > 0 && (
                        <div className="mt-4 flex flex-col gap-2">
                          {msg.citations.map((c, ci) => {
                            const colors = [
                              "bg-primary/10 border-primary/50 text-primary",
                              "bg-purple-50 border-purple-200 text-purple-700",
                              "bg-success/10 border-success/50 text-success",
                              "bg-amber-50 border-amber-200 text-amber-700",
                              "bg-destructive/10 border-rose-200 text-destructive"
                            ];
                            const colorClass = colors[ci % colors.length];
                            return (
                              <div
                                key={ci}
                                className={`flex items-center justify-between gap-3 text-[12px] border px-3 py-2 rounded-xl transition-all hover:shadow-sm ${colorClass}`}
                              >
                                <div className="flex items-center gap-2 overflow-hidden flex-1">
                                  <FileText className="w-4 h-4 shrink-0 opacity-75" />
                                  <span className="font-medium truncate">{c.doc}</span>
                                  {c.field && (
                                    <span className="opacity-80 italic truncate text-[11px] ml-1 shrink-0 bg-black/5 px-1.5 py-0.5 rounded">
                                      {c.field.replace(/_/g, ' ')}
                                    </span>
                                  )}
                                </div>
                                <span className="shrink-0 opacity-80 text-[11px] font-bold bg-black/5 px-2 py-0.5 rounded-md">
                                  Page {c.page}
                                </span>
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </>
                  )}

                  {/* Message Actions */}
                  {editingMessageIndex !== i && (
                    <div className={cn(
                      "mt-2 flex items-center gap-1 transition-opacity opacity-100",
                      msg.role === "user" ? "justify-end" : "justify-start"
                    )}>
                      {msg.role === "user" && (
                        <button
                          onClick={() => handleEditMessage(i)}
                          className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-muted/50 rounded transition-colors"
                          title="Edit"
                        >
                          <Pencil className="w-3.5 h-3.5" />
                        </button>
                      )}

                      <button
                        onClick={() => handleCopy(msg.content, i)}
                        className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-muted/50 rounded transition-colors"
                        title="Copy"
                      >
                        {copiedIndex === i ? <CheckCheck className="w-3.5 h-3.5 text-green-600" /> : <Copy className="w-3.5 h-3.5" />}
                      </button>

                      {msg.role !== "user" && (
                        <button
                          onClick={() => handleRetry(i)}
                          className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-muted/50 rounded transition-colors"
                          title="Retry"
                          disabled={sending}
                        >
                          <RotateCcw className="w-3.5 h-3.5" />
                        </button>
                      )}
                    </div>
                  )}
                </div>
              </div>
            ))}
            {sending && (
              <div className="flex gap-4 max-w-3xl mx-auto w-full">
                <div className="w-8 h-8 rounded-full bg-card border border-border text-muted-foreground flex items-center justify-center mt-1">
                  <Bot className="w-5 h-5" />
                </div>
                <div className="bg-transparent px-4 py-3">
                  <div className="flex gap-1.5 items-center h-5">
                    <span className="w-2 h-2 bg-muted rounded-full animate-bounce [animation-delay:0ms]" />
                    <span className="w-2 h-2 bg-muted rounded-full animate-bounce [animation-delay:150ms]" />
                    <span className="w-2 h-2 bg-muted rounded-full animate-bounce [animation-delay:300ms]" />
                  </div>
                </div>
              </div>
            )}
            <div ref={bottomRef} />
          </div>
        )}

        {/* Floating Input Area */}
        <div className="px-4 pb-6 pt-2 w-full flex justify-center">
          <div className="w-full max-w-[48rem]">
            {attachedFiles.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-3 px-2">
                {attachedFiles.map((file, idx) => (
                  <div key={idx} className="group relative flex items-center gap-3 bg-[#202123] text-white pr-4 pl-2 py-2 rounded-2xl w-fit shadow-sm border border-slate-700">
                    <div className="w-10 h-10 rounded-xl bg-card/10 flex items-center justify-center shrink-0">
                      <FileText className="w-5 h-5 text-destructive fill-red-500/20" />
                    </div>
                    <div className="flex flex-col justify-center">
                      <span className="truncate max-w-[140px] text-sm font-medium leading-tight">{file.name}</span>
                      <span className="text-[11px] text-muted-foreground font-medium uppercase mt-0.5">
                        {file.name.split('.').pop() || "FILE"}
                      </span>
                    </div>
                    <button 
                      onClick={() => setAttachedFiles(prev => prev.filter((_, i) => i !== idx))} 
                      className="absolute -top-1.5 -right-1.5 w-5 h-5 bg-muted-foreground hover:bg-foreground text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity shadow-md"
                    >
                      <X className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className="relative flex items-center gap-2 border border-border rounded-[26px] bg-surface shadow-sm focus-within:bg-card focus-within:ring-1 focus-within:ring-slate-400 focus-within:border-border-strong transition-all px-2.5 py-2.5">

              <input
                type="file"
                multiple
                ref={fileInputRef}
                onClick={(e) => {
                  e.currentTarget.value = "";
                }}
                onChange={(e) => {
                  if (e.target.files && e.target.files.length > 0) {
                    setAttachedFiles(prev => [...prev, ...Array.from(e.target.files!)]);
                  }
                }}
                className="hidden"
              />

              <button 
                type="button"
                onClick={() => fileInputRef.current?.click()} 
                className="w-8 h-8 flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-surface rounded-full transition-colors shrink-0" 
                title="Attach file"
              >
                <Plus className="w-5 h-5" />
              </button>

              <textarea
                ref={textareaRef}
                rows={1}
                value={input}
                onChange={(e) => {
                  setInput(e.target.value);
                  e.target.style.height = "auto";
                  e.target.style.height = Math.min(e.target.scrollHeight, 200) + "px";
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage(input);
                  }
                }}
                onPaste={handlePaste}
                placeholder="Ask anything (or paste an image)"
                className="flex-1 bg-transparent resize-none outline-none text-[15px] text-foreground placeholder:text-muted-foreground min-h-[24px] max-h-[200px] py-1 self-center"
              />

              {(!input.trim() && attachedFiles.length === 0) ? (
                <button
                  onClick={handleVoiceInput}
                  disabled={sending}
                  className={cn(
                    "w-8 h-8 rounded-full flex items-center justify-center shrink-0 self-end transition-all",
                    isRecording 
                      ? "bg-destructive text-white animate-pulse shadow-md" 
                      : "bg-muted text-muted-foreground hover:bg-muted"
                  )}
                  title="Voice input"
                >
                  <Mic className="w-4 h-4" />
                </button>
              ) : (
                <button
                  disabled={sending}
                  onClick={() => sendMessage(input)}
                  className="w-8 h-8 rounded-full bg-black text-white flex items-center justify-center hover:bg-foreground disabled:opacity-40 transition-all shrink-0 self-end shadow-sm"
                >
                  {sending ? <Loader2 className="w-4 h-4 animate-spin" /> : <ArrowUp className="w-4 h-4" />}
                </button>
              )}
            </div>

            <p className="text-center text-[11px] text-muted-foreground mt-2">
              All answers are based strictly on your uploaded documents with verifiable citations.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useParams, useRouter, useSearchParams } from "next/navigation";
import {
  ShieldAlert,
  AlertTriangle,
  ChevronDown,
  ChevronUp,
  FileText,
  Loader2,
  Info,
  CheckCircle2,
  Filter,
  TriangleAlert,
  ShieldCheck,
  Check,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { fetcher } from "@/lib/api";

/* ΓöÇΓöÇ types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
interface Document {
  id: string;
  name: string;
  status: "pending" | "processing" | "ready" | "failed";
  uploaded_at: string;
}

interface RedFlag {
  id: string;
  severity: "High" | "Medium" | "Low";
  category: string;
  title: string;
  description: string;
  recommendation: string;
  source_doc: string;
  source_page: number;
  detected_at: string;
}
interface FlagsData {
  status?: string;
  total_flags: number;
  last_analyzed: string;
  flags: RedFlag[];
  filename?: string;
  company?: string;
}

/* ΓöÇΓöÇ severity config ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
const SEV: Record<
  string,
  {
    color: string;
    bg: string;
    border: string;
    barColor: string;
    icon: any;
    label: string;
  }
> = {
  High: {
    color: "text-destructive",
    bg: "bg-destructive/10",
    border: "border-destructive/50",
    barColor: "bg-destructive",
    icon: AlertTriangle,
    label: "High Risk",
  },
  Medium: {
    color: "text-orange-700",
    bg: "bg-orange-50",
    border: "border-orange-200",
    barColor: "bg-orange-500",
    icon: TriangleAlert,
    label: "Medium Risk",
  },
  Low: {
    color: "text-amber-700",
    bg: "bg-amber-50",
    border: "border-amber-200",
    barColor: "bg-amber-400",
    icon: ShieldAlert,
    label: "Low Risk",
  },
};

/* ΓöÇΓöÇ Page ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
export default function RedFlagsPage() {
  const params = useParams();
  const workspaceId = params.id as string;
  const router = useRouter();
  const searchParams = useSearchParams();
  
  const selectedDocumentId = searchParams.get("documentId");

  const [data, setData] = useState<FlagsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [docsLoading, setDocsLoading] = useState(true);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  
  const [expanded, setExpanded] = useState<string | null>(null);
  const [activeFilter, setActiveFilter] = useState<string>("all");

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setDropdownOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Fetch available documents
  useEffect(() => {
    fetcher<{ documents: Document[] }>(`/workspaces/${workspaceId}/documents`)
      .then((res) => setDocuments(res.documents || []))
      .catch(console.error)
      .finally(() => setDocsLoading(false));
  }, [workspaceId]);

  useEffect(() => {
    setLoading(true);
    const url = selectedDocumentId 
      ? `/workspaces/${workspaceId}/red-flags?document_id=${selectedDocumentId}`
      : `/workspaces/${workspaceId}/red-flags`;
      
    fetcher<FlagsData>(url)
      .then(setData)
      .catch(console.error)
      .finally(() => setLoading(false));
  }, [workspaceId, selectedDocumentId]);

  const handleSelectDocument = (docId: string) => {
    setDropdownOpen(false);
    const params = new URLSearchParams(searchParams.toString());
    params.set("documentId", docId);
    router.push(`?${params.toString()}`);
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "ready":
        return <span className="bg-emerald-100 text-success px-2 py-0.5 rounded text-[10px] font-bold uppercase">Ready</span>;
      case "processing":
        return <span className="bg-primary/20 text-primary px-2 py-0.5 rounded text-[10px] font-bold uppercase flex items-center gap-1"><Loader2 className="w-3 h-3 animate-spin"/> Processing</span>;
      case "failed":
        return <span className="bg-destructive/20 text-destructive px-2 py-0.5 rounded text-[10px] font-bold uppercase">Failed</span>;
      default:
        return <span className="bg-surface text-foreground px-2 py-0.5 rounded text-[10px] font-bold uppercase">{status}</span>;
    }
  };

  if (loading || docsLoading)
    return (
      <div className="flex-1 flex items-center justify-center py-24 text-muted-foreground">
        <Loader2 className="w-6 h-6 animate-spin mr-2" />
        Loading...
      </div>
    );

  const selectedDoc = (documents || []).find(d => d.id === selectedDocumentId);
  const displayTitle = selectedDoc?.name || data?.filename || data?.company || "Financial Document";
  const displayCompany = data?.company || "Company";

  let emptyState = null;
  if (!data || data.status === "running") {
    emptyState = (
      <div className="bg-card border border-border rounded-xl shadow-sm overflow-hidden flex flex-col items-center justify-center py-24 px-6 mt-6">
        <Loader2 className="w-10 h-10 animate-spin text-primary mb-5" />
        <h4 className="text-foreground font-bold text-lg mb-2">Analyzing Risks</h4>
        <p className="text-muted-foreground text-sm max-w-[400px] text-center mx-auto leading-relaxed">
          The Red Flag Agent is scanning your document for financial risks...
        </p>
      </div>
    );
  } else if (data.status === "failed") {
    emptyState = (
      <div className="bg-card border border-border rounded-xl shadow-sm overflow-hidden flex flex-col items-center justify-center py-24 px-6 mt-6">
        <div className="w-16 h-16 rounded-2xl bg-destructive/10 flex items-center justify-center mb-5 border border-red-100/50 shadow-sm">
          <Info className="w-7 h-7 text-destructive" />
        </div>
        <h4 className="text-foreground font-bold text-lg mb-2">Analysis Failed</h4>
        <p className="text-muted-foreground text-sm max-w-[400px] text-center mx-auto leading-relaxed">
          The Red Flag Agent encountered an error. Please retry from the Agent Status sidebar.
        </p>
      </div>
    );
  } else if (data.status === "blocked" || data.status === "pending" || data.status === "empty") {
    emptyState = (
      <div className="bg-card border border-border rounded-xl shadow-sm overflow-hidden flex flex-col items-center justify-center py-24 px-6 mt-6">
        <div className="w-16 h-16 rounded-2xl bg-surface flex items-center justify-center mb-5 border border-border/50 shadow-sm">
          <ShieldAlert className="w-7 h-7 text-muted-foreground" />
        </div>
        <h4 className="text-foreground font-bold text-lg mb-2">Risk Analysis Not Ready</h4>
        <p className="text-muted-foreground text-sm max-w-[400px] text-center mx-auto leading-relaxed">
          Upload and process a document to see risk flags. The agent may be waiting for prerequisite extraction steps.
        </p>
      </div>
    );
  } else if (data.status === "complete" && data.total_flags === 0) {
    emptyState = (
      <div className="bg-card border border-border rounded-xl shadow-sm overflow-hidden flex flex-col items-center justify-center py-24 px-6 mt-6">
        <div className="w-16 h-16 rounded-2xl bg-success/10 flex items-center justify-center mb-5 border border-emerald-100/50 shadow-sm">
          <ShieldCheck className="w-7 h-7 text-success" />
        </div>
        <h4 className="text-foreground font-bold text-lg mb-2">Risk Analysis Complete</h4>
        <p className="text-muted-foreground text-sm max-w-[400px] text-center mx-auto leading-relaxed">
          No significant risk flags identified. The document has been analyzed and cleared of major risks.
        </p>
      </div>
    );
  }

  const highCount = data?.flags?.filter((f) => f.severity === "High").length || 0;
  const medCount = data?.flags?.filter((f) => f.severity === "Medium").length || 0;
  const lowCount = data?.flags?.filter((f) => f.severity === "Low").length || 0;

  const filteredFlags =
    activeFilter === "all"
      ? data?.flags || []
      : data?.flags?.filter((f) => f.severity === activeFilter) || [];

  return (
    <div className="flex-1 overflow-y-auto">
      <div className="max-w-[1000px] mx-auto px-6 py-6 space-y-6">
        {/* ΓöÇΓöÇ Header & Document Selector ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <div className="flex items-center justify-between flex-wrap gap-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-destructive/20 text-destructive flex items-center justify-center shadow-sm">
              <ShieldAlert className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-lg font-bold text-foreground line-clamp-1">
                  Risk Flag Analysis
                </h2>
              </div>
              <p className="text-xs text-muted-foreground">
                {data?.total_flags || 0} risk factors identified ┬╖ Last analyzed{" "}
                {data?.last_analyzed || "Not analyzed"}
              </p>
            </div>
          </div>

          <div className="relative" ref={dropdownRef}>
            <button
              onClick={() => setDropdownOpen(!dropdownOpen)}
              className="group flex items-center gap-3 px-2.5 py-2.5 bg-card border border-border hover:border-destructive/50 hover:shadow-sm hover:shadow-red-100/50 rounded-xl text-sm font-medium transition-all min-w-[260px] max-w-sm w-full outline-none focus:ring-4 focus:ring-red-500/10"
            >
              <div className="w-9 h-9 rounded-lg bg-destructive/10/80 text-destructive flex items-center justify-center shrink-0 group-hover:bg-destructive/20 group-hover:text-destructive transition-colors">
                <FileText className="w-4 h-4" />
              </div>
              <div className="flex flex-col items-start flex-1 min-w-0 gap-0.5">
                <span className="text-[10px] uppercase tracking-wider font-bold text-muted-foreground leading-none">
                  Source Document
                </span>
                <span className="truncate w-full text-left font-semibold text-foreground leading-none">
                  {displayTitle}
                </span>
              </div>
              <div className="w-7 h-7 rounded-full bg-surface flex items-center justify-center shrink-0 ml-1 group-hover:bg-destructive/10 transition-colors">
                <ChevronDown className={cn("w-4 h-4 text-muted-foreground group-hover:text-destructive transition-transform duration-200", dropdownOpen && "rotate-180")} />
              </div>
            </button>

            {dropdownOpen && (
              <div className="absolute right-0 top-full mt-2 w-full sm:w-80 bg-card border border-border rounded-xl shadow-xl z-50 overflow-hidden flex flex-col max-h-[300px]">
                <div className="p-3 border-b border-border-subtle bg-surface/50">
                  <h3 className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Select Document</h3>
                </div>
                <div className="overflow-y-auto flex-1 p-1">
                  {documents.length === 0 ? (
                    <div className="p-4 text-center text-sm text-muted-foreground">No documents available</div>
                  ) : (
                    documents.map((doc) => {
                      const isSelected = selectedDocumentId === doc.id || (!selectedDocumentId && displayTitle === doc.name);
                      return (
                        <button
                          key={doc.id}
                          onClick={() => handleSelectDocument(doc.id)}
                          className={cn(
                            "w-full text-left px-3 py-2.5 rounded-lg flex items-start gap-3 transition-colors",
                            isSelected ? "bg-destructive/10" : "hover:bg-surface"
                          )}
                        >
                          <div className={cn("mt-0.5 shrink-0 w-4", isSelected ? "text-destructive" : "text-transparent")}>
                            <Check className="w-4 h-4" />
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-0.5">
                              <span className={cn("text-sm font-medium truncate", isSelected ? "text-red-900" : "text-foreground")}>
                                {doc.name}
                              </span>
                            </div>
                            <div className="flex items-center gap-2">
                              {getStatusBadge(doc.status)}
                              <span className="text-[10px] text-muted-foreground">
                                {doc.uploaded_at}
                              </span>
                            </div>
                          </div>
                        </button>
                      );
                    })
                  )}
                </div>
              </div>
            )}
          </div>
        </div>

        {emptyState ? (
          emptyState
        ) : (
          <>
            {/* ΓöÇΓöÇ Severity Summary Cards ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
            <div className="grid grid-cols-3 gap-4">
          {[
            { severity: "High", count: highCount, color: "red" },
            { severity: "Medium", count: medCount, color: "orange" },
            { severity: "Low", count: lowCount, color: "amber" },
          ].map((s) => {
            const cfg = SEV[s.severity];
            const Icon = cfg.icon;
            return (
              <button
                key={s.severity}
                onClick={() =>
                  setActiveFilter(
                    activeFilter === s.severity ? "all" : s.severity
                  )
                }
                className={cn(
                  "bg-card border rounded-xl p-4 shadow-sm text-left transition-all hover:shadow-md",
                  activeFilter === s.severity
                    ? cfg.border + " ring-2 ring-current/10"
                    : "border-border"
                )}
              >
                <div className="flex items-center justify-between mb-2">
                  <div
                    className={cn(
                      "w-9 h-9 rounded-lg flex items-center justify-center",
                      cfg.bg
                    )}
                  >
                    <Icon className={cn("w-4.5 h-4.5", cfg.color)} />
                  </div>
                  <span
                    className={cn(
                      "text-2xl font-extrabold",
                      cfg.color
                    )}
                  >
                    {s.count}
                  </span>
                </div>
                <p className={cn("text-xs font-bold", cfg.color)}>
                  {cfg.label}
                </p>
              </button>
            );
          })}
        </div>

        {/* ΓöÇΓöÇ Severity Distribution Bar ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <div className="bg-card border border-border rounded-xl p-4 shadow-sm">
          <p className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-3">
            Severity Distribution
          </p>
          <div className="flex h-3 rounded-full overflow-hidden gap-0.5">
            {highCount > 0 && (
              <div
                className="bg-destructive rounded-l-full transition-all duration-500"
                style={{
                  width: `${(highCount / (data?.total_flags || 1)) * 100}%`,
                }}
              />
            )}
            {medCount > 0 && (
              <div
                className="bg-orange-400 transition-all duration-500"
                style={{
                  width: `${(medCount / (data?.total_flags || 1)) * 100}%`,
                }}
              />
            )}
            {lowCount > 0 && (
              <div
                className="bg-amber-300 rounded-r-full transition-all duration-500"
                style={{
                  width: `${(lowCount / (data?.total_flags || 1)) * 100}%`,
                }}
              />
            )}
          </div>
          <div className="flex items-center justify-between mt-2">
            <div className="flex items-center gap-4 text-[11px]">
              <span className="flex items-center gap-1.5">
                <span className="w-2.5 h-2.5 bg-destructive rounded-full" />
                <span className="text-muted-foreground">High ({highCount})</span>
              </span>
              <span className="flex items-center gap-1.5">
                <span className="w-2.5 h-2.5 bg-orange-400 rounded-full" />
                <span className="text-muted-foreground">Medium ({medCount})</span>
              </span>
              <span className="flex items-center gap-1.5">
                <span className="w-2.5 h-2.5 bg-amber-300 rounded-full" />
                <span className="text-muted-foreground">Low ({lowCount})</span>
              </span>
            </div>
            {activeFilter !== "all" && (
              <button
                onClick={() => setActiveFilter("all")}
                className="text-[11px] text-primary font-medium hover:underline"
              >
                Clear filter
              </button>
            )}
          </div>
        </div>

        {/* ΓöÇΓöÇ Risk Cards ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <div className="space-y-3">
          {filteredFlags.map((flag) => {
            const cfg = SEV[flag.severity] || SEV.Low;
            const Icon = cfg.icon;
            const isOpen = expanded === flag.id;

            return (
              <div
                key={flag.id}
                className={cn(
                  "bg-card rounded-xl overflow-hidden shadow-sm transition-all border-l-4",
                  flag.severity === "High"
                    ? "border-l-red-500 border border-red-100"
                    : flag.severity === "Medium"
                    ? "border-l-orange-500 border border-orange-100"
                    : "border-l-amber-400 border border-amber-100"
                )}
              >
                <button
                  onClick={() => setExpanded(isOpen ? null : flag.id)}
                  className="w-full text-left px-5 py-4 flex items-start gap-4 hover:bg-surface/60 transition-colors"
                >
                  <div
                    className={cn(
                      "w-10 h-10 rounded-xl flex items-center justify-center shrink-0 mt-0.5",
                      cfg.bg
                    )}
                  >
                    <Icon className={cn("w-5 h-5", cfg.color)} />
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap mb-1">
                      <span
                        className={cn(
                          "text-[11px] font-extrabold uppercase px-2 py-0.5 rounded-full border tracking-wide",
                          cfg.color,
                          cfg.bg,
                          cfg.border
                        )}
                      >
                        {flag.severity}
                      </span>
                      <span className="text-[11px] text-muted-foreground bg-surface px-2 py-0.5 rounded-full font-medium">
                        {flag.category}
                      </span>
                    </div>
                    <h4 className="text-sm font-bold text-foreground leading-snug">
                      {flag.title}
                    </h4>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      {flag.detected_at && flag.detected_at !== "Unknown" 
                        ? new Date(flag.detected_at).toLocaleString('en-US', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }).replace(',', ' ΓÇó')
                        : "Unknown"}
                    </p>
                  </div>

                  <div className="shrink-0 mt-1 text-muted-foreground">
                    {isOpen ? (
                      <ChevronUp className="w-4 h-4" />
                    ) : (
                      <ChevronDown className="w-4 h-4" />
                    )}
                  </div>
                </button>

                {isOpen && (
                  <div className="px-5 pb-5 pt-0 border-t border-border-subtle">
                    <div className="ml-14 space-y-4 mt-4">
                      <div>
                        <p className="text-[11px] font-bold text-muted-foreground uppercase tracking-wider mb-1">
                          Description
                        </p>
                        <p className="text-sm text-foreground leading-relaxed">
                          {flag.description}
                        </p>
                      </div>
                      <div className="bg-success/10 border border-emerald-100 rounded-lg p-3">
                        <p className="text-[11px] font-bold text-success uppercase tracking-wider mb-1">
                          Recommendation
                        </p>
                        <p className="text-sm text-emerald-800 leading-relaxed">
                          {flag.recommendation}
                        </p>
                      </div>
                      <div className="flex items-center gap-2 pt-1">
                        <FileText className="w-3.5 h-3.5 text-primary" />
                        <span className="text-xs text-primary font-medium hover:underline cursor-pointer">
                          {flag.source_doc} ΓÇö Page {flag.source_page}
                        </span>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* ΓöÇΓöÇ Resolved Section ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        {data?.status === "complete" && highCount > 0 && (
          <div className="bg-success/10 border border-success/50 rounded-xl p-5 flex items-start gap-4">
            <div className="w-10 h-10 rounded-xl bg-emerald-100 flex items-center justify-center shrink-0">
              <CheckCircle2 className="w-5 h-5 text-success" />
            </div>
            <div>
              <h4 className="text-sm font-bold text-emerald-800">
                Risk Mitigation in Progress
              </h4>
              <p className="text-xs text-success mt-1 leading-relaxed">
                All high-severity flags have been flagged for management review.
                The AI will continue monitoring documents for new risk indicators
                and update this analysis automatically.
              </p>
            </div>
          </div>
        )}
          </>
        )}

      </div>
    </div>
  );
}

