"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { useParams, useRouter } from "next/navigation";
import { Document, Page, pdfjs } from 'react-pdf';
import 'react-pdf/dist/Page/AnnotationLayer.css';
import 'react-pdf/dist/Page/TextLayer.css';
import {
  ChevronLeft, Download, Share2, RotateCcw, ZoomIn, ZoomOut,
  ChevronRight, Check, AlertTriangle, Loader2
} from "lucide-react";
import { cn } from "@/lib/utils";
import { fetcher, fetchBlob } from "@/lib/api";

// Use standard CDN for pdf.js worker
pdfjs.GlobalWorkerOptions.workerSrc = `//unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`;

interface ReportData {
  id: string;
  title: string;
  summary: string;
  status: string;
  pages: number;
  type: string;
  workspace_name: string;
}

export default function ReportPreviewPage() {
  const params = useParams();
  const router = useRouter();
  const workspaceId = params.id as string;
  const reportId = params.reportId as string;
  const mainRef = useRef<HTMLDivElement>(null);

  const [activePage, setActivePage] = useState(1);
  const [numPages, setNumPages] = useState<number>(0);
  const [zoom, setZoom] = useState(100);
  const [report, setReport] = useState<ReportData | null>(null);
  const [loading, setLoading] = useState(true);
  const [pdfBlobUrl, setPdfBlobUrl] = useState<string | null>(null);
  const [pdfError, setPdfError] = useState<string | null>(null);
  const [isRegenerating, setIsRegenerating] = useState(false);

  const [reportError, setReportError] = useState<string | null>(null);

  // Fetch report metadata
  useEffect(() => {
    (async () => {
      try {
        const res = await fetcher<ReportData>(`/reports/${reportId}`);
        setReport(res);
      } catch (e: any) {
        setReportError(e.message || "Report not found");
      }
    })();
  }, [workspaceId, reportId]);

  // Fetch PDF blob
  const loadPdf = useCallback(async () => {
    try {
      setLoading(true);
      setPdfError(null);
      const blob = await fetchBlob(`/reports/${reportId}/download`);
      const url = URL.createObjectURL(blob);

      // Cleanup previous url
      if (pdfBlobUrl) {
        URL.revokeObjectURL(pdfBlobUrl);
      }

      setPdfBlobUrl(url);
    } catch (e: any) {
      setPdfError(e.message || "Failed to load PDF");
    } finally {
      setLoading(false);
    }
  }, [reportId]);

  useEffect(() => {
    loadPdf();

    return () => {
      if (pdfBlobUrl) URL.revokeObjectURL(pdfBlobUrl);
    };
  }, [loadPdf]);

  const onDocumentLoadSuccess = ({ numPages }: { numPages: number }) => {
    setNumPages(numPages);
  };

  const scrollToPage = useCallback((pageNum: number) => {
    setActivePage(pageNum);
    const el = document.getElementById(`pdf-page-${pageNum}`);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  }, []);

  const handleZoomIn = () => setZoom((z) => Math.min(z + 25, 200));
  const handleZoomOut = () => setZoom((z) => Math.max(z - 25, 50));

  const handleDownload = () => {
    if (!pdfBlobUrl || !report) return;
    const a = document.createElement("a");
    a.href = pdfBlobUrl;
    a.download = `${report.title.replace(/\s+/g, "-")}.pdf`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const handleRegenerate = async () => {
    try {
      setIsRegenerating(true);
      // Wait for backend to regenerate
      await fetcher(`/reports/${reportId}/regenerate`, { method: "POST" });

      // Reload PDF
      await loadPdf();

      // Also reload metadata to get updated dates etc
      const res = await fetcher<ReportData>(`/reports/${reportId}`);
      setReport(res);

      setActivePage(1);
    } catch (e: any) {
      alert(`Failed to regenerate: ${e.message}`);
    } finally {
      setIsRegenerating(false);
    }
  };

  return (
    <div className="flex-1 flex flex-col min-w-0 bg-surface min-h-full">
      {/* Top Header */}
      <div className="bg-card border-b border-border px-6 py-4 flex items-center justify-between shrink-0 z-10">
        <div className="flex items-center gap-4">
          <h1 className="text-xl font-bold text-foreground leading-none tracking-tight whitespace-nowrap">
            PDF Preview
          </h1>
          <div className="w-px h-6 bg-border mx-1" />
          <span className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-surface border border-border shadow-sm truncate max-w-[500px]">
            <Check className="w-3.5 h-3.5 shrink-0 text-primary" /> <span className="truncate text-xs font-semibold text-muted-foreground">{report?.title || "Generated Successfully"}</span>
          </span>
        </div>

        <div className="flex items-center gap-3">
          <button 
            disabled={isRegenerating || loading}
            onClick={handleRegenerate} 
            className="flex items-center gap-2 px-4 py-2 bg-surface hover:bg-surface/80 border border-border text-sm font-bold text-foreground rounded-lg shadow-sm transition-colors disabled:opacity-50 whitespace-nowrap"
          >
            {isRegenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <RotateCcw className="w-4 h-4" />} 
            Regenerate
          </button>
          <button 
            disabled={!pdfBlobUrl}
            onClick={handleDownload} 
            className="flex items-center gap-2 px-4 py-2 bg-primary hover:bg-primary/90 text-primary-foreground text-sm font-bold rounded-lg shadow-sm transition-colors disabled:opacity-50 whitespace-nowrap"
          >
            <Download className="w-4 h-4" /> Download PDF
          </button>
          <div className="relative flex items-center group">
            <button className="flex items-center gap-2 px-4 py-2 bg-surface border border-border text-sm font-bold text-muted-foreground rounded-lg transition-colors opacity-50 cursor-not-allowed whitespace-nowrap">
              <Share2 className="w-4 h-4" /> Share Link
            </button>
            <span className="absolute -top-2.5 -right-2.5 px-2 py-0.5 bg-primary border border-primary/20 shadow-md text-[9px] font-black text-primary-foreground uppercase tracking-wider rounded-full">
              Soon
            </span>
          </div>
        </div>
      </div>

      {loading ? (
        <div className="flex-1 flex flex-col items-center justify-center">
          <Loader2 className="w-8 h-8 text-primary animate-spin mb-4" />
          <p className="text-muted-foreground font-medium">Loading actual report PDF...</p>
        </div>
      ) : reportError ? (
        <div className="flex-1 flex flex-col items-center justify-center">
          <AlertTriangle className="w-12 h-12 text-destructive mb-4" />
          <h2 className="text-xl font-bold text-foreground mb-2">Report Not Found</h2>
          <p className="text-muted-foreground mb-6 max-w-md text-center">{reportError}</p>
          <div className="flex items-center gap-4">
            <button onClick={() => router.push(`/workspace/${workspaceId}/reports`)} className="px-4 py-2 bg-primary text-white font-bold rounded-lg">
              Back to Reports
            </button>
          </div>
        </div>
      ) : pdfError ? (
        <div className="flex-1 flex flex-col items-center justify-center">
          <AlertTriangle className="w-12 h-12 text-destructive mb-4" />
          <h2 className="text-xl font-bold text-foreground mb-2">Unable to load PDF</h2>
          <p className="text-muted-foreground mb-6 max-w-md text-center">{pdfError}</p>
          <div className="flex items-center gap-4">
            <button onClick={loadPdf} className="px-4 py-2 bg-primary text-white font-bold rounded-lg">
              Retry
            </button>
          </div>
        </div>
      ) : (
        <div className="flex-1 flex min-w-0 overflow-hidden">
          {/* Left Sidebar ΓÇô Page Thumbnails */}
          <div className="w-64 bg-card border-r border-border overflow-y-auto shrink-0 flex flex-col hidden md:flex">
            <div className="p-4 border-b border-border sticky top-0 bg-card z-10 flex items-center justify-between">
              <h3 className="text-sm font-bold text-foreground uppercase tracking-widest">Pages</h3>
              <span className="text-xs font-bold px-2 py-0.5 rounded-full bg-surface text-muted-foreground border border-border">{numPages}</span>
            </div>
            <div className="p-4 flex flex-col gap-6">
              <Document file={pdfBlobUrl} loading={null}>
                {Array.from(new Array(numPages), (el, index) => (
                  <button
                    key={`thumb_${index + 1}`}
                    onClick={() => scrollToPage(index + 1)}
                    className="w-full text-left group focus:outline-none"
                  >
                    <div className={cn(
                      "w-full rounded shadow-sm mb-2 flex flex-col overflow-hidden border-2 transition-all",
                      activePage === index + 1
                        ? "border-primary/50 ring-2 ring-primary/20"
                        : "border-border group-hover:border-primary/30"
                    )}>
                      <Page
                        pageNumber={index + 1}
                        width={200}
                        renderTextLayer={false}
                        renderAnnotationLayer={false}
                        className="w-full pointer-events-none"
                      />
                    </div>
                    <p className={cn("text-xs font-bold pl-1", activePage === index + 1 ? "text-primary" : "text-foreground")}>
                      Page {index + 1}
                    </p>
                  </button>
                ))}
              </Document>
            </div>
          </div>

          {/* Main PDF View */}
          <div className="flex-1 flex flex-col min-w-0 bg-surface">

            {/* Main Toolbar */}
            <div className="h-14 bg-card border-b border-border flex items-center justify-center gap-8 px-4 shrink-0 shadow-sm z-10">
              <div className="flex items-center gap-1 bg-surface p-1 rounded-lg border border-border shadow-sm">
                <button onClick={() => scrollToPage(Math.max(1, activePage - 1))} className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-background rounded-md transition-colors">
                  <ChevronLeft className="w-4 h-4" />
                </button>
                <div className="flex items-center justify-center text-sm font-bold text-foreground min-w-[70px]">
                  <span>{activePage}</span>
                  <span className="text-muted-foreground mx-1">/</span>
                  <span className="text-muted-foreground">{numPages}</span>
                </div>
                <button onClick={() => scrollToPage(Math.min(numPages, activePage + 1))} className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-background rounded-md transition-colors">
                  <ChevronRight className="w-4 h-4" />
                </button>
              </div>

              <div className="flex items-center gap-1 bg-surface p-1 rounded-lg border border-border shadow-sm">
                <button onClick={handleZoomOut} className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-background rounded-md transition-colors">
                  <ZoomOut className="w-4 h-4" />
                </button>
                <span className="text-sm font-bold text-foreground w-12 text-center">{zoom}%</span>
                <button onClick={handleZoomIn} className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-background rounded-md transition-colors">
                  <ZoomIn className="w-4 h-4" />
                </button>
              </div>

              <button onClick={() => setZoom(100)} className="px-3 py-2 text-sm font-bold text-muted-foreground hover:text-foreground hover:bg-surface rounded-lg transition-colors border border-transparent hover:border-border">
                Reset Zoom
              </button>
            </div>

            <div ref={mainRef} className="flex-1 overflow-auto min-w-0 p-8 flex flex-col items-center gap-8 relative bg-[#1E1E24]">
              <Document
                file={pdfBlobUrl}
                onLoadSuccess={onDocumentLoadSuccess}
                loading={
                  <div className="flex flex-col items-center py-20">
                    <Loader2 className="w-8 h-8 text-primary animate-spin" />
                  </div>
                }
                error={
                  <div className="p-8 bg-destructive/10 text-destructive rounded-lg border border-destructive/20 font-medium">
                    Failed to render PDF document. It may be corrupted or invalid.
                  </div>
                }
              >
                {Array.from(new Array(numPages), (el, index) => (
                  <div
                    key={`page_${index + 1}`}
                    id={`pdf-page-${index + 1}`}
                    className="w-full mb-8 flex justify-center"
                  >
                    <div className="shadow-[0_8px_30px_rgb(0,0,0,0.4)]">
                        <Page
                          pageNumber={index + 1}
                          scale={zoom / 100}
                          renderTextLayer={true}
                          renderAnnotationLayer={true}
                          className="max-w-full bg-white"
                        />
                    </div>
                  </div>
                ))}
              </Document>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
