interface ReportStatusResponse {
  report_id: string;
  status: "pending" | "running" | "completed" | "failed" | "blocked";
  pipeline_stage: string;
  agent_counts: {
    documents_processed?: number;
    metrics_found?: number;
    risks_found?: number;
    comparisons_found?: number;
    research_found?: number;
  };
  error_message?: string;
}

/* ΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
const DEFAULT_SECTIONS: Section[] = [
  {
    id: "exec_summary",
    label: "Executive Summary",
    description: "AI-generated summary of key findings",
    icon: <FileText className="w-4 h-4" />,
    enabled: true,
    children: [
      { label: "High-level overview highlighting revenue growth, profitability, key ratios, and major takeaways.", previewText: "~ 1 page" }
    ],
  },
  {
