    enabled: true,
    children: [{ label: "Financial Analysis", previewText: "~ 2 pages" }],
  },
  {
    id: "financial_performance",
    label: "Financial Performance & Trends",
    description: "Deep dive into financial numbers",
    icon: <TrendingUp className="w-4 h-4" />,
    enabled: true,
    children: [{ label: "Performance Metrics", previewText: "~ 3 pages" }],
  },
  {
