    enabled: true,
    children: [{ label: "Insights", previewText: "~ 1 page" }],
  },
  {
    id: "conclusion",
    label: "Conclusion",
    description: "Final thoughts and summary",
    icon: <Shield className="w-4 h-4" />,
    enabled: true,
    children: [{ label: "Conclusion", previewText: "~ 1 page" }],
  },
];

const PIPELINE_STAGES = [
  "Initializing Financial Report Agent",
  "Aggregating Source Documents",
  "Extracting Key Financial Metrics",
  "Running Risk & Sentiment Analysis",
  "Generating AI Strategic Insights",
  "Building Data-Driven Charts",
  "Rendering Premium PDF Layout",
  "Report Ready"
];

/* ΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
export default function GenerateReportPage() {
  const params = useParams();
  const router = useRouter();
  const workspaceId = params.id as string;

  const [step, setStep] = useState<1 | 2 | 3 | 4>(1); // 1: Scope, 2: Preview, 3: Generating, 4: Success
  const [docs, setDocs] = useState<any[]>([]);
  const [redFlagCount, setRedFlagCount] = useState(0);
  const [sections, setSections] = useState(DEFAULT_SECTIONS);
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set(["exec_summary"]));

  const [isGenerating, setIsGenerating] = useState(false);
  const [generationError, setGenerationError] = useState<string | null>(null);
  const [reportId, setReportId] = useState<string | null>(null);
  const [isDownloading, setIsDownloading] = useState(false);

  const [statusData, setStatusData] = useState<ReportStatusResponse | null>(null);

  // Fetch real documents
  useEffect(() => {
    if (!workspaceId) return;
    fetcher<any>(`/workspaces/${workspaceId}/documents`)
      .then((res) => {
        const documents = res.documents || res || [];
        setDocs(documents.map((d: any) => ({ ...d, selected: true })));
      })
      .catch(console.error);

    // Fetch red flag count for badge
    fetcher<any>(`/workspaces/${workspaceId}/red-flags`)
      .then((res) => {
        setRedFlagCount(res.total_flags || 0);
        setSections((prev) =>
          prev.map((s) =>
            s.id === "risk_analysis"
              ? {
                  ...s,
                  children: [
                    {
                      label: "Identified Risks",
                      badge: `${res.total_flags || 0} flags`,
                      badgeColor: "bg-destructive/20 text-destructive",
                    },
                  ],
                }
              : s
          )
        );
      })
      .catch(console.error);
  }, [workspaceId]);

  // Update comparative analysis badge when docs change
  useEffect(() => {
    const selectedCount = docs.filter((d) => d.selected).length;
    setSections((prev) =>
      prev.map((s) =>
        s.id === "comparative_analysis"
          ? {
              ...s,
              autoEnabled: selectedCount >= 2,
              children: [
                {
                  label: "Peer Comparison",
                  badge: selectedCount >= 2 ? `${selectedCount} companies` : undefined,
                  badgeColor: "bg-primary/20 text-primary",
                },
              ],
            }
          : s
      )
    );
  }, [docs]);

  // Polling Mechanism
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (step === 3 && reportId) {
      interval = setInterval(async () => {
        try {
          const res = await fetcher<ReportStatusResponse>(`/workspaces/${workspaceId}/reports/${reportId}/status`);
          setStatusData(res);
          if (res.status === "completed") {
            setStep(4);
            clearInterval(interval);
          } else if (res.status === "failed") {
            setGenerationError(res.error_message || "Generation failed during pipeline execution.");
            clearInterval(interval);
          }
        } catch (e) {
          console.error("Polling error:", e);
        }
      }, 2000);
    }
    return () => clearInterval(interval);
  }, [step, reportId, workspaceId]);

  const toggleDoc = (id: string) => {
    setDocs((prev) => prev.map((d) => (d.id === id ? { ...d, selected: !d.selected } : d)));
  };

  const toggleSection = (id: string) => {
    setSections((prev) => prev.map((s) => (s.id === id ? { ...s, enabled: !s.enabled } : s)));
  };

  const toggleExpand = (id: string) => {
    setExpandedSections((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const selectedDocs = docs.filter((d) => d.selected);
  const selectedDocCount = selectedDocs.length;

  const getFirebaseToken = useCallback(async (): Promise<string | null> => {
    try {
      const user = auth.currentUser;
      if (user) return await getIdToken(user);
    } catch {}
    return null;
  }, []);

  const downloadReport = useCallback(async (rid: string) => {
    try {
      const token = await getFirebaseToken();
      const baseUrl = API_BASE_URL;
      const url = `${baseUrl}/workspaces/${workspaceId}/reports/${rid}/download`;
      const headers: Record<string, string> = {};
      if (token) headers["Authorization"] = `Bearer ${token}`;

      const response = await fetch(url, { headers });
      if (!response.ok) {
        throw new Error(`Download failed: ${response.status}`);
      }
      const blob = await response.blob();
      const blobUrl = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = blobUrl;
      a.download = `AstraFinance_Report.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      window.URL.revokeObjectURL(blobUrl);
    } catch (e) {
      console.error("Download error:", e);
      alert("Failed to download report. Please try again.");
    }
  }, [workspaceId, getFirebaseToken]);

  const handleDownload = async () => {
    if (!reportId) return;
    setIsDownloading(true);
    await downloadReport(reportId);
    setIsDownloading(false);
  };

  const handleClose = () => {
    router.push(`/workspace/${workspaceId}/reports`);
  };

  const startGeneration = async () => {
    setStep(3);
    setIsGenerating(true);
    setGenerationError(null);
    setStatusData(null);

    const selectedDocIds = selectedDocs.map((d) => d.id);
    const enabledSections = sections.filter((s) => s.enabled).map((s) => ({ id: s.id, label: s.label }));

    try {
      const res = await fetcher<{ report_id: string }>(`/workspaces/${workspaceId}/reports/generate`, {
        method: "POST",
        body: JSON.stringify({
          title: "AstraFinance AI Report",
          report_type: "Full Analysis",
          documents: selectedDocIds,
          sections: enabledSections,
        }),
      });

      setReportId(res.report_id);
    } catch (e: any) {
      console.error("Failed to generate report", e);
      setGenerationError(e.message || "An error occurred while generating the report.");
      setIsGenerating(false);
    }
  };

  const currentStageIndex = statusData 
    ? PIPELINE_STAGES.findIndex(s => s === statusData.pipeline_stage) 
    : 0;

  return (
    <div className="fixed inset-0 z-50 bg-foreground/60 backdrop-blur-md overflow-y-auto flex items-start justify-center p-4 sm:p-6 md:p-8">
      <motion.div 
        initial={{ opacity: 0, scale: 0.95, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        className="bg-card w-full max-w-5xl rounded-2xl shadow-2xl flex flex-col overflow-hidden my-auto"
      >

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-5 border-b border-border-subtle bg-card sticky top-0 z-10">
          <div>
            <h2 className="text-2xl font-bold text-foreground">Report Generator</h2>
            <p className="text-sm text-muted-foreground mt-1">Compile and synthesize agent data into a professional document</p>
          </div>
          <button
            onClick={handleClose}
            className="p-2 text-muted-foreground hover:text-foreground hover:bg-surface rounded-full transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Stepper */}
        {step < 3 && (
          <div className="flex items-center justify-between px-8 py-4 bg-surface border-b border-border-subtle text-sm font-medium">
            <div className={cn("flex items-center gap-3 transition-colors", step === 1 ? "text-primary" : "text-muted-foreground")}>
              <div className={cn("w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold shadow-sm transition-colors", step === 1 ? "bg-primary text-white" : "bg-card border border-border text-muted-foreground")}>1</div>
              Select Scope
            </div>
            <div className="flex-1 h-px bg-muted mx-6" />
            <div className={cn("flex items-center gap-3 transition-colors", step === 2 ? "text-primary" : "text-muted-foreground")}>
              <div className={cn("w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold shadow-sm transition-colors", step === 2 ? "bg-primary text-white" : "bg-card border border-border text-muted-foreground")}>2</div>
              Preview Outline
            </div>
            <div className="flex-1 h-px bg-muted mx-6" />
            <div className="flex items-center gap-3 text-muted-foreground">
              <div className="w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold shadow-sm bg-card border border-border text-muted-foreground">3</div>
              Generate
            </div>
          </div>
        )}

        {/* Content Body */}
        <div className="p-5 md:p-6 max-h-[85vh] overflow-y-auto w-full [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
          {step === 1 && (
            <motion.div 
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              className="space-y-6"
            >
              {/* Documents */}
              <div>
                <h3 className="text-lg font-bold text-foreground mb-1">Select Documents</h3>
                <p className="text-sm text-muted-foreground mb-3">Choose the financial documents to analyze.</p>
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                  {docs.map((doc) => (
                    <div 
                      key={doc.id} 
                      onClick={() => toggleDoc(doc.id)}
                      className={cn(
                        "flex items-center gap-3 p-3 rounded-xl border-2 cursor-pointer transition-all",
                        doc.selected ? "border-primary bg-primary/10 shadow-sm" : "border-border-subtle bg-card hover:border-border"
                      )}
                    >
                      <div className={cn("w-5 h-5 rounded flex items-center justify-center border transition-colors shrink-0", doc.selected ? "bg-primary border-primary text-white" : "bg-card border-border")}>
                        {doc.selected && <Check className="w-3.5 h-3.5" />}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-semibold text-foreground truncate">{doc.name || doc.filename}</p>
                      </div>
                    </div>
                  ))}
                  {docs.length === 0 && (
                    <div className="col-span-full p-6 text-center text-sm text-muted-foreground border-2 border-dashed border-border rounded-xl bg-surface">
                      No documents available in this workspace.
                    </div>
                  )}
                </div>
              </div>

              {/* Sections */}
              <div>
                <h3 className="text-lg font-bold text-foreground mb-1">Include Sections</h3>
                <p className="text-sm text-muted-foreground mb-3">Toggle the modules you want to include in the final report.</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {sections.map((sec) => (
                    <div 
                      key={sec.id} 
                      onClick={() => toggleSection(sec.id)}
                      className={cn(
                        "flex items-center justify-between p-3 rounded-xl border transition-all cursor-pointer select-none", 
                        sec.enabled 
                          ? "bg-surface border-primary/30 shadow-sm" 
                          : "bg-card border-border hover:border-border-strong opacity-80 hover:opacity-100"
                      )}
                    >
                      <div className="flex items-center gap-3">
                        <div className={cn(
                          "w-8 h-8 rounded-lg border flex items-center justify-center shadow-sm shrink-0 transition-colors",
                          sec.enabled ? "bg-primary/10 border-primary/20 text-primary" : "bg-surface border-border text-muted-foreground"
                        )}>
                          {sec.icon}
                        </div>
                        <div>
                          <p className={cn("text-sm font-semibold transition-colors", sec.enabled ? "text-foreground" : "text-foreground/80")}>{sec.label}</p>
                          <p className="text-xs text-muted-foreground mt-0.5 line-clamp-1">{sec.description}</p>
                        </div>
                      </div>
                      <div
                        className={cn(
                          "peer inline-flex h-6 w-11 shrink-0 items-center rounded-full border-2 border-transparent transition-colors focus-visible:outline-none",
                          sec.enabled ? "bg-primary" : "bg-muted-foreground/30"
                        )}
                      >
                        <span className={cn(
                          "pointer-events-none block h-5 w-5 rounded-full bg-white shadow-md ring-0 transition-transform",
                          sec.enabled ? "translate-x-5" : "translate-x-0"
                        )} />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </motion.div>
          )}

          {step === 2 && (
            <motion.div 
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              className="space-y-6"
            >
              <div className="flex items-center justify-between mb-4">
                <div>
                  <h3 className="text-lg font-bold text-foreground">Report Outline Preview</h3>
                  <p className="text-sm text-muted-foreground">Review the estimated structure before generating.</p>
                </div>
                <div className="text-right bg-surface px-4 py-2 rounded-lg border border-border-subtle">
                  <p className="text-sm font-bold text-foreground">{sections.filter(s => s.enabled).length} Sections</p>
                  <p className="text-xs text-muted-foreground font-medium">~15-20 pages estimated</p>
                </div>
              </div>

              <div className="space-y-3">
                {sections.filter(s => s.enabled).map((sec, idx) => {
                  const isExpanded = expandedSections.has(sec.id);
                  return (
                    <div key={sec.id} className={cn("border rounded-xl transition-all duration-200", isExpanded ? "border-primary/50 bg-primary/10/40 shadow-sm" : "border-border bg-card hover:border-border")}>
                      <button 
                        className="flex items-center w-full p-4 text-left focus:outline-none"
                        onClick={() => toggleExpand(sec.id)}
                      >
                        <div className="w-8 h-8 rounded-full bg-primary/20 text-primary flex items-center justify-center text-sm font-bold shrink-0 mr-4 shadow-sm">
                          {idx + 1}
                        </div>
                        <span className="text-base font-semibold text-foreground flex-1">{sec.label}</span>
                        <ChevronDown className={cn("w-5 h-5 text-muted-foreground transition-transform duration-200", isExpanded && "rotate-180")} />
                      </button>
                      <AnimatePresence>
                        {isExpanded && (
                          <motion.div 
                            initial={{ height: 0, opacity: 0 }}
                            animate={{ height: "auto", opacity: 1 }}
                            exit={{ height: 0, opacity: 0 }}
                            className="overflow-hidden"
                          >
                            <div className="px-4 pb-4 pt-1 ml-12">
                              <p className="text-sm text-muted-foreground bg-card p-4 rounded-xl border border-border-subtle shadow-sm">
                                {sec.description}
                                {sec.children?.[0]?.previewText && (
                                  <span className="block mt-3 text-xs font-semibold text-primary bg-primary/10 w-fit px-2 py-1 rounded-md">
                                    Estimated length: {sec.children[0].previewText}
                                  </span>
                                )}
                              </p>
                            </div>
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  );
                })}
              </div>
            </motion.div>
          )}

          {step === 3 && (
            <motion.div 
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              className="py-8 flex flex-col md:flex-row gap-8 items-start w-full"
            >
              {generationError ? (
                <div className="w-full flex flex-col items-center justify-center text-center py-12 px-6">
                  <div className="relative mb-8">
                    <div className="w-24 h-24 rounded-full bg-destructive/10 flex items-center justify-center border border-destructive/20 shadow-[0_0_30px_rgba(239,68,68,0.15)] relative z-10">
                      <AlertTriangle className="w-12 h-12 text-destructive" />
                    </div>
                    <div className="absolute inset-0 rounded-full border-4 border-destructive/30 animate-pulse opacity-50"></div>
                  </div>
                  <h3 className="text-3xl font-black text-foreground mb-3">Generation Failed</h3>
                  <div className="bg-destructive/5 border border-destructive/20 rounded-xl p-4 max-w-lg mb-8 shadow-sm">
                    <p className="text-muted-foreground text-sm leading-relaxed">{generationError}</p>
                  </div>
                  <button
                    onClick={() => {
                      setStep(2);
                      setGenerationError(null);
                    }}
                    className="px-10 py-4 bg-primary text-primary-foreground text-base font-bold rounded-2xl hover:bg-primary/90 hover:shadow-xl hover:-translate-y-1 transition-all inline-flex items-center justify-center gap-2"
                  >
                    Try Again
                  </button>
                </div>
              ) : (
                <>
                  {/* Left Column: Visual Pipeline */}
                  <div className="flex-1 w-full space-y-6">
                    <div>
                      <h3 className="text-2xl font-bold text-foreground mb-2">Generating Report</h3>
                      <p className="text-muted-foreground">Executing background pipeline. Please do not close this window.</p>
                    </div>

                    <div className="space-y-4 bg-surface border border-border-subtle rounded-2xl p-6 relative overflow-hidden">
                      {PIPELINE_STAGES.map((stage, idx) => {
                        const isActive = idx === currentStageIndex;
                        const isCompleted = idx < currentStageIndex;

                        return (
                          <div key={stage} className={cn("flex items-center gap-4 transition-all duration-300", isActive ? "opacity-100 translate-x-2" : isCompleted ? "opacity-60" : "opacity-30")}>
                            <div className="relative shrink-0">
                              <div className={cn("w-6 h-6 rounded-full flex items-center justify-center z-10 relative transition-colors", isActive ? "bg-primary shadow-[0_0_15px_rgba(45,212,191,0.5)]" : isCompleted ? "bg-primary/20 border border-primary/30" : "bg-surface border border-border")}>
                                {isCompleted ? <Check className="w-3.5 h-3.5 text-primary" /> : <div className={cn("w-2 h-2 rounded-full", isActive ? "bg-primary-foreground" : "bg-muted-foreground/30")} />}
                              </div>
                              {idx < PIPELINE_STAGES.length - 1 && (
                                <div className={cn("absolute top-6 left-3 w-0.5 h-6 -ml-px transition-colors", isCompleted ? "bg-primary/40" : "bg-border")} />
                              )}
                            </div>
                            <div className="flex-1 min-w-0">
                              <p className={cn("text-sm font-bold truncate transition-colors", isActive ? "text-primary" : isCompleted ? "text-foreground" : "text-muted-foreground")}>
                                {stage}
                              </p>
                            </div>
                            {isActive && (
                              <Loader2 className="w-4 h-4 text-primary animate-spin shrink-0" />
                            )}
                          </div>
                        );
                      })}
                    </div>
                  </div>

                  {/* Right Column: Live Agent Activity Data */}
                  <div className="w-full md:w-80 shrink-0 space-y-6 mt-8 md:mt-0">
                    <div className="bg-card border-2 border-border-strong rounded-2xl p-6 text-foreground shadow-xl relative overflow-hidden">
                      <div className="absolute top-0 right-0 p-4 opacity-10">
                        <Activity className="w-24 h-24 text-primary" />
                      </div>
                      <h4 className="text-lg font-bold mb-4 flex items-center gap-2">
                        <Activity className="w-5 h-5 text-primary" />
                        Live Agent Status
                      </h4>

                      <div className="space-y-5 relative z-10">
                        <div>
                          <p className="text-muted-foreground text-xs font-semibold uppercase tracking-wider mb-1">Documents Processed</p>
                          <p className="text-2xl font-bold font-mono text-foreground">
                            {statusData?.agent_counts?.documents_processed ?? 0} <span className="text-muted-foreground text-lg">/ {selectedDocCount}</span>
                          </p>
                        </div>
                        <div>
                          <p className="text-muted-foreground text-xs font-semibold uppercase tracking-wider mb-1">Metrics Extracted</p>
                          <p className="text-2xl font-bold font-mono text-primary drop-shadow-[0_0_10px_rgba(45,212,191,0.2)]">
                            {statusData?.agent_counts?.metrics_found ?? 0}
                          </p>
                        </div>
                        <div>
                          <p className="text-muted-foreground text-xs font-semibold uppercase tracking-wider mb-1">Risks Identified</p>
                          <p className="text-2xl font-bold font-mono text-red-400 drop-shadow-[0_0_10px_rgba(248,113,113,0.2)]">
                            {statusData?.agent_counts?.risks_found ?? 0}
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                </>
              )}
            </motion.div>
          )}

          {step === 4 && (
            <motion.div 
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              className="py-16 px-4 flex flex-col items-center justify-center text-center w-full"
            >
              <div className="w-24 h-24 bg-green-500/10 border border-green-500/20 rounded-full flex items-center justify-center mb-8 shadow-[0_0_30px_rgba(34,197,94,0.15)] relative">
                <motion.div 
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ type: "spring", bounce: 0.5 }}
                >
                  <Check className="w-12 h-12 text-green-400 drop-shadow-[0_0_8px_rgba(34,197,94,0.5)]" />
                </motion.div>
                <div className="absolute inset-0 rounded-full border-4 border-green-500/30 animate-ping opacity-20"></div>
              </div>
              <h3 className="text-4xl font-black text-foreground mb-4">Report Complete!</h3>
              {/* Ensure text wraps nicely and doesn't squeeze to one word per line */}
              <p className="text-muted-foreground text-lg max-w-2xl mb-10 w-full px-4">
                Your institutional-grade financial report has been successfully synthesized by the AstraFinance AI agents and is ready for download.
              </p>

              <button
                onClick={handleDownload}
                disabled={isDownloading}
                className={cn(
                  "px-10 py-5 bg-primary text-white font-bold rounded-2xl hover:bg-primary/90 hover:shadow-xl hover:-translate-y-1 transition-all inline-flex items-center justify-center gap-3 text-lg whitespace-nowrap",
                  isDownloading && "opacity-75 cursor-not-allowed hover:bg-primary hover:shadow-none hover:-translate-y-0"
                )}
              >
                {isDownloading ? (
                  <Loader2 className="w-6 h-6 animate-spin" />
                ) : (
                  <Download className="w-6 h-6" />
                )}
                {isDownloading ? "Downloading Secure PDF..." : "Download Full PDF Report"}
              </button>
            </motion.div>
          )}
        </div>

        {/* Footer Actions */}
        {step < 3 && (
          <div className="px-8 py-5 border-t border-border-subtle bg-surface flex items-center justify-between mt-auto">
            <button
              onClick={() => step === 1 ? handleClose() : setStep(1)}
              className="px-6 py-3 text-sm font-bold text-muted-foreground bg-card border border-border rounded-xl hover:bg-surface transition-colors shadow-sm"
            >
              {step === 1 ? "Cancel" : "Back"}
            </button>

            {step === 1 && (
              <button
                onClick={() => setStep(2)}
                disabled={selectedDocCount === 0}
                className="px-8 py-3 text-sm font-bold text-white bg-primary rounded-xl hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-md flex items-center gap-2"
              >
                Continue <ArrowRight className="w-4 h-4" />
              </button>
            )}

            {step === 2 && (
              <button
                onClick={startGeneration}
                className="px-8 py-3 text-sm font-bold text-primary border border-primary/50 bg-transparent rounded-xl hover:bg-primary/10 transition-all flex items-center gap-2"
              >
                <FileText className="w-4 h-4" /> Generate Report
              </button>
            )}
          </div>
        )}
      </motion.div>
    </div>
  );
}

