"use client";

import { useState, useEffect, useCallback } from "react";
import { useParams, useRouter } from "next/navigation";
import Link from "next/link";
import {
  FileText,
  Download,
  Clock,
  FileBarChart2,
  Plus,
  Loader2,
  Trash2,
  Eye,
  MoreVertical,
  Calendar,
  HardDrive,
  Layers,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { fetcher } from "@/lib/api";

interface ReportVersion {
  id: string;
  version: string;
  is_latest: boolean;
  description: string;
  generated_by: string;
  created_at: string;
  pdf_path?: string;
}

interface Report {
  id: string;
  title: string;
  summary: string;
  status: string;
  created_at: string;
  pages: number;
  type: string;
  companies: number;
  sections: number;
  red_flags_included: boolean;
  workspace_name?: string;
  versions: ReportVersion[];
}

interface ReportsResponse {
  reports: Report[];
  metrics: {
    total_reports: number;
    total_versions: number;
    storage_used: string;
  };
}

export default function ReportsPage() {
  const params = useParams();
  const router = useRouter();
  const workspaceId = params.id as string;

  const [data, setData] = useState<ReportsResponse | null>(null);
  const [loading, setLoading] = useState(true);

  const loadReports = useCallback(async () => {
    try {
      const res = await fetcher<ReportsResponse>(`/workspaces/${workspaceId}/reports`);
      setData(res);
    } catch (e) {
      console.error("Failed to load reports:", e);
    } finally {
      setLoading(false);
    }
  }, [workspaceId]);

  useEffect(() => {
    loadReports();
  }, [loadReports]);

  const handleDownload = async (reportId: string, title: string) => {
    try {
      const token = localStorage.getItem("token");
      const url = `${process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000/api/v1"}/workspaces/${workspaceId}/reports/${reportId}/download`;
      const response = await fetch(url, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!response.ok) throw new Error("Failed to download");
      const blob = await response.blob();
      const blobUrl = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = blobUrl;
      a.download = `${title || "AstraFinance_Report"}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (e) {
      console.error(e);
    }
  };

  const handleGenerateNew = () => {
    router.push(`/workspace/${workspaceId}/reports/generate`);
  };

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center py-32">
        <Loader2 className="w-8 h-8 text-primary animate-spin" />
      </div>
    );
  }

  const reports = data?.reports || [];
  const metrics = data?.metrics || { total_reports: 0, total_versions: 0, storage_used: "0 MB" };

  return (
    <div className="flex-1 flex flex-col bg-surface overflow-y-auto">
      <div className="max-w-[1200px] w-full mx-auto px-6 py-6 md:px-8 md:py-8">

        <div className="flex items-center justify-between flex-wrap gap-4 mb-6">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-primary/20 text-primary flex items-center justify-center shadow-sm">
              <FileBarChart2 className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-lg font-bold text-foreground line-clamp-1">
                  Generated Reports
                </h2>
              </div>
              <p className="text-xs text-muted-foreground">
                View and download reports generated by the AI agents.
              </p>
            </div>
          </div>
          <button
            suppressHydrationWarning
            onClick={handleGenerateNew}
            className="flex items-center gap-2 px-6 py-2.5 bg-transparent border border-primary/50 text-primary hover:bg-primary/10 text-sm font-bold rounded-xl transition-all"
          >
            <FileBarChart2 className="w-4 h-4" />
            Generate Report
          </button>
        </div>

        {/* Metrics Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <div className="bg-card border border-border rounded-xl p-4 flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
              <Layers className="w-5 h-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold text-foreground">{metrics.total_reports}</p>
              <p className="text-xs text-muted-foreground">Total Reports</p>
            </div>
          </div>
          <div className="bg-card border border-border rounded-xl p-4 flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-violet-50 flex items-center justify-center">
              <Calendar className="w-5 h-5 text-violet-600" />
            </div>
            <div>
              <p className="text-2xl font-bold text-foreground">{metrics.total_versions}</p>
              <p className="text-xs text-muted-foreground">Total Versions</p>
            </div>
          </div>
          <div className="bg-card border border-border rounded-xl p-4 flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-amber-50 flex items-center justify-center">
              <HardDrive className="w-5 h-5 text-amber-600" />
            </div>
            <div>
              <p className="text-2xl font-bold text-foreground">{metrics.storage_used}</p>
              <p className="text-xs text-muted-foreground">Storage Used</p>
            </div>
          </div>
        </div>

        {/* Reports List */}
        {reports.length === 0 ? (
          <div className="bg-card border border-border rounded-xl shadow-sm overflow-hidden flex flex-col items-center justify-center py-24 px-6 mt-6">
            <div className="w-16 h-16 rounded-2xl bg-surface flex items-center justify-center mb-5 border border-border/50 shadow-sm">
              <FileText className="w-7 h-7 text-muted-foreground" />
            </div>
            <h4 className="text-foreground font-bold text-lg mb-2">No Reports Generated Yet</h4>
            <p className="text-muted-foreground text-sm max-w-[400px] text-center mx-auto leading-relaxed mb-6">
              Generate your first AI-powered report by selecting documents and customizing the sections to include.
            </p>
            <button
              suppressHydrationWarning
              onClick={handleGenerateNew}
              className="inline-flex items-center gap-2 px-6 py-3 bg-transparent border border-primary/50 text-primary hover:bg-primary/10 text-sm font-bold rounded-xl transition-all"
            >
              <FileBarChart2 className="w-4 h-4" />
              Generate Your First Report
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {reports.map((report) => (
              <Link
                href={`/workspace/${workspaceId}/reports/${report.id}`}
                key={report.id}
                className="bg-card border border-border rounded-xl p-5 hover:shadow-md transition-shadow group block"
              >
                <div className="flex items-start justify-between">
                  <div className="flex items-start gap-4 flex-1 min-w-0">
                    <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center shrink-0 border border-primary/50">
                      <FileBarChart2 className="w-6 h-6 text-primary" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="text-base font-bold text-foreground truncate">{report.title}</h3>
                        <span className={cn(
                          "px-2 py-0.5 rounded-full text-[10px] font-bold uppercase",
                          report.status === "completed"
                            ? "bg-primary/20 text-primary"
                            : "bg-amber-100 text-amber-700"
                        )}>
                          {report.status}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground mb-2">{report.summary}</p>
                      <div className="flex items-center gap-4 text-[11px] text-muted-foreground">
                        <span className="flex items-center gap-1">
                          <Clock className="w-3 h-3" />
                          {report.created_at}
                        </span>
                        <span>{report.type}</span>
                        <span>{report.companies} document{report.companies !== 1 ? "s" : ""}</span>
                        <span>{report.sections} section{report.sections !== 1 ? "s" : ""}</span>
                        {report.red_flags_included && (
                          <span className="text-destructive font-medium">Includes Red Flags</span>
                        )}
                      </div>

                      {/* Versions */}
                      {report.versions && report.versions.length > 0 && (
                        <div className="mt-3 space-y-1.5">
                          {report.versions.map((v) => (
                            <div key={v.id} className="flex items-center gap-3 text-xs text-muted-foreground bg-surface rounded-lg px-3 py-2">
                              <span className="font-bold text-foreground">{v.version}</span>
                              {v.is_latest && (
                                <span className="text-[9px] font-bold bg-primary/20 text-primary px-1.5 py-0.5 rounded">Latest</span>
                              )}
                              <span className="flex-1 truncate">{v.description}</span>
                              <span className="text-muted-foreground shrink-0">{v.generated_by}</span>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-2 shrink-0 ml-4">
                    <button
                      suppressHydrationWarning
                      onClick={(e) => {
                        e.preventDefault();
                        handleDownload(report.id, report.title);
                      }}
                      className="flex items-center gap-1.5 px-3 py-2 bg-primary hover:bg-primary/90 text-white text-xs font-bold rounded-lg transition-colors shadow-sm"
                    >
                      <Download className="w-3.5 h-3.5" />
                      Download
                    </button>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

