import type { ImgHTMLAttributes } from "react";

const LOGO_SRC = "/logo.svg";

type AstraFinanceLogoProps = Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "alt">;

/** Renders the unmodified, official AstraFinance PNG from the canonical asset path. */
export function AstraFinanceLogo({ className, ...props }: AstraFinanceLogoProps) {
  return (
    <img
      src={LOGO_SRC}
      alt="AstraFinance"
      draggable={false}
      className={`object-contain [image-rendering:auto] ${className ?? ""}`}
      {...props}
    />
  );
}

"use client";

import { useState, useRef } from "react";
import { User, Mail, LogOut, Check, Edit2, Upload, Trash, Image as ImageIcon } from "lucide-react";
import { useAuth } from "@/components/providers/AuthProvider";
import { fetcher } from "@/lib/api";
import { toast } from "sonner"; // Assuming sonner is used for toasts, standard in new nextjs

interface UserProfilePanelProps {
  onClose: () => void;
  onSignOut: () => void;
}

export function UserProfilePanel({ onClose, onSignOut }: UserProfilePanelProps) {
  const { user: firebaseUser, dbUser, updateDbUser } = useAuth();

  const [isEditing, setIsEditing] = useState(false);
  const [name, setName] = useState(dbUser?.name || firebaseUser?.displayName || "");
  const [email, setEmail] = useState(dbUser?.email || firebaseUser?.email || "");

  // Loading states
  const [isSavingName, setIsSavingName] = useState(false);
  const [isUploadingPhoto, setIsUploadingPhoto] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleNameSave = async () => {
    if (name === (dbUser?.name || firebaseUser?.displayName)) {
      setIsEditing(false);
      return;
    }

    setIsSavingName(true);
    try {
      await fetcher("/auth/profile/name", {
        method: "PUT",
        body: JSON.stringify({ name })
      });
      updateDbUser({ name });
      toast?.success && toast.success("Name updated successfully");
      setIsEditing(false);
    } catch (error: any) {
      toast?.error && toast.error(error.message || "Failed to update name");
    } finally {
      setIsSavingName(false);
    }
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file size (5MB max)
    if (file.size > 5 * 1024 * 1024) {
      toast?.error && toast.error("Image must be under 5MB");
      return;
    }

    // Convert to base64
    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      setIsUploadingPhoto(true);
      try {
        await fetcher("/auth/profile/photo", {
          method: "PUT",
          body: JSON.stringify({ photo_base64: base64 })
        });
        updateDbUser({ profile_picture: base64 });
        toast?.success && toast.success("Profile photo updated");
      } catch (error: any) {
        toast?.error && toast.error("Failed to upload photo");
      } finally {
        setIsUploadingPhoto(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleRemovePhoto = async () => {
    try {
      await fetcher("/auth/profile/photo", {
        method: "DELETE"
      });
      updateDbUser({ profile_picture: null });
      toast?.success && toast.success("Profile photo removed");
    } catch (error: any) {
      toast?.error && toast.error("Failed to remove photo");
    }
  };

  const userImage = dbUser ? dbUser.profile_picture : firebaseUser?.photoURL;
  const userName = dbUser?.name || firebaseUser?.displayName || "User";
  const userEmail = dbUser?.email || firebaseUser?.email || "email@example.com";

  return (
    <>
      <div className="fixed inset-0 z-40" onClick={onClose} />
      <div className="absolute top-14 right-8 w-80 bg-card border border-border rounded-xl shadow-xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
        <div className="p-5 border-b border-border-subtle bg-surface flex flex-col gap-4">

          <div className="flex items-start gap-4">
            <div className="relative group shrink-0">
              {userImage ? (
                <img src={userImage} alt="Profile" className="w-12 h-12 rounded-full object-cover" />
              ) : (
                <div className="w-12 h-12 rounded-full bg-blue-900 text-white flex items-center justify-center font-bold text-lg">
                  {userName.charAt(0).toUpperCase()}
                </div>
              )}
              {isEditing && (
                <div className="absolute inset-0 bg-black/50 rounded-full opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-1">
                  <button onClick={() => fileInputRef.current?.click()} className="text-white hover:text-blue-200 p-1">
                    <Upload className="w-3.5 h-3.5" />
                  </button>
                  {userImage && (
                    <button onClick={handleRemovePhoto} className="text-white hover:text-red-300 p-1">
                      <Trash className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>
              )}
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept="image/png, image/jpeg" 
                onChange={handlePhotoUpload} 
              />
            </div>

            <div className="flex-1 min-w-0">
              {isEditing ? (
                <div className="flex flex-col gap-3">
                  <div>
                    <label className="text-[10px] text-muted-foreground font-semibold uppercase mb-1 block">Name</label>
                    <input
                      type="text"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      className="w-full px-2 py-1.5 text-sm border border-border rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    {name !== userName && (
                      <button
                        onClick={handleNameSave}
                        disabled={isSavingName}
                        className="mt-1 text-xs bg-primary text-white px-2 py-1 rounded hover:bg-primary/90 flex items-center gap-1 ml-auto"
                      >
                        {isSavingName ? "Saving..." : <><Check className="w-3 h-3" /> Save Name</>}
                      </button>
                    )}
                  </div>

                  <div>
                    <label className="text-[10px] text-muted-foreground font-semibold uppercase mb-1 block">Email (Cannot be changed)</label>
                    <input
                      type="email"
                      value={email}
                      disabled
                      className="w-full px-2 py-1.5 text-sm border border-border bg-surface text-muted-foreground rounded cursor-not-allowed"
                    />
                  </div>

                  <div className="flex justify-end mt-2 pt-2 border-t border-border">
                    <button
                      onClick={() => {
                        setName(userName);
                        setIsEditing(false);
                      }}
                      className="text-xs text-muted-foreground hover:text-foreground font-medium"
                    >
                      Done Editing
                    </button>
                  </div>
                </div>
              ) : (
                <div>
                  <div className="font-semibold text-foreground truncate">{userName}</div>
                  <div className="text-sm text-muted-foreground truncate">{userEmail}</div>
                  <button
                    onClick={() => setIsEditing(true)}
                    className="text-xs text-primary hover:underline mt-1 flex items-center gap-1"
                  >
