  { label: "Rendering PDF..." },
  { label: "Finalizing & optimizing..." },
];

/* ΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
export default function GenerateReportModal({ workspaceId: initialWorkspaceId, onClose, onComplete }: Props) {
  const router = useRouter();
  const [workspaceId, setWorkspaceId] = useState<string | undefined>(initialWorkspaceId);
  const [workspaces, setWorkspaces] = useState<any[]>([]);

  // State for the modal
  const [step, setStep] = useState(1); // Controls which panel is active/visible on mobile, but on desktop we show all 3 in a row

  const [docs, setDocs] = useState(MOCK_DOCUMENTS);
  const [sections, setSections] = useState(DEFAULT_SECTIONS);
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set(["exec_summary"]));

  const [progressItems, setProgressItems] = useState<ProgressItem[]>(
    PROGRESS_STEPS.map((s) => ({ ...s, progress: 0, done: false, time: "--:--" }))
  );
  const [globalProgress, setGlobalProgress] = useState(0);
  const [generatedReportId, setGeneratedReportId] = useState<string | null>(null);

  useEffect(() => {
    if (!initialWorkspaceId) {
      fetcher<any[]>("/workspaces").then((res) => {
        setWorkspaces(res);
        if (res.length > 0) setWorkspaceId(res[0].id);
      }).catch(console.error);
    }
  }, [initialWorkspaceId]);

  const toggleDoc = (id: string) => {
    setDocs((prev) => prev.map((d) => (d.id === id ? { ...d, selected: !d.selected } : d)));
  };

  const toggleSection = (id: string) => {
    setSections((prev) => prev.map((s) => (s.id === id ? { ...s, enabled: !s.enabled } : s)));
  };

  const toggleExpand = (id: string) => {
    setExpandedSections((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const selectedDocCount = docs.filter((d) => d.selected).length;

  /* ΓöÇΓöÇ Step 3: Generation progress simulation ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
  const startGeneration = useCallback(async () => {
