"use client";

import { motion, AnimatePresence } from "framer-motion";
import { X, Edit2 } from "lucide-react";
import { useState, useEffect } from "react";

interface RenameDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (newName: string) => Promise<void>;
  currentName: string;
}

export default function RenameDialog({ isOpen, onClose, onConfirm, currentName }: RenameDialogProps) {
  const [loading, setLoading] = useState(false);
  const [name, setName] = useState(currentName);

  useEffect(() => {
    if (isOpen) {
      setName(currentName);
    }
  }, [isOpen, currentName]);

  const handleConfirm = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || name === currentName) return;

    setLoading(true);
    try {
      await onConfirm(name.trim());
      onClose();
    } finally {
      setLoading(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm"
          />
          <div className="fixed inset-0 z-50 flex items-center justify-center pointer-events-none p-4">
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              transition={{ type: "spring", stiffness: 300, damping: 25 }}
              className="bg-card rounded-2xl shadow-xl w-full max-w-md overflow-hidden pointer-events-auto"
            >
              <form onSubmit={handleConfirm} className="p-6">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                    <Edit2 className="w-6 h-6 text-primary" />
                  </div>
                  <button type="button" onClick={onClose} className="p-2 text-muted-foreground hover:bg-surface rounded-full transition-colors">
                    <X className="w-5 h-5" />
                  </button>
                </div>

                <h3 className="text-xl font-bold text-foreground mb-4">Rename Report</h3>

                <div className="mb-6">
                  <label htmlFor="reportName" className="block text-sm font-medium text-foreground mb-1.5">
                    Report Name
                  </label>
                  <input
                    id="reportName"
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    autoFocus
                    className="w-full px-3 py-2 bg-card border border-border rounded-lg text-foreground text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-primary transition-all shadow-sm"
                    placeholder="Enter a new name for the report"
                  />
                </div>

                <div className="flex items-center justify-end gap-3">
                  <button 
                    type="button"
                    onClick={onClose}
                    disabled={loading}
                    className="px-4 py-2 text-sm font-medium text-muted-foreground hover:bg-surface rounded-lg transition-colors"
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit"
                    disabled={loading || !name.trim() || name === currentName}
                    className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-primary hover:bg-primary/90 rounded-lg transition-colors shadow-sm disabled:opacity-50"
                  >
                    {loading && (
                      <span className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                    )}
                    Save Changes
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        </>
      )}
    </AnimatePresence>
  );
}

