"use client";

import React, { useMemo } from 'react';
import { motion } from 'framer-motion';
import { cn } from '@/lib/utils';

export function FinancialHeroParticles() {
  const particles = useMemo(() => {
    return Array.from({ length: 40 }).map((_, i) => ({
      id: i,
      size: Math.random() * 4 + 2, // 2px to 6px
      x: Math.random() * 100, // 0 to 100%
      y: Math.random() * 100, // 0 to 100%
      duration: Math.random() * 20 + 10, // 10s to 30s
      delay: Math.random() * 5,
    }));
  }, []);

  return (
    <div className="absolute inset-0 w-full h-full pointer-events-none z-0 overflow-hidden opacity-40">
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-blue-500/10 via-transparent to-transparent opacity-50" />
      {particles.map((p) => (
        <motion.div
          key={p.id}
          className="absolute rounded-full bg-primary/30"
          style={{
            width: p.size,
            height: p.size,
            left: `${p.x}%`,
            top: `${p.y}%`,
          }}
          animate={{
            y: [`${p.y}%`, `${p.y - 10}%`, `${p.y}%`],
            x: [`${p.x}%`, `${p.x + (Math.random() * 10 - 5)}%`, `${p.x}%`],
            opacity: [0.1, 0.4, 0.1],
          }}
          transition={{
            duration: p.duration,
            repeat: Infinity,
            ease: "linear",
            delay: p.delay,
          }}
        />
      ))}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  Legend,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  Radar,
} from "recharts";
import { PremiumTooltip } from "./PremiumTooltip";


const SEG_COLORS = ["#3B82F6", "#8B5CF6", "#10B981", "#F59E0B", "#EF4444", "#06B6D4", "#EC4899"];

const parseNum = (val: string | number | undefined | null): number => {
  if (val === undefined || val === null) return NaN;
  if (typeof val === 'number') return val;
  const match = val.replace(/,/g, '').match(/-?\d+(\.\d+)?/);
  return match ? parseFloat(match[0]) : NaN;
};

// ΓöÇΓöÇ 1. Recharts Donut ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export function DonutChart({ segments }: { segments: any[] }) {
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  if (!segments || !Array.isArray(segments) || segments.length === 0) {
    return (
      <div className="w-full h-full flex items-center justify-center relative">
        <div className="w-48 h-48 border-[20px] border-border-subtle rounded-full flex items-center justify-center">
           <span className="text-muted-foreground font-bold text-sm">No Data</span>
        </div>
      </div>
    );
  }

  const validSegments = segments
    .map((seg) => ({ ...seg, numVal: parseNum(seg.value) }))
    .filter((seg) => Number.isFinite(seg.numVal) && seg.numVal > 0);

  const total = validSegments.reduce((s, seg) => s + seg.numVal, 0);

  if (total <= 0) {
    return (
      <div className="w-full h-full flex items-center justify-center relative">
        <div className="w-48 h-48 border-[20px] border-border-subtle rounded-full flex items-center justify-center">
           <span className="text-muted-foreground font-bold text-sm">No Data</span>
        </div>
      </div>
    );
  }

  return (
    <div className="w-[160px] h-[160px] relative flex-shrink-0">
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Tooltip content={<PremiumTooltip />} />
          <Pie
            data={validSegments}
            cx="50%"
            cy="50%"
            innerRadius={48}
            outerRadius={72}
            paddingAngle={2}
            dataKey="numVal"
            nameKey="segment"
            stroke="none"
            onMouseEnter={(_, index) => setActiveIndex(index)}
            onMouseLeave={() => setActiveIndex(null)}
          >
            {validSegments.map((entry, index) => (
              <Cell 
                key={`cell-${index}`} 
                fill={SEG_COLORS[index % SEG_COLORS.length]} 
                opacity={activeIndex === null || activeIndex === index ? 1 : 0.3}
                style={{ transition: 'opacity 300ms ease' }}
              />
            ))}
          </Pie>
        </PieChart>
      </ResponsiveContainer>
      <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
        <span className="text-foreground text-2xl font-black tracking-tighter">100%</span>
        <span className="text-muted-foreground text-[9px] uppercase font-bold tracking-widest mt-0.5">Total Revenue</span>
      </div>
    </div>
  );
}

// ΓöÇΓöÇ 2. Recharts Area Trend ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export function QuarterlyTrendChart({ trendData }: { trendData: any[] }) {
  if (!trendData || !Array.isArray(trendData) || trendData.length === 0 || trendData[0].quarter == null) {
    return <div className="w-full h-40 flex items-center justify-center text-muted-foreground">No data</div>;
  }

  const validData = trendData.map(q => ({
    name: q.quarter,
    Revenue: parseNum(q.revenue) || 0,
    Margin: parseNum(q.margin) || 0,
  }));

  return (
    <div className="w-full h-[300px]">
      <ResponsiveContainer width="100%" height="100%">
        <AreaChart data={validData} margin={{ top: 10, right: 0, left: -20, bottom: 0 }}>
          <defs>
            <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#3B82F6" stopOpacity={0.3}/>
              <stop offset="95%" stopColor="#3B82F6" stopOpacity={0}/>
            </linearGradient>
            <linearGradient id="colorMargin" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#10B981" stopOpacity={0.3}/>
              <stop offset="95%" stopColor="#10B981" stopOpacity={0}/>
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E2E8F0" />
          <XAxis 
            dataKey="name" 
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#94A3B8', fontSize: 12, fontWeight: 500 }} 
            dy={10} 
          />
          <YAxis 
            yAxisId="left"
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#94A3B8', fontSize: 12, fontWeight: 500 }}
            tickFormatter={(value) => value >= 1000 ? (value / 1000).toFixed(0) + 'k' : value}
          />
          <YAxis 
            yAxisId="right"
            orientation="right"
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#10B981', fontSize: 12, fontWeight: 600 }}
            tickFormatter={(value) => `${value}%`}
          />
          <Tooltip content={<PremiumTooltip />} cursor={{ stroke: '#94A3B8', strokeWidth: 1, strokeDasharray: '4 4' }} />
          <Area 
            yAxisId="left"
            type="monotone" 
            dataKey="Revenue" 
            stroke="#3B82F6" 
            strokeWidth={3}
            fillOpacity={1} 
            fill="url(#colorRevenue)" 
            activeDot={{ r: 6, strokeWidth: 0, fill: '#3B82F6' }}
          />
          <Area 
            yAxisId="right"
            type="monotone" 
            dataKey="Margin" 
            stroke="#10B981" 
            strokeWidth={3}
            fillOpacity={1} 
            fill="url(#colorMargin)" 
            activeDot={{ r: 6, strokeWidth: 0, fill: '#10B981' }}
          />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  );
}

// ΓöÇΓöÇ 3. Recharts Geography Bar (Replacing Polar) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export function GeographySplitChart({ splitData }: { splitData: any[] }) {
  if (!splitData || !Array.isArray(splitData) || splitData.length === 0) {
    return <div className="w-full h-40 flex items-center justify-center text-muted-foreground">No data</div>;
  }
  const validGeos = splitData.map(g => ({ name: g.region, Value: parseNum(g.percentage) })).filter(g => Number.isFinite(g.Value));

  return (
    <div className="w-full h-[260px]">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={validGeos} layout="vertical" margin={{ top: 0, right: 30, left: 20, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#E2E8F0" />
          <XAxis type="number" axisLine={false} tickLine={false} tick={{ fill: '#94A3B8', fontSize: 12 }} tickFormatter={(val) => `${val}%`} />
          <YAxis type="category" dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#64748B', fontSize: 12, fontWeight: 600 }} width={100} />
          <Tooltip content={<PremiumTooltip />} cursor={{ fill: '#F1F5F9' }} />
          <Bar dataKey="Value" radius={[0, 4, 4, 0]} barSize={24}>
            {validGeos.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={SEG_COLORS[index % SEG_COLORS.length]} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

// ΓöÇΓöÇ 4. Recharts Key Metrics Bar (Log Scale Alternative) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export function KeyMetricsBarChart({ metrics }: { metrics: any[] }) {
  const validMetrics = metrics
    .map(m => ({ name: m.label, Value: parseNum(m.value) }))
    .filter(m => Number.isFinite(m.Value) && m.Value > 0);

  if (validMetrics.length < 2) return null;

  return (
    <div className="w-full h-[260px]">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={validMetrics} margin={{ top: 20, right: 0, left: -20, bottom: 20 }}>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E2E8F0" />
          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#64748B', fontSize: 11, fontWeight: 600 }} angle={-25} textAnchor="end" dy={10} />
          <YAxis scale="log" domain={['auto', 'auto']} axisLine={false} tickLine={false} tick={{ fill: '#94A3B8', fontSize: 11 }} tickFormatter={(val) => val >= 1000 ? `${(val/1000).toFixed(0)}k` : val} />
          <Tooltip content={<PremiumTooltip />} cursor={{ fill: '#F1F5F9' }} />
          <Bar dataKey="Value" radius={[4, 4, 0, 0]} barSize={32}>
            {validMetrics.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={SEG_COLORS[index % SEG_COLORS.length]} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

// ΓöÇΓöÇ 5. Recharts Circular Gauge ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export function CircularGauge({ value, label }: { value: number | string; label: string }) {
  const numVal = parseNum(value);
  if (!Number.isFinite(numVal) || numVal < 0) {
    return (
      <div className="flex flex-col items-center justify-center w-full max-w-[120px]">
        <div className="w-24 h-24 flex items-center justify-center border-8 border-border-subtle rounded-full">
          <span className="text-muted-foreground font-bold text-sm">-</span>
        </div>
        <span className="text-xs font-semibold text-muted-foreground mt-2">{label}</span>
      </div>
    );
  }

  const data = [
    { name: "Value", value: numVal, fill: "#3B82F6" },
    { name: "Remainder", value: 100 - numVal, fill: "#E2E8F0" },
  ];

  return (
    <div className="flex flex-col items-center justify-center flex-shrink-0">
      <div className="w-[150px] h-[80px] relative">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={data}
              cx="50%"
              cy="100%"
              startAngle={180}
              endAngle={0}
              innerRadius={42}
              outerRadius={58}
              paddingAngle={2}
              dataKey="value"
              stroke="none"
              cornerRadius={10}
            >
              {data.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.fill} />
              ))}
            </Pie>
          </PieChart>
        </ResponsiveContainer>
        <div className="absolute inset-x-0 bottom-0 flex items-end justify-center pb-0.5 pointer-events-none">
          <span className="text-foreground text-xl font-black">{numVal}%</span>
        </div>
      </div>
      <span className="text-[11px] font-bold text-muted-foreground mt-2 uppercase tracking-wider text-center leading-tight">
        {label}
      </span>
    </div>
  );
}

// ΓöÇΓöÇ 6. Recharts Key Metrics Radar ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export function KeyMetricsRadarChart({ metrics }: { metrics: any[] }) {
  const validMetrics = metrics
    .map(m => ({ label: m.label, numVal: parseNum(m.value) }))
    .filter(m => Number.isFinite(m.numVal) && m.numVal > 0);

  if (validMetrics.length < 3) return null;

  const maxVal = Math.max(...validMetrics.map(m => m.numVal));
  const data = validMetrics.map(m => ({
    subject: m.label,
    A: (m.numVal / maxVal) * 100,
    originalValue: m.numVal,
  }));

  return (
    <div className="w-full h-[260px]">
      <ResponsiveContainer width="100%" height="100%">
        <RadarChart cx="50%" cy="50%" outerRadius="75%" data={data}>
          <PolarGrid stroke="#E2E8F0" />
          <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748B', fontSize: 10, fontWeight: 600 }} />
          <PolarRadiusAxis angle={30} domain={[0, 100]} tick={false} axisLine={false} />
          <Tooltip 
            content={({ active, payload }) => {
              if (active && payload && payload.length) {
                return (
                  <div className="bg-foreground border border-slate-700/50 rounded-xl shadow-xl px-4 py-3">
                    <p className="text-muted-foreground text-xs font-bold mb-1">{payload[0].payload.subject}</p>
                    <p className="text-white text-sm font-bold">Value: {payload[0].payload.originalValue}</p>
                  </div>
                );
              }
              return null;
            }} 
          />
          <Radar name="Metrics" dataKey="A" stroke="#3B82F6" fill="#3B82F6" fillOpacity={0.2} />
        </RadarChart>
      </ResponsiveContainer>
    </div>
  );
}

"use client";

import React from "react";
import { motion } from "framer-motion";

export function PremiumTooltip({ active, payload, label }: any) {
  if (active && payload && payload.length) {
    return (
      <motion.div 
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="bg-foreground border border-slate-700/50 rounded-xl shadow-xl px-4 py-3 min-w-[140px]"
      >
        <p className="text-muted-foreground text-xs font-bold uppercase tracking-wider mb-2">
          {label}
        </p>
        <div className="flex flex-col gap-1.5">
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center gap-3 justify-between">
              <div className="flex items-center gap-2">
                <div 
                  className="w-2 h-2 rounded-full shadow-sm" 
                  style={{ backgroundColor: entry.color }} 
                />
                <span className="text-muted-foreground text-xs font-medium">
                  {entry.name}
                </span>
              </div>
              <span className="text-white text-sm font-bold tracking-tight">
                {typeof entry.value === 'number' && entry.value > 100 
                  ? entry.value.toLocaleString() 
                  : entry.value}
                {entry.name.toLowerCase().includes('margin') ? '%' : ''}
              </span>
            </div>
          ))}
        </div>
      </motion.div>
    );
  }
  return null;
}

"use client";

import React, { useRef } from "react";
import { motion, useAnimationFrame, useMotionValue, useTransform } from "framer-motion";

interface BendingMarqueeProps {
  text: string;
  speed?: number; // Pixels per frame or speed multiplier
  color?: string;
}

export function BendingMarquee({ 
  text, 
  speed = 1,
  color = "currentColor"
}: BendingMarqueeProps) {
  // We use a motion value to track the offset
  const baseOffset = useMotionValue(0);

  // Animate the base offset continuously
  useAnimationFrame((t, delta) => {
    // Increase offset. Speed controls how fast. 
    // Decrease speed further as requested (divided by 120)
    let moveBy = speed * (delta / 120);

    // We'll map the offset from 0 to 50% since we duplicate the text twice.
    // If it exceeds 50%, we wrap it back to 0.
    const newOffset = baseOffset.get() - moveBy;
    if (newOffset <= -50) {
      baseOffset.set(0);
    } else {
      baseOffset.set(newOffset);
    }
  });

  // Convert the numerical offset into a percentage string for SVG startOffset
  const startOffset = useTransform(baseOffset, (v) => `${v}%`);

  // To make the scroll seamless, we duplicate the text a few times with spacing.
  const spacedText = `${text}  Γ£│  ${text}  Γ£│  ${text}  Γ£│  ${text}  Γ£│  `;

  return (
    <div className="w-full relative overflow-hidden h-[120px] md:h-[160px] flex items-center justify-center py-4">
      {/* 
        We use a viewBox of 0 0 1000 200 to establish a responsive coordinate system.
        The path is a gentle curve. 
      */}
      <svg 
        viewBox="0 0 1000 200" 
        preserveAspectRatio="none" 
        className="w-full h-full absolute inset-0 pointer-events-none"
      >
        <defs>
          <path 
            id="bend-curve" 
            d="M -500,50 Q 500,200 1500,50" 
          />
        </defs>

        {/* Adaptive background band (White in light mode, Black in dark mode) */}
        <use href="#bend-curve" className="stroke-white dark:stroke-black" strokeWidth="60" fill="transparent" />

        {/* Main Text (Black in light mode, Primary Teal in dark mode) */}
        <motion.text 
          className="text-2xl md:text-3xl font-medium tracking-wide pointer-events-none fill-black dark:fill-primary"
          style={{ whiteSpace: "pre" }}
          dy="10" // Vertically center text on the stroke
        >
          <motion.textPath 
            href="#bend-curve" 
            startOffset={startOffset}
            className="select-none"
          >
            {spacedText}
          </motion.textPath>
        </motion.text>
      </svg>
    </div>
  );
}

