"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import {
  Search,
  Upload,
  FileText,
  Loader2,
  Check,
  X,
  Trash2,
  Download,
  ChevronLeft,
  ChevronRight,
  ChevronDown,
  Filter,
  LayoutGrid,
  LayoutList,
  BarChart2,
  ShieldAlert,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
  Eye,
  CheckCircle2,
  XCircle,
  MoreVertical,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { fetcher, API_BASE_URL } from "@/lib/api";
import type { Document, Metric, RedFlag } from "./types";
import { DocumentProcessingView } from "./DocumentProcessingView";

// ΓöÇΓöÇ Upload Modal ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function UploadDocumentsModal({
  onCancel,
  onUploadStart,
}: {
  onCancel: () => void;
  onUploadStart: (files: File[]) => void;
  workspaceId: string;
}) {
  const [dragActive, setDragActive] = useState(false);
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") setDragActive(true);
    else if (e.type === "dragleave") setDragActive(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      setSelectedFiles(
        Array.from(e.dataTransfer.files).filter(
          (f) => f.type === "application/pdf"
        )
      );
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setSelectedFiles(
        Array.from(e.target.files).filter((f) => f.type === "application/pdf")
      );
    }
  };

  return (
    <div className="p-6 max-w-3xl mx-auto w-full h-full">
      <div className="mb-6">
        <button
          onClick={onCancel}
          className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground mb-4 transition-colors"
        >
          <ChevronLeft className="w-4 h-4" /> Back to Documents
        </button>
        <h3 className="text-xl font-bold text-foreground">Upload Documents</h3>
        <p className="text-sm text-muted-foreground">
          Upload PDF files for processing and analysis.
        </p>
      </div>

      <div
        className={cn(
          "border-2 border-dashed rounded-2xl p-12 text-center transition-all cursor-pointer relative",
          dragActive
            ? "border-primary bg-primary/10/50"
            : "border-border hover:border-primary hover:bg-surface"
        )}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
        onClick={() => inputRef.current?.click()}
      >
        <input
          ref={inputRef}
          type="file"
          multiple
          accept=".pdf"
          className="hidden"
          onChange={handleChange}
        />
        <div className="w-16 h-16 bg-primary/20 rounded-full flex items-center justify-center mx-auto mb-4">
          <Upload className="w-8 h-8 text-primary" />
        </div>
        <h4 className="text-base font-semibold text-foreground mb-1">
          Click or drag and drop to upload
        </h4>
        <p className="text-sm text-muted-foreground">
          Only PDF files are supported. Max size 50MB per file.
        </p>
      </div>

      {selectedFiles.length > 0 && (
        <div className="mt-8 space-y-3">
          <h4 className="text-sm font-semibold text-foreground">
            Selected Files ({selectedFiles.length})
          </h4>
          {selectedFiles.map((file, i) => (
            <div
              key={i}
              className="flex items-center justify-between bg-card border border-border rounded-xl p-3 shadow-sm hover:shadow-md transition-shadow"
            >
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-lg bg-destructive/10 flex items-center justify-center shrink-0">
                  <FileText className="w-5 h-5 text-destructive" />
                </div>
                <div>
                  <p className="text-sm font-medium text-foreground truncate max-w-[300px]">
                    {file.name}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {(file.size / 1024 / 1024).toFixed(2)} MB
                  </p>
                </div>
              </div>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  setSelectedFiles((prev) =>
                    prev.filter((_, idx) => idx !== i)
                  );
                }}
                className="p-2 text-muted-foreground hover:text-destructive rounded-lg hover:bg-destructive/10 transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          ))}
          <div className="flex justify-end gap-3 mt-6">
            <button
              onClick={onCancel}
              className="px-4 py-2 text-sm font-medium text-muted-foreground bg-surface rounded-xl hover:bg-surface transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={() => onUploadStart(selectedFiles)}
              className="px-6 py-2 text-sm font-medium text-white bg-primary rounded-xl hover:bg-primary/90 flex items-center gap-2 transition-colors"
            >
              Start Processing <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

// ΓöÇΓöÇ Document Detail Side Panel ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
