            <p className="text-[10px] text-muted-foreground font-medium">Pages</p>
          </div>
          <div className="bg-surface rounded-xl p-3 text-center">
            <p className="text-lg font-bold text-foreground">
              {formatSize(doc.size_bytes)}
            </p>
            <p className="text-[10px] text-muted-foreground font-medium">Size</p>
          </div>
          <div className="bg-surface rounded-xl p-3 text-center">
            <p className="text-lg font-bold text-foreground">{fileExt}</p>
            <p className="text-[10px] text-muted-foreground font-medium">Type</p>
          </div>
        </div>

        {/* Extracted Metrics */}
        {doc.extracted_metrics && doc.extracted_metrics.length > 0 && (
          <div className="mb-6">
            <div className="flex items-center justify-between mb-3">
              <h5 className="text-xs font-bold text-foreground">
                Key Financial Metrics
              </h5>
              <span className="text-[10px] text-muted-foreground">(Extracted)</span>
            </div>
            <div className="space-y-2">
              {doc.extracted_metrics.map((m, i) => (
                <div
                  key={i}
                  className="flex items-center justify-between py-2 border-b border-border-subtle last:border-0"
                >
                  <span className="text-xs text-muted-foreground">{m.label}</span>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-foreground">
                      {m.value}
                    </span>
                    <span
                      className={cn(
                        "text-xs font-semibold",
                        m.trend === "up"
                          ? "text-success"
                          : "text-destructive"
                      )}
                    >
                      {m.trend === "up" ? "Γåæ" : "Γåô"} {m.change}
                    </span>
                  </div>
                </div>
              ))}
            </div>
            <button className="text-xs text-primary hover:text-primary-hover font-medium mt-2 flex items-center gap-1">
              View all metrics ΓåÆ
            </button>
          </div>
        )}

        {/* Red Flags */}
        {doc.red_flags && doc.red_flags.length > 0 && (
          <div className="mb-6">
            <div className="flex items-center justify-between mb-3">
              <h5 className="text-xs font-bold text-foreground">
