                <div
                  key={i}
                  className="flex items-center justify-between py-1.5"
                >
                  <span className="text-xs text-muted-foreground truncate pr-2">
                    {rf.title}
                  </span>
                  <span
                    className={cn(
                      "text-[10px] font-bold px-2 py-0.5 rounded-full shrink-0",
                      rf.severity === "High"
                        ? "bg-destructive/10 text-destructive"
                        : rf.severity === "Medium"
                          ? "bg-orange-50 text-orange-700"
                          : "bg-yellow-50 text-yellow-700"
                    )}
                  >
                    {rf.severity}
                  </span>
                </div>
              ))}
            </div>
            <button className="text-xs text-primary hover:text-primary-hover font-medium mt-2 flex items-center gap-1">
              View all red flags ΓåÆ
            </button>
          </div>
        )}

        {/* Action buttons */}
        <div className="grid grid-cols-2 gap-2 mt-4">
          <button className="flex items-center justify-center gap-1.5 text-xs font-medium text-primary bg-primary/10 border border-primary/50 px-3 py-2.5 rounded-xl hover:bg-primary/20 transition-colors">
            <BarChart2 className="w-3.5 h-3.5" />
            Open in Metrics
          </button>
          <button className="flex items-center justify-center gap-1.5 text-xs font-medium text-orange-600 bg-orange-50 border border-orange-200 px-3 py-2.5 rounded-xl hover:bg-orange-100 transition-colors">
            <ShieldAlert className="w-3.5 h-3.5" />
            Open in Red Flags
          </button>
        </div>
      </div>
    </div>
  );
}

// ΓöÇΓöÇ Delete Confirmation Modal ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function DeleteConfirmModal({
