}

// ΓöÇΓöÇ Main DocumentsTab ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export function DocumentsTab({
  workspaceId,
  onDocCountChange,
}: {
  workspaceId: string;
  onDocCountChange: (n: number) => void;
}) {
  const [view, setView] = useState<"list" | "upload" | "processing">("list");
  const [documents, setDocuments] = useState<Document[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [companyFilter, setCompanyFilter] = useState("all");
  const [layoutMode, setLayoutMode] = useState<"table" | "grid">("table");
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [deleteDoc, setDeleteDoc] = useState<Document | null>(null);

  const loadDocuments = useCallback(async () => {
    try {
      const data = await fetcher<{ documents: Document[]; total: number }>(
        `/workspaces/${workspaceId}/documents`
      );
      setDocuments(data.documents);
      onDocCountChange(data.total);
      if (data.documents.some((d) => d.status === "processing")) {
        setView("processing");
      }
    } catch (e) {
      console.error("Failed to load documents:", e);
    } finally {
      setLoading(false);
    }
  }, [workspaceId, onDocCountChange]);

  useEffect(() => {
    loadDocuments();
  }, [loadDocuments]);

  const handleUploadStart = async (files: File[]) => {
    setView("processing");
    const formData = new FormData();
    files.forEach((f) => formData.append("files", f));
    try {
      await fetch(`${API_BASE_URL}/workspaces/${workspaceId}/documents`, {
        method: "POST",
        body: formData,
      });
    } catch (e) {
      console.error("Upload failed", e);
      setView("list");
    }
  };

  const handleDelete = async (docId: string) => {
    try {
      await fetcher(`/workspaces/${workspaceId}/documents/${docId}`, {
        method: "DELETE",
      });
      setDocuments((prev) => prev.filter((d) => d.id !== docId));
      onDocCountChange(documents.length - 1);
      if (selectedDoc?.id === docId) setSelectedDoc(null);
      setDeleteDoc(null);
    } catch (e) {
      console.error("Delete failed:", e);
    }
  };

  const handleProcessingComplete = useCallback(() => {
    setView("list");
    loadDocuments();
  }, [loadDocuments]);

  const formatSize = (bytes: number) => {
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
    return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
  };

  if (loading) {
    return (
      <div className="p-6 flex flex-col gap-3">
        {Array.from({ length: 3 }).map((_, i) => (
          <div
            key={i}
            className="flex items-center gap-4 bg-card border border-border rounded-xl p-4 animate-pulse"
          >
            <div className="w-10 h-10 rounded-xl bg-surface shrink-0" />
            <div className="flex-1 space-y-2">
              <div className="h-3 bg-surface rounded w-2/3" />
              <div className="h-2 bg-surface rounded w-1/3" />
            </div>
          </div>
        ))}
      </div>
    );
  }

  if (view === "upload") {
    return (
      <UploadDocumentsModal
        onCancel={() => setView("list")}
        onUploadStart={handleUploadStart}
        workspaceId={workspaceId}
      />
    );
  }

  if (view === "processing") {
    return (
      <DocumentProcessingView
        workspaceId={workspaceId}
        onComplete={handleProcessingComplete}
      />
    );
  }

  const filteredDocs = documents.filter((d) => {
    if (statusFilter !== "all" && d.status !== statusFilter) {
      if (
        statusFilter === "ready" &&
        (d.status === "ready" || d.status === "processed")
      )
        return true;
      return false;
    }
    if (
      searchQuery &&
      !d.name.toLowerCase().includes(searchQuery.toLowerCase())
    )
      return false;
    return true;
  });

  return (
    <div className="flex h-full relative overflow-hidden">
      {/* Main content */}
      <div className="flex-1 flex flex-col p-6 min-w-0">
        {/* Toolbar */}
        <div className="flex items-center justify-between mb-5">
          <div>
            <h3 className="text-lg font-bold text-foreground">Documents</h3>
            <p className="text-sm text-muted-foreground mt-0.5">
              {documents.length} document{documents.length !== 1 ? "s" : ""} in
              this workspace
            </p>
          </div>
          <div className="flex items-center gap-3">
            {/* Search */}
            <div className="relative">
              <Search className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                placeholder="Search documents..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-9 pr-4 py-2 border border-border rounded-lg text-sm bg-card focus:ring-2 focus:ring-blue-500 outline-none w-56 shadow-sm"
              />
            </div>

            {/* Status filter */}
            <div className="relative">
              <Filter className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" />
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="pl-9 pr-8 py-2 border border-border rounded-lg text-sm bg-card text-foreground outline-none cursor-pointer hover:bg-surface shadow-sm appearance-none"
              >
                <option value="all">Status: All</option>
                <option value="ready">Ready</option>
                <option value="processing">Processing</option>
                <option value="failed">Failed</option>
              </select>
              <ChevronDown className="w-4 h-4 text-muted-foreground absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
            </div>

            {/* Company filter */}
            <div className="relative">
              <select
                value={companyFilter}
                onChange={(e) => setCompanyFilter(e.target.value)}
                className="pl-3 pr-8 py-2 border border-border rounded-lg text-sm bg-card text-foreground outline-none cursor-pointer hover:bg-surface shadow-sm appearance-none"
              >
                <option value="all">Company: All</option>
              </select>
              <ChevronDown className="w-4 h-4 text-muted-foreground absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
            </div>

            {/* Layout toggle */}
            <div className="flex border border-border rounded-lg overflow-hidden shadow-sm">
              <button
                onClick={() => setLayoutMode("grid")}
                className={cn(
                  "p-2 transition-colors",
                  layoutMode === "grid"
                    ? "bg-primary/10 text-primary"
                    : "bg-card text-muted-foreground hover:text-foreground"
                )}
              >
                <LayoutGrid className="w-4 h-4" />
              </button>
              <button
                onClick={() => setLayoutMode("table")}
                className={cn(
                  "p-2 transition-colors",
                  layoutMode === "table"
                    ? "bg-primary/10 text-primary"
                    : "bg-card text-muted-foreground hover:text-foreground"
                )}
              >
                <LayoutList className="w-4 h-4" />
              </button>
            </div>

            {/* Upload button */}
            <button
              onClick={() => setView("upload")}
              className="flex items-center gap-2 px-4 py-2 bg-primary text-white text-sm font-medium rounded-lg hover:bg-primary/90 transition-colors shadow-sm"
            >
              <Upload className="w-4 h-4" />
              Upload PDF
            </button>
          </div>
        </div>

        {/* Table view */}
        {layoutMode === "table" ? (
          <div className="flex-1 bg-card border border-border rounded-xl shadow-sm overflow-hidden flex flex-col">
            {/* Header */}
            <div className="grid grid-cols-12 gap-4 px-6 py-3 border-b border-border-subtle bg-surface text-xs font-semibold text-muted-foreground uppercase tracking-wider">
              <div className="col-span-4">Document</div>
              <div className="col-span-1">Pages</div>
              <div className="col-span-2">Uploaded</div>
              <div className="col-span-2">Status</div>
              <div className="col-span-3 text-right">Actions</div>
            </div>
            {/* Body */}
            <div className="flex-1 overflow-y-auto divide-y divide-border">
              {filteredDocs.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-24">
                  <div className="w-16 h-16 rounded-full bg-surface flex items-center justify-center mb-4 border border-border-subtle">
                    <Search className="w-6 h-6 text-muted-foreground" />
                  </div>
                  <h4 className="text-foreground font-semibold mb-1">
                    No documents found
                  </h4>
                  <p className="text-muted-foreground text-sm">
                    Adjust your filters or search query.
                  </p>
                </div>
              ) : (
                filteredDocs.map((doc) => (
                  <div
                    key={doc.id}
                    className="grid grid-cols-12 gap-4 px-6 py-4 items-center hover:bg-surface transition-colors cursor-pointer group"
                    onClick={() => setSelectedDoc(doc)}
                  >
                    {/* Document info */}
                    <div className="col-span-4 flex items-center gap-3">
                      <div className="w-9 h-9 rounded-lg bg-destructive/10 border border-red-100 flex items-center justify-center shrink-0">
                        <FileText className="w-4 h-4 text-destructive" />
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-medium text-foreground truncate group-hover:text-primary transition-colors">
                          {doc.name}
                        </p>
                        <div className="flex items-center gap-2 mt-0.5">
                          {doc.company && (
                            <span className="text-[10px] text-muted-foreground">
                              {doc.company}
                            </span>
                          )}
                          {doc.doc_type && (
                            <span className="text-[10px] text-primary bg-primary/10 px-1.5 py-0.5 rounded">
                              {doc.doc_type}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>

                    {/* Pages */}
                    <div className="col-span-1 text-sm text-muted-foreground font-medium">
                      {doc.pages}
                    </div>

                    {/* Uploaded */}
                    <div className="col-span-2 text-sm text-muted-foreground">
                      {doc.uploaded_at}
                    </div>

                    {/* Status */}
                    <div className="col-span-2">
                      {doc.status === "ready" ||
                      doc.status === "processed" ? (
                        <div>
                          <span className="inline-flex items-center gap-1 text-xs font-semibold text-success bg-success/10 border border-success/50 px-2.5 py-1 rounded-full">
                            <CheckCircle2 className="w-3.5 h-3.5" /> Ready
                          </span>
                          <p className="text-[10px] text-muted-foreground mt-1 flex items-center gap-1">
                            <Check className="w-3 h-3" /> Indexed
                          </p>
                        </div>
                      ) : doc.status === "processing" ? (
                        <div>
                          <span className="inline-flex items-center gap-1 text-xs font-semibold text-primary bg-primary/10 border border-primary/50 px-2.5 py-1 rounded-full">
                            <Loader2 className="w-3.5 h-3.5 animate-spin" />{" "}
                            Processing
                          </span>
                          <div className="mt-1.5">
                            <p className="text-[10px] text-muted-foreground mb-1">
                              {doc.processing_step || 1} of 5 steps
                            </p>
                            <div className="h-1.5 bg-surface rounded-full overflow-hidden w-24">
                              <div
                                className="h-full bg-primary rounded-full transition-all duration-500"
                                style={{
                                  width: `${doc.progress || ((doc.processing_step || 1) / 5) * 100}%`,
                                }}
                              />
                            </div>
                          </div>
                        </div>
                      ) : (
                        <div>
                          <span className="inline-flex items-center gap-1 text-xs font-semibold text-destructive bg-destructive/10 border border-destructive/50 px-2.5 py-1 rounded-full">
                            <XCircle className="w-3.5 h-3.5" /> Failed
                          </span>
                          <p className="text-[10px] text-red-400 mt-1 italic">
                            Parsing failed
                          </p>
