                    {/* Actions */}
                    <div
                      className="col-span-3 flex items-center justify-end gap-2"
                      onClick={(e) => e.stopPropagation()}
                    >
                      {(doc.status === "ready" ||
                        doc.status === "processed") && (
                        <>
                          <button className="flex items-center gap-1 text-xs font-medium text-primary bg-primary/10 border border-primary/50 px-2.5 py-1.5 rounded-lg hover:bg-primary/20 transition-colors">
                            <BarChart2 className="w-3 h-3" /> View Metrics
                          </button>
                          <button className="flex items-center gap-1 text-xs font-medium text-orange-600 bg-orange-50 border border-orange-200 px-2.5 py-1.5 rounded-lg hover:bg-orange-100 transition-colors">
                            <ShieldAlert className="w-3 h-3" /> View Red Flags
                          </button>
                        </>
                      )}
                      <button
                        onClick={() => setDeleteDoc(doc)}
                        className="p-1.5 text-muted-foreground hover:text-destructive rounded-lg hover:bg-destructive/10 transition-colors"
                        title="Delete"
                      >
                        <MoreVertical className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>

            {/* Footer */}
            {filteredDocs.length > 0 && (
              <div className="flex items-center justify-between px-6 py-3 border-t border-border-subtle bg-surface/50">
                <span className="text-xs text-muted-foreground">
                  Showing 1ΓÇô{filteredDocs.length} of {filteredDocs.length}{" "}
                  documents
                </span>
                <div className="flex items-center gap-1">
                  <button className="p-1.5 text-muted-foreground hover:text-foreground rounded-lg hover:bg-surface">
                    <ChevronLeft className="w-4 h-4" />
                  </button>
                  <span className="w-8 h-8 rounded-lg bg-primary text-white text-xs font-bold flex items-center justify-center">
                    1
                  </span>
                  <button className="p-1.5 text-muted-foreground hover:text-foreground rounded-lg hover:bg-surface">
                    <ChevronRight className="w-4 h-4" />
                  </button>
                </div>
              </div>
            )}
          </div>
        ) : (
          /* Grid view */
          <div className="flex-1 overflow-y-auto">
            {filteredDocs.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-24">
                <div className="w-16 h-16 rounded-full bg-surface flex items-center justify-center mb-4 border border-border-subtle">
                  <Search className="w-6 h-6 text-muted-foreground" />
                </div>
                <h4 className="text-foreground font-semibold mb-1">
                  No documents found
                </h4>
                <p className="text-muted-foreground text-sm">
                  Adjust your filters or search query.
                </p>
              </div>
            ) : (
              <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">
                {filteredDocs.map((doc) => (
                  <div
                    key={doc.id}
                    className="bg-card border border-border rounded-xl p-4 shadow-sm hover:shadow-md transition-all cursor-pointer group hover:border-primary/50"
                    onClick={() => setSelectedDoc(doc)}
                  >
                    <div className="flex items-start justify-between mb-3">
                      <div className="w-12 h-12 rounded-xl bg-destructive/10 border border-red-100 flex items-center justify-center shrink-0">
                        <FileText className="w-6 h-6 text-destructive" />
                      </div>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setDeleteDoc(doc);
                        }}
                        className="p-1 text-muted-foreground hover:text-destructive rounded-lg hover:bg-destructive/10 opacity-0 group-hover:opacity-100 transition-all"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                    <h4 className="text-sm font-semibold text-foreground truncate mb-1 group-hover:text-primary transition-colors">
                      {doc.name}
                    </h4>
                    <p className="text-xs text-muted-foreground mb-3">
                      {doc.pages} pages ┬╖ {formatSize(doc.size_bytes)}
                    </p>

                    {/* Status with mini progress */}
                    {doc.status === "processing" ? (
                      <div>
                        <div className="flex items-center justify-between mb-1">
                          <span className="text-[10px] font-semibold text-primary">
                            Processing
                          </span>
                          <span className="text-[10px] text-muted-foreground">
                            {doc.progress || 0}%
                          </span>
                        </div>
                        <div className="h-1.5 bg-surface rounded-full overflow-hidden">
                          <div
                            className="h-full bg-primary rounded-full transition-all duration-500"
                            style={{
                              width: `${doc.progress || ((doc.processing_step || 1) / 5) * 100}%`,
                            }}
                          />
                        </div>
                      </div>
                    ) : doc.status === "ready" ||
                      doc.status === "processed" ? (
                      <span className="inline-flex items-center gap-1 text-xs font-semibold text-success bg-success/10 px-2 py-0.5 rounded-full">
                        <CheckCircle2 className="w-3 h-3" /> Ready
                      </span>
                    ) : (
                      <span className="inline-flex items-center gap-1 text-xs font-semibold text-destructive bg-destructive/10 px-2 py-0.5 rounded-full">
                        <XCircle className="w-3 h-3" /> Failed
                      </span>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Side panel */}
      {selectedDoc && (
        <DocumentDetailPanel
          doc={selectedDoc}
          onClose={() => setSelectedDoc(null)}
        />
      )}

      {/* Delete modal */}
      {deleteDoc && (
        <DeleteConfirmModal
          doc={deleteDoc}
          onClose={() => setDeleteDoc(null)}
          onConfirm={() => handleDelete(deleteDoc.id)}
        />
      )}
    </div>
  );
}

